import{C as e,L as t,S as n,V as r,X as i,_ as a,b as o,x as s}from"./vue-DJZSiPbu.js";import{r as c}from"./app-a38lz1Y_.js";var l=JSON.parse(`{"path":"/read/continued/C1.html","title":"1 吾等乃惠惠盗贼团 | 阅读","lang":"zh-CN","frontmatter":{"title":"1 吾等乃惠惠盗贼团","description":"「寻找职业为盗贼的队员。仅限为了正义而做出犯罪行为也在所不辞，具备此等干劲者。」 由于崇拜在艾莉丝感谢祭期间遇见的银发盗贼团，惠惠（自以为）为了协助他们而组成了盗贼团。但其最关键的团员，有总是独处的悠悠、不谙世事的公主爱丽丝、阿克西斯教的祭司赛西莉等等，全都是些问题儿童……尽管如此，惠惠还是毫不气馁，为了惩戒黑心贵族而致力于盗贼活动，事情却有了意想不到...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"1 吾等乃惠惠盗贼团\\",\\"image\\":[\\"\\"],\\"dateModified\\":null,\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://ajtn123.github.io/konosuba/read/continued/C1.html"}],["meta",{"property":"og:site_name","content":"素晴"}],["meta",{"property":"og:title","content":"1 吾等乃惠惠盗贼团"}],["meta",{"property":"og:description","content":"「寻找职业为盗贼的队员。仅限为了正义而做出犯罪行为也在所不辞，具备此等干劲者。」 由于崇拜在艾莉丝感谢祭期间遇见的银发盗贼团，惠惠（自以为）为了协助他们而组成了盗贼团。但其最关键的团员，有总是独处的悠悠、不谙世事的公主爱丽丝、阿克西斯教的祭司赛西莉等等，全都是些问题儿童……尽管如此，惠惠还是毫不气馁，为了惩戒黑心贵族而致力于盗贼活动，事情却有了意想不到..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}]]},"readingTime":{"minutes":304.68,"words":91405},"git":{"createdTime":1784183213000},"autoDesc":true,"filePathRelative":"read/continued/C1.md","headers":[]}`),u={name:`C1.md`};function d(c,l,u,d,f,p){let m=r(`ImageView`);return t(),o(`div`,null,[l[4]||=a(`p`,null,`「寻找职业为盗贼的队员。仅限为了正义而做出犯罪行为也在所不辞，具备此等干劲者。」`,-1),l[5]||=a(`p`,null,`由于崇拜在艾莉丝感谢祭期间遇见的银发盗贼团，惠惠（自以为）为了协助他们而组成了盗贼团。但其最关键的团员，有总是独处的悠悠、不谙世事的公主爱丽丝、阿克西斯教的祭司赛西莉等等，全都是些问题儿童……尽管如此，惠惠还是毫不气馁，为了惩戒黑心贵族而致力于盗贼活动，事情却有了意想不到的发展！`,-1),l[6]||=a(`p`,null,`祝贺惠惠荣获角色人气票选第一名的纪念企画，终于书籍化！`,-1),e(m,{src:`/images/C1/00.avif`,alt:`封面`,width:`850`,height:`1257`}),e(m,{src:`/images/C1/21.avif`,alt:`扉页`,width:`850`,height:`1257`}),l[7]||=a(`h2`,{id:`彩页`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#彩页`},[a(`span`,null,`彩页`)])],-1),e(m,{src:`/images/C1/11.avif`,alt:`彩页插图 1`,width:`850`,height:`650`},{default:i(()=>[...l[0]||=[a(`p`,null,[n(`惠惠`),a(`br`),n(` 　「吾乃惠惠！清白正直又妥当执行窃盗业务，为世间、为人类有所贡献的盗贼团之领导者！」`)],-1)]]),_:1}),e(m,{src:`/images/C1/05.avif`,alt:`彩页插图 2`,width:`850`,height:`650`},{default:i(()=>[...l[1]||=[a(`p`,null,[n(`悠悠`),a(`br`),n(` 　「我只是想说，虽然不知道你想做什么，不过我也想参一脚……」`)],-1),a(`p`,null,[n(`爱丽丝`),a(`br`),n(` 　「请务必让我加入！也让我成为两位的伙伴吧！」`)],-1),a(`p`,null,[n(`克莉丝`),a(`br`),n(` 　「我的运气明明应该很好才对啊，为什么老是碰到这种很搞笑的状况呢……」`)],-1),a(`p`,null,[n(`赛西莉`),a(`br`),n(` 　「我是这间教堂位阶最高的人，也是阿克西斯教团的美女祭司，名叫赛西莉。不用客气，叫我赛西莉姐姐就可以了。」`)],-1)]]),_:1}),e(m,{src:`/images/C1/01.avif`,alt:`彩页插图 3`,width:`850`,height:`650`},{default:i(()=>[...l[2]||=[a(`p`,null,[n(`惠惠`),a(`br`),n(` 　「那个，你们两个的关系相当密切吗？是从什么时候变成这种关系的啊？」`)],-1),a(`p`,null,[n(`克莉丝`),a(`br`),n(` 　「惠惠，不是啦！我们两个开始一起当盗贼也是最近的事情，我之前也说过了啊，助手老弟在我心目中什么都不是！我只是把他当成普通朋友，对他并没有特别的感觉！」`)],-1),a(`p`,null,[n(`和真`),a(`br`),n(` 　「等一下，你们两个在我不在的时候都聊了些什么啊？为什么我要在不知情的状况下被甩掉啊？」`)],-1)]]),_:1}),e(m,{src:`/images/C1/18.avif`,alt:`目录`,width:`850`,height:`1257`}),l[8]||=a(`h2`,{id:`序章`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#序章`},[a(`span`,null,`序章`)])],-1),e(m,{src:`/images/C1/22.avif`,alt:`章节标题`,collapsed:``,width:`850`,height:`1257`}),l[9]||=s(`<p>和那个人一起去烟火大会的那天晚上。</p><p>就在无法遵守和那个人的约定，有点失落的我，拖着沉重的步伐走在回家路上的时候。</p><p>我路过一户名叫安岱因，风评不佳的贵族家的宅邸。</p><p>在那里，有两个看起来就很可疑的人从远方望着那栋宅邸。</p><p>看见那熟悉的面具，我的心脏开始狂跳。</p><p>怎么搞的，难道我有这么好拐吗？</p><p>我还以为自己是个更守身如玉，更能自持的人呢……</p><p>我下定决心，向那两个人搭话。</p><p>「——请、请问……前面那两位，该不会是银发盗贼团吧？」</p><p>被我从背后这么一叫，那个人抖了一下。等我回过神来，我已经在用拔高的声音向他自我介绍了。</p><p>面对止不住嘴角的笑意的两人，我问了一直很好奇的事情。</p><p>「你们两位之所以潜入王城，是因为公主殿下手上有个危险的神器，两位想要保护她的人身安全对吧？」</p><p>对于我的发问。</p><p>『是啊，就是这样。我们是坊间所谓的义贼。平常站在庶民这边，但即使对方是公主，知道年纪尚小的少女曝身于危险之中，我们岂能坐视不管。只要有人不知该如何是好，无论是贵族的宅邸还是王城，任何地方我们都会潜入其中。这就是我们面具盗贼团的作风。』</p><p>或许细节有点不同，但那个人斩钉截铁地这么说了。</p><p>『你叫惠惠对吧？其实，我们锁定了沈眠于这间宅邸的某样东西。为了人类的未来，那是不可或缺的东西。偷窃这种行为确实不可取。但是，对于我们而言，即使国家悬赏要拿下我们的人头，这也是必须去做的事情。』</p><p>他面具底下的眼睛蕴藏着坚强的决心，而且不知为何，光是看着就让我觉得似曾相识。</p><p>我目不转睛地盯着这双眼睛看，听着他们接下来要说的话。</p><p>『我们接下来要潜入那间宅邸偷东西，借此取得对付魔王军的王牌之一。如果你想报警的话我们也不会阻止……不过，希望你相信我们，我们是为了人类才这么做的。』</p><p>也就是说，他们两位即使是在被悬赏高额奖金的现在，不仅与魔王军为敌，甚至不惜与全人类为敌，也要为了世界而继续采取行动。</p><p>明明都在做这种大事，而且明明接下来还有重要的工作等着他们去做。</p><p>他们却像是相伴已久的搭档似的，开心地互动着。</p><p>看着两人这样的互动，不知为何让我的心头一紧。</p><p>向他们道别之后，我依依不舍地一次又一次回头看向他们，最后假装离开现场。</p><p>那一天。</p><p>我下定决心，要暗中协助仅以两名成员努力活动的他们——</p><h2 id="第一话-新锐的盗贼团" tabindex="-1"><a class="header-anchor" href="#第一话-新锐的盗贼团"><span>第一话 新锐的盗贼团</span></a></h2>`,27),e(m,{src:`/images/C1/02.avif`,alt:`章节标题`,collapsed:``,width:`850`,height:`1257`}),l[10]||=s(`<h3 id="_1" tabindex="-1"><a class="header-anchor" href="#_1"><span>1</span></a></h3><p>有个名叫阿克塞尔的城镇。</p><p>新进冒险者为了寻求同伴，都会聚集到这个城镇来。</p><p>同时，这个地方也因为治安非常良好而闻名。</p><p>在这样的阿克塞尔的冒险者公会当中——</p><p>「住……住手——！你在做什么！」</p><p>我遭受到不当的暴力对待。</p><p>拿着我张贴在公布栏上的告示，公会的柜台小姐对我说：</p><p>「居然还问我是在做什么！这是冒险者们募集小队成员用的公布栏，想找玩伴的话请去别的地方！」</p><p>「什么玩伴，没礼貌耶！我这是在找队友无误，如果你对我贴告示的地方有意见的话就说啊，我洗耳恭听！」</p><p>面对像是在炫耀似的挺出胸部的巨乳美女柜台小姐，我也不甘示弱，示意要她把募集告示交出来。</p><p>「如果不是在玩就更糟糕了！我有意见的不是贴告示的地方，而是关于募集内容啊！」</p><p>柜台小姐将告示递到这样的我眼前，念出写在上面的文章。</p><p>「『征求盗贼职业队员。仅限为了正义而犯罪也在所不辞，具备此等干劲者。主要工作内容为袭击贵族宅邸等等……』」</p><p>听见这些，在附近围观的冒险者们都以怜悯的眼神看向我。</p><p>「……没办法了。我原本只想找职业是盗贼的队员，不过其他职业也没关系啦。我重写就是了。」</p><p>「问题不在那里啊！我的意思是请不要透过公会的公布栏募集和你一起犯罪的同伴！」</p><p>——事情发生在之前举办艾莉丝女神感谢祭的时候。</p><p>那时，我遇见了一直很崇拜的盗贼团。</p><p>以布条罩住口鼻，一头银发的盗贼团头目。</p><p>还有只看一眼就能知道不是简单角色，戴着一副帅气面具的神秘男子。</p><p>那个被称作头目的银发人士还无所谓，该怎么说呢，感觉是个活泼、诚恳，让人很有好感的人。</p><p>问题是另一个人，面具男。</p><p>那个戴着巴尼尔面具复制品的人，给我一种该说是不像陌生人的感觉吧，明明是第一次见面，我却感觉到某种能够令我放心的感情。</p><p>而且，又是盗贼团又是义贼又是面具的。</p><p>——简直太迷人了。</p><p>居然能够凑齐如此触动我心弦的要素，肯定不是简单角色。</p><p>老实说，我其实很想加入那个盗贼团，但是很遗憾的，我并没有盗贼的技术。</p><p>「——所以，身为他们的支持者之一，我决定擅自成立那个盗贼团的附随组织，聚集人力，协助他们的义举。」</p><p>「要是你真的成立了那种愚蠢的团体我就悬赏捉拿你们喔。」</p><p>募集告示被柜台小姐没收之后，我环视整个公会。</p><p>既然不准我张贴告示，我就只能个别挖角了，但是听见我们刚才的对话的冒险者们都纷纷闪避着我的视线。</p><p>我走向附近一位看起来职业应该是盗贼的大哥，为了让他卸下心防而换上最灿烂的微笑对他说：</p><p>「这位看起来很闲的大哥，可以耽误你一下吗？」</p><p>「抱歉啊，我现在正忙着数桌子的木纹，晚点再说吧。」</p><p>那位大哥非常做作地数起木纹来，害我忍不住揪住他。</p><p>「你明明直到上一秒都还一副很闲的样子，现在到底是有什么不满的啦！」</p><p>「别这样，不要把我牵扯进去！为什么谁不好挑偏偏挑上我啊，你的队上不是有那个方便又好用的家伙吗！那个家伙也有盗贼技能不是吗！」</p><p>「我当然第一个就拜托他了。但是，那个男人居然说等到季节变得再凉爽一点再陪我玩。看来，他似乎不认为我是认真想成立支持那个盗贼团的团体。」</p><p>「那当然了，说要支持被悬赏的盗贼团啊，人家只会觉得你到底在开什么玩笑吧。」</p><p>听那位大哥如此回应，我用力拍了一下桌子。</p><p>「那个盗贼团为了拯救人类的未来，即使被人在背后指指点点，也还是日夜努力采取行动！看来我必须先从这一点开始向你彻底厘清才行了！」</p><p>「别这样，我不想听那些，也不想和你扯上关系！拿去，这盘我拿来配酒的花生给你，你去找别人吧！」</p><p>……天啊。</p><p>我不但还帮不上自己崇拜的那些人的忙，甚至得先从解开世人对他们抱持的误会开始才行吗……</p><p>一手拿着装着花生的盘子，我一面啃着花生，一面环顾四周……</p><p>在众人依然闪避着我的视线的同时，我忽然感觉到背后有人看着我。</p><p>我转头盯着那边看，只见视线的主人发现我在看她之后连忙低下头去，但不久之后又以有所期待的眼神不断偷瞄我。</p><p>……</p><p>「那位看起来职业应该是盗贼的大姐，可以耽误你一下吗？」</p><p>「惠惠，你刚才有发现我在看你对吧！」</p><p>见我向附近的大姐搭话，视线的主人，也就是悠悠便踢开椅子站了起来。</p><p>「你那种不敢主动找人讲话却希望人家理你的视线真是有够烦的！有事情想说的话你就直接开口啊！」</p><p>「别这样！我知道了，我开口就是了，别拉我的头发！」</p><p>我扑向依然难搞的悠悠之后，她便带着下定决心的表情说：</p><p>「我只是想说，虽然不知道你想做什么，不过我也想参一脚……」</p><p>听说最近经常和一些怪人混在一起的悠悠前所未见地主动说出这种积极的发言。</p><p>大概是和那些怪人混在一起，让这个孩子有所成长了吧。</p><p>不过……</p><p>「事到如今你还在说什么啊，悠悠可是吾之盗贼团的副团长喔。而且名字也已经列在名册上了。」</p><p>「你在说什么啊，我可没听说喔！应该说，你从刚才开始就一直向人搭话，原来是在找人加入那种不正经的团体吗？」</p><p>悠悠如此惊叫出声，让我不禁大声叫骂。</p><p>「什么叫不正经的团体啊！这可是一个清白正直又妥当执行窃盗业务，为世间为人类有所贡献的盗贼团！」</p><p>「我听不懂你在说什么！我完全只有不祥的预感所以还是算了！」</p><p>正当我和悠悠在争执的时候，我原本打算上前搭话的那位大姐连忙离开了公会。</p><p>我抓住打算逃跑的悠悠的一只手之后说：</p><p>「居然害怕了，你这样还称得上是红魔族吗！真是的，都怪你大吵大闹的，大家都开始警戒了。够了喔，你别再闹别扭了，我们上街找团员去！我们的新团员也等于是你的伙伴。乖，你可以交到新朋友耶。」</p><p>「别以为只要说出可以交到新朋友我就会愿意去做任何事，你如果这样想的话可是大错特错啊啊啊————！」</p><h3 id="_2" tabindex="-1"><a class="header-anchor" href="#_2"><span>2</span></a></h3><p>「——你看，那个人怎么样？他的长相看起来就很适合当盗贼。」</p><p>「惠惠，嘘——！你太大声了！那个大叔的长相看起来是很凶悍没错，但他是一般老百姓，又不是冒险者！别看那个人了，你觉得那个看起来年纪和我们差不多的人如何……」</p><p>「他才是真正的一般老百姓吧。这是在找团员，不是在找朋友喔！」</p><p>在阿克塞尔的大街上。</p><p>我和推三阻四最后还是跟过来的悠悠一起坐在大街旁的长椅上，观察着往来的人群。</p><p>没错，目的是为了找到适合的人才就立刻挖角。</p><p>不过，我和悠悠从刚才开始就一直意见相左，到现在都还没有向任何人搭话。</p><p>「啊，那个女孩怎么样？虽然她把长袍的兜帽戴上了，看不到长相，不过年纪看起来好像和我们差不了多少，而且腰际还挂着剑，应该不是一般老百姓吧？」</p><p>悠悠指着一个罩着朴素长袍，戴上兜帽的娇小少女这么说。</p><p>虽然看不到她的发色，不过从兜帽底下露出来的眼睛是充满透明感的澄澈蓝色……</p><p>「等一下，为什么那个孩子会一个人出现在这个镇上啊！」</p><p>「你、你怎么了，惠惠？你认识那个女孩吗？」</p><p>在我们的视线前方，那名戴上兜帽的少女似乎对身边的东西非常有兴趣，一面到处东张西望，一面到处乱晃，脚步看起来虚浮不稳，危险极了。</p><p>这时，串烧摊贩的大叔对那名少女说：</p><p>「前面的小妹妹，要不要来一串刚烤好的串烧啊？小妹妹长得这么可爱，叔叔算你便宜一点，现在一串只要一百万艾莉丝喔。」</p><p>「串烧……我没见过这种食物呢。一串一百万艾莉丝吗？那么，可以给我三串吗？」</p><p>说着，把大叔的玩笑话当真的少女从怀里拿出钱包之后……</p><p>「你在做什么啊！不可以在这种地方拿出那么多钱来！」</p><p>「咦？啊啊！你是惠惠小姐！」</p><p>我冲到那个一副理所当然的打算从钱包里拿出高额硬币的少女，也就是不知为何出现在这里的爱丽丝公主身边，抢走了她递给老板的硬币。</p><p>没有理会因为看见高额硬币而全身僵住的老板，我教训起爱丽丝。</p><p>「一百万艾莉丝是那个大叔的玩笑话，其实是一串一百艾莉丝的意思。哪个世界的串烧会那么贵啦。」</p><p>「是、是这样吗？因为我不懂行情……」</p><p>这时，原本僵在那边的老板一脸认真地递出串烧说：</p><p>「不，真的是一串一百万艾莉丝。小妹妹这么可爱，我算你三串一百万艾莉丝好了。」</p><p>「可以便宜我这么多吗？谢谢老板！」</p><p>「不可以相信他，这个大叔是知道你不谙世事所以想趁机敲你竹杠！拿去，三百艾莉丝！要是你还想诓骗无知少女的话就由我来对付你！」</p><p>——带着以正常价格买到串烧的爱丽丝，我们转移阵地来到附近的公园里。</p><p>「真是的，你为什么会一个人在那种地方乱晃啊？你的护卫在做什么？」</p><p>面对立刻把刚买到的串烧放进嘴里的爱丽丝，我再次这么问。</p><p>或许是第一次吃到这种庶民的食物，笑得一脸幸福的爱丽丝表示：</p><p>「护卫是什么意思？我叫依丽丝。你是不是把我当成别人了啊？话说回来……这种名叫串烧的食物还真好吃。这或许是我第一次吃这么温热的食物呢。两位不嫌弃的话，要不要也来一串呢？」</p><p>在如此装傻的同时，她还问我和悠悠要不要吃串烧。</p><p>看来她似乎希望我们用依丽丝这个假名叫她。</p><p>我拿起串烧之后说：</p><p>「这样啊……那么，依丽丝殿下在这种地方做什么呢？这里算是治安比较好的城镇没错，不过会出什么差错也很难说喔。」</p><p>「请不要叫我依丽丝殿下，叫我依丽丝就可以了……呵呵，其实，不久之前我曾经偷偷跑来这个城镇玩。那个时候我没能见到兄长大人，不过却结识了一位很有趣的人士……这让我知道世间还有很多很奇特的人，所以我才会像这样熘出来学习社会经验。」</p><p>她突然冒出这番非常不得了的发言，害我把吃进嘴里的串烧喷了出来。</p><p>现在王都应该闹得天翻地覆了吧。</p><p>「来来，另外一位小姐也请用请用。」</p><p>「啊，谢谢你，依丽丝！你好，我叫悠悠……呐，惠惠。这个孩子金发碧眼的，难不成是贵族家的千金小姐吗？」</p><p>同样从爱丽丝手上接过串烧的悠悠战战兢兢地将串烧拿到嘴边，同时这么问我。</p><p>「不，我是王都的绉绸盘商的孙女，依丽丝，并不是什么千金小姐。」</p><p>也不知道到底是在哪里受到谁的影响，爱丽丝冒出这种奇怪的说词。</p><p>绉绸盘商是什么东西啊？</p><p>「既然本人都如此坚称了，就当作是这么回事吧……不过这下可伤脑筋了，既然都发现依丽丝了，也不好就这样置之不理让她落单……」</p><p>再怎么说她也是一国的公主殿下，总不能在发现她之后还丢下她一个人不管。</p><p>这时，见我如此烦恼，拿着串烧的爱丽丝歪着头问道：</p><p>「这么说来，你们两位又在做什么呢？」</p>`,118),e(m,{src:`/images/C1/16.avif`,alt:`插图`,width:`850`,height:`1257`}),l[11]||=s(`<p>听爱丽丝天真地这么问，我瞬间烦恼了一下是不是应该说真话。</p><p>可是，我记得这个孩子对那个盗贼团的印象应该也不差才对。</p><p>「其实，我们打算成立银发盗贼团的下层组织。」</p><p>「那是什么意思？也告诉我详情吧！」</p><p>怪了，她这么感兴趣是怎样，太出乎意料了。</p><p>「没有啦，我只是想擅自号称义贼银发盗贼团的下层组织、擅自募集同伴、擅自支持他们，只是想成立一个这样的团体罢了。」</p><p>「听起来好像很有趣的样子！想加入那个组织的话需要通过什么测试吗？」</p><p>见爱丽丝的反应依然如此热切，我为了让她回心转意，摇了摇头说：</p><p>「现在是怎样，难道你想加入吗？不可以喔，这不是儿戏。我们要建设秘密基地作为吾等之活动据点、扩大势力等等，要做的事情有很多。想当然尔，团员也必须要相当努力工作才行。」</p><p>「秘密基地！」</p><p>听我如此劝说，爱丽丝不知为何眼睛一亮。</p><p>「还、还有……不仅如此，为了惩治黑心贵族，在我们的设想范围内可能也得采取一些不合法的手段……」</p><p>「惩治黑心贵族！」</p><p>听我如此劝说，爱丽丝不知为何眼睛变得更亮了。</p><p>「请务必让我加入！也让我成为两位的伙伴吧！」</p><p>也不知道是哪一点触动了她的心弦，爱丽丝脸色泛红，握起拳头。</p><p>「呐，惠惠，既然她都这么有干劲了，让她加入也没关系吧？我……我可不是因为有年纪相近的女生成为同伴会很开心才这么说的喔。」</p><p>看见这样的她，不知为何连悠悠也积极想让这个孩子入团。</p><p>要是让公主殿下加入这么危险的组织，万一哪天东窗事发了，我会不会被处以绞刑啊？</p><p>应该说，将我想支持的银发盗贼团列为悬赏对象的，根本就是这个孩子身边的人耶。</p><p>「既、既然你都说到这个份上了，那好吧。不过，我们要做的事情也不是儿戏，所以要请你接受入团测试。经过测试，如果我认为你是值得入团的人才，并且成绩优异的话，我就给予你吾等盗贼团之左手的称号。」</p><p>「呐，惠惠，我姑且问一下，这样的话右手是谁？我只是让你借用我的名字而已喔，不要擅自把我列为干部喔！」</p><p>不顾听了我的发言而感到害怕的悠悠，爱丽丝的表情整个亮了起来。</p><h3 id="_3" tabindex="-1"><a class="header-anchor" href="#_3"><span>3</span></a></h3><p>——离开了城镇，来到熟悉的平原。</p><p>「依、依丽丝，你可以吗？那只蟾蜍比我们平常看到的还要大上不少喔！」</p><p>我们打算透过阿克塞尔最著名的怪物，同时也是我们的宿敌——蟾蜍，来测试爱丽丝的实力。</p><p>「我可以的！王族……不对，绉绸盘商一族可是很强的！」</p><p>绉绸盘商是不是和红魔族一样，是什么种族的名称啊？</p><p>爱丽丝面对与她对峙的蟾蜍，拔出插在腰际的剑，摆出架势。</p><p>「『Extelion』！」</p><p>然后在如此大喊的同时，在距离明明还很远的状态下挥了剑。</p><p>那把尺寸和娇小的爱丽丝不太相称，装饰华美的长剑，与又长又大的外观正好相反，轻盈地划过空气——</p><p>接着便毫无预警地，将朝我们跳过来的蟾蜍砍成两半。</p><p>「「咦！」」</p><p>在忍不住惊叫出声的我和悠悠的守候之下，爱丽丝满意地把剑收回剑鞘。</p><p>「惠惠小姐，如何？这样算是通过测试了吗？」</p><p>「咦？这个嘛……这还是测试的第一阶段！你刚才打倒的蟾蜍，在这附近是任何装备齐全的冒险者都能够猎杀的怪物！能够一招打倒那种怪物只是理所当然！」</p><p>「自己在对付那种蟾蜍的时候明明曾经被整个人吞进肚子里还敢说……」</p><p>我假装没听见这道从背后传来的声音，决定给爱丽丝更严苛的考验——</p><p>「——『Extelion』！」</p><p>「请等一下，你从刚才开始就一直用的那招是什么啊！再怎么说未免也太强了吧！为什么有办法反过来一击打倒一击熊那种大咖啊！」</p><p>因为不知道爱丽丝的极限到底在哪里，我不断提高讨伐怪物的难度。</p><p>「这招是只有得到我们家代代相传的圣剑所认同的人才可以使用，能够发出强烈斩击的必杀技！」</p><p>「那该不会是据说原本是勇者所持有，传说中的……算、算了，还是不要想太多吧。」</p><p>王族最有名的一件事就是招婿拥有强大力量的勇者，吸收其血统。</p><p>所以，名列王族之中的人都继承了这样的素养，多半都强到犯规……</p><p>「不过，如果是这样的话，就只是你的武器在强而已吧。盗贼团有很多时候要来硬的，所以不能让不够强的人加入。我想看的是你真正的实力。请你确实展现出来给我看。」</p><p>「呐，惠惠，我看依丽丝肯定比我们还强吧？你也差不多该承认了吧？」</p><p>悠悠一边这么说，一边用力拉我的衣服，但是如果现在轻易承认这种事情的话，我就没有立场可言了。</p><p>「那么，我去打倒那边的那群怪物吧，而且不用圣剑。」</p><p>正当我和悠悠在交头接耳的时候，爱丽丝指着远方的怪物，并且这么说……</p><p>「等等，那是一整群的哥布林耶！不可以，那种很好赚的怪物附近多半都跟着一种名叫初学者杀手的狠角色……！」</p><p>尽管我如此警告，爱丽丝已经对着哥布林举起手来——！</p><p>「『Sacred Lightning Blare』——！」</p><p>在爱丽丝如此大喊的同时。</p><p>一道白光在哥布林群的中央闪了一下，白色的闪电伴随着暴风肆虐，扫荡了一切——！</p><h3 id="_4" tabindex="-1"><a class="header-anchor" href="#_4"><span>4</span></a></h3><p>回到阿克塞尔之后，我用力拍了一下手说：</p><p>「好了，第一次测试就此结束。以新人而言，我承认你还算有点本事。不过因为我们是盗贼团，并没有那么需要战斗力就是了。所以说，并不是强者的地位就会比较高。」</p><p>「等一下，惠惠，你的说法跟刚才不一样吧！你不是说有时候要来硬的所以不能让不够强的人加入吗！」</p><p>见识到爱丽丝的实力之后一直有点呆若木鸡的悠悠现在才回过神来，如此对我抗议。</p><p>「吵、吵死了，第一次测试我都已经让她顺利过关了，这样不就好了吗！」</p><p>「还说什么第一次测试，怎么我就没有！应该说，这个孩子怎么想都比我们还要……」</p><p>「住、住口——！不可以继续说下去，一旦认输就全盘结束了！」</p><p>老实说，我太小看王族的力量了。</p><p>我是有听说王族和贵族很多都是天生就很有才能的人，但我没想到居然强到这种地步。</p><p>再说了，让这个孩子自己去打倒魔王不就好了吗？</p><p>「可是，没想到居然连在附近观望的初学者杀手也一起收十掉了，依丽丝那招魔法也太厉害了吧。再说了，就连身为红魔族的我都没听过那招魔法呢……」</p><p>「那是王家……不对，是绉绸盘商代代相传的魔法之一。听说是传说中的勇者最拿手的原创魔法，能够发出蕴含神圣力量的闪电。」</p><p>有关绉绸盘商的谜团越来越扑朔迷离了。</p><p>「话说回来，第二次测试要做什么呢？我对体能很有自信，无论是怎样的测试我都愿意挑战！」</p><p>看见干劲十足的爱丽丝，我苦思不已，心想到底该如何是好。</p><p>要是擅自让公主殿下加入盗贼团的话，我可以想像得到穿帮之后会闹出怎样的骚动。</p><p>老实说，我原本是想对她鸡蛋里挑骨头，好让她死心的……</p><p>这时，悠悠忽然说：</p><p>「继续测试你的体能也没有意义，不如测试学力或一般常识如何？不过，依丽丝看起来家教就很好，学力应该也还不错吧。」</p><p>「就是这个！」</p><p>听见悠悠随口说出的这番话，我用力点头。</p><p>对方是接受英才教育的公主殿下。</p><p>所以学力测试当然也没有意义，不过一般常识就另当别论了。</p><p>「盗贼需要的不是高强的战斗能力。此外，智力当然也是越高越好，但最重要的还是常识！依丽丝的常识水准有多高，就由本小姐来测试一下！」</p><p>「在阿克塞尔最没常识的惠惠居然说要测试别人的常识，到底是在开什么玩笑……好痛、好痛！」</p><p>在我因为悠悠乱插嘴而拉扯她的头发时，爱丽丝尽管显得有些困惑，却还是握起拳头对我说：</p><p>「我、我可以的！我也经常像这样熘出来探索城镇，应该已经学到了不少常识才对！请务必开始进行那项测试！」</p><p>——先从结果说起好了，实在是糟糕到不行。</p><p>「小妹妹，那不是可以直接吃的东西，要先剥皮再吃里面的部分。」</p><p>我试着叫爱丽丝去商店街随便买点东西，结果她好像是第一次看见还没剥皮的水果，拿起刚买来的芒果，在准备直接啃下去的时候停下了动作。</p><p>被老板这么一叮咛，红着脸的爱丽丝不知所措地看向我们。</p><p>真是的，不谙世事的公主殿下就是这样……</p><p>「真拿你没办法，反正你之前一定只吃过人家把皮剥干净装在盘子里面的水果对吧？现在就由我来教你一般的常识。水果这种东西呢，首先要把皮剥掉，吃里面的果肉，然后把种子炒熟当点心吃。剥下来的果皮要煮软了再拿来吃。」</p><p>「惠惠也偏离一般常识了！正常来说果皮和种子都会丢掉好吗！」</p><p>悠悠出乎意料的吐嘈，害得我心目中的常识瞬间差点瓦解。</p><p>「才、才没有这么回事呢。种子炒干了之后会变得像葵花子一样好吃，果皮只要细火慢炖之后也能吃！悠悠在红魔之里才是走得最偏的啊。真是的，不懂常识的人就是这样……」</p><p>「你给我等一下——！只论我们三个的话，我自认是最有常识的好吗！等等，依丽丝，还没有付钱不可以咬下去！」</p><p>「对、对不起！因为平常都是我的随从会自动付钱……！」</p><p>没想到意外暴露出我的弱点，这样也不能继续测试下去了。</p><p>嗯嗯……无论以战力而言还是以人才而论，爱丽丝都很优秀没错……</p><p>「惠惠，我不知道你是在犹豫什么，不过你也差不多该让依丽丝加入了吧？该怎么说呢，被排挤在小圈圈之外是非常难过的事情喔……」</p><p>「悠悠说这种话听起来超沉重的，别这样！我知道了啦，这项测试就先暂缓吧。不过这只是先让你暂时入团试用一下喔。谁知道你那些跟班发现这件事会说什么。」</p><p>听见我因为悠悠的劝说而如此表示，爱丽丝的表情一亮。</p><p>「事情就是这样，暂时入团的你是我们当中地位最低的基层人员。我这个团长说什么你都得服从喔。」</p><p>听我这么说，悠悠像是忽然想起了什么似的表示：</p><p>「这么说来，为什么惠惠不知不觉间就变成团长了啊？我这么说并不是因为自己想当团长，只是身为惠惠的竞争对手却被你擅自当成部下，感觉好像输给你了，让我很不舒服。」</p><p>「你这个难搞的家伙又在说这种话了。那还用说吗，当然是因为我们当中最强最能干最成熟的就是我。既然如此，也只能由这样的我来负责统领大家了啊。」</p><p>听了我这番话，两名手下似乎无法接受这个理由，分别露出微妙的表情。</p><p>「王族……绉绸盘商可是很强的喔！不然我们来打一场如何？」</p><p>「战斗方面……要赢过你们两个或许是有点困难，但我们当中最成熟的应该是我吧？常识也是我比较丰富，身高也是我最高。」</p><p>面对这两个难搞的手下，我只能不以为然地摇摇头。</p><p>「像你们这么轻易动气，幼稚的人就是这样。而且，最成熟的一个肯定是我没有错喔。毕竟……」</p><p>停顿了一下之后。</p><p>「我都已经对那个男人说了，问他今晚要不要来我的房间玩。」</p><p>我坦白说出不久之前和那个人约定好的事情……</p><p>「「咦咦咦咦咦咦咦！」」</p><p>「喂！你、你们在做什么，住手！快住手——！请你们放手，不准拉我的长袍！」</p><p>「惠惠，这是怎么回事！那个男人是指和真先生对吧？你你、你打算和他跨越最后一道界线吗！」</p><p>「你你、你邀请兄长大人去你的房间吗？邀请那个无论是任何人随便问一下都很有可能随便跟去的兄长大人吗？身为淑女，惠惠小姐未免太不检点了，我这个兄长大人的妹妹无法坐视你们发展那种靡烂的关系！」</p><p>我推开揪住我不放的两人，整理了一下凌乱的长袍衣襟之后说：</p><p>「我已经是可以结婚的年纪了。应该说，年轻男女在一个屋檐下一起生活，事到如今就算变成那种关系也没什么好奇怪的吧？」</p><p>两人从我这番从容的发言中得知了彼此之间的层次差距，变得脸色苍白，脚步还踉跄了一下。而我对这样的两人表示：</p><p>「那么，团长就是我了，你们没有异议吧？」</p><h3 id="_5" tabindex="-1"><a class="header-anchor" href="#_5"><span>5</span></a></h3><p>展现出压倒性的上下关系之后，我带着她们两个来到原本的目的地，然而——</p><p>「本小姐都已经这么低声下气地求你了，你真的不肯通融一下吗？」</p><p>「办不到。」</p><p>房地产仲介的老板冷淡的如此秒答。</p><p>「你到底有什么不满意的啊！难道你信不过击退了众多魔王军干部的本小姐吗？这么值得期待有朝一日发达之后能够付出钱来的魔法师，除了我之外没有第二个了！」</p><p>「无论你怎么说，办不到的事情就是办不到！既没有东西可以抵押，也没有现金，却想要我把这个城镇最大的房子租给你，脸皮再怎么厚也该有个限度吧！而且你的小队打下的战果确实非常丰硕，却也被列为最有可能灭团的小队之一，你最好认清这一点！」</p><p>「你、你说什么！这么说的人是什么来头，竟敢给我们如此不当的评价！」</p><p>来到阿克塞尔的房地产仲介的我们，原本是为了确保活动据点才像这样来找老板商量，受到的却是这般对待。</p><p>「总之，三万艾莉丝连押金都不够付。我干这行已经很久了，拿出这点钱就想叫我交出镇上最好的房子的人我倒是头一次见到。」</p><p>「唔……没办法了，这原本是我为了应急而留下来的私房钱，不过……」</p><p>说着，我又在桌上多放了我珍藏的一万艾莉丝，结果被老板用食指弹飞。</p><p>「混帐东西，竟敢如此对待我好不容易才存下来的私房钱！」</p><p>「因为就算三万艾莉丝变成四万艾莉丝也无济于事啊！算我拜托你们，快点回去吧！」</p><p>就在这时。</p><p>我还在和老板唇枪舌战的时候，有人从背后拉了拉我的披风。</p><p>「呐，惠惠，再怎么说这样都太鲁莽了吧？应该说，你之前说要建设秘密基地还是活动据点什么的，原来是认真的啊。那个，有一个地方能够让朋友们聚在一起，随时都可以在那里休息，找一个这样的地方我是赞成，所以我们今天还是先回去，想办法筹钱吧。」</p><p>听悠悠这么说，我咬牙切齿地思考着到底应该怎么做。</p><p>「不好意思……这个城镇最大的房子要多少钱才租得起啊？」</p><p>这时，爱丽丝从我们背后探出头来，战战兢兢地这么问了老板。</p><p>「你们要这个城镇最大的房子的话，一个月要两百万艾莉丝。加上押金之类的，总共应该是五百万艾莉丝吧。」</p><p>五百万……</p><p>我轻轻把悠悠推向老板，然后说：</p><p>「……我们这边再加上她每天都叫你一声帅叔叔的权利，能不能再算我们便宜一点？」</p><p>「为什么我非得做这种事情不可啊！」</p><p>见悠悠打算掐我的脖子，我便进入迎击态势。这时，爱丽丝拍了拍我的背。</p><p>「怎么了，依丽丝？现在是谈判最关键的时候，不要妨碍我……」</p><p>说到这里，我倒抽了一口气。</p><p>「不好意思，这些钱够吗？」</p><p>爱丽丝递出来的，是面额惊人的艾莉丝纸币。</p><p>老板看见纸币也顿了一下，悠悠则是颜面抽搐，整个人僵住。</p><p>「……这、这个嘛，钱是非常够没错，不过想租房子还需要能够证明承租人的身分，以及值得信用的保证人……」</p><p>听老板语带歉疚地这么说，爱丽丝露出伤脑筋的表情表示：</p><p>「不好意思，这个可以当成我的身分证明吗？」</p><p>说着，她从胸口拉出项链……</p><p>「小人失礼了！如果是您的话要租什么房子都可以！当然也不会向您收取租金！我现在立刻就去拿钥匙出来，还请您在此稍候一下！」</p><p>老板一看见项链，便连忙冲进内场。</p><p>目送老板离开的悠悠一脸紧张地说：</p><p>「……呐，难不成依丽丝的家世其实非常显赫吗？」</p><p>「……她只是我们盗贼团的一介基层人员罢了。」</p><p>「是的，我是基层人员！」</p><p>看着被叫成基层人员不知为何还是一脸开心的爱丽丝，悠悠也乱了套。</p><p>「可是，你的家世至少也显赫到会让那个大叔的态度瞬间大转变吧？呐……惠惠，把依丽丝牵扯进这种愚蠢的游戏真的好吗？我们该不会正在闯下非常不得了的大祸吧？」</p><p>悠悠事到如今才发现事情有多严重，嘴角不住抽搐，但已经太迟了。</p><p>「让您久等了，钥匙就是这副！……今后也请您多多关照小店！」</p><p>老板带着和冲进去的时候一样的冲劲拿着钥匙回来，满头大汗的露出僵硬的笑容。而听他这么说的悠悠则表示：</p><p>「……呐，惠惠，如果再闹上警局的话，我就真的没脸见故乡的大家了……」</p><p>「没问题的，我们只是把依丽丝带在身边照顾她、保护她而已。我们的所作所为不比这个好，也不比这个坏。这样你听懂了吗？」</p><h3 id="_6" tabindex="-1"><a class="header-anchor" href="#_6"><span>6</span></a></h3><p>在阿克塞尔中心附近的高级地段，有一栋看起来就很豪华的大豪宅。</p><p>与这栋建筑物相比，我现在住的豪宅看起来简直就像是一般住宅。而这间房子从今天起，就是我们的活动据点了。</p><p>我和悠悠仰望着这栋大豪宅，自然而然冒出这样的对话。</p><p>「……看来得决定盗贼团的名称了。然后，就把这里当成阿克塞尔分部吧。」</p><p>「呐，惠惠，你到底打算把团体的规模搞到多大啊？我一开始还以为只是像办家家酒一样的游戏，现在事情越闹越大，害我都害怕了起来。」</p><p>我也没想过事情会进展得如此顺利，其实现在心里还满慌的，但是总不能表露出来。</p><p>居然在盗贼团成立的第一天就得到镇上最好的房子，我还真的没想到。</p><p>「好大的房子喔！可能比父亲大人在避暑地的那栋别墅还要大呢！」</p><p>没有理会自己一个对宅邸有不同感想的爱丽丝，我打开了大门。</p><p>或许是贵族的宅邸构造都很类似吧，走进大门之后首先映入眼帘的隔间，和我住的豪宅一样是大厅。</p><p>负责管理的房地产仲介把宅邸内部打理得非常整洁，但是里面没有什么家具，只有一张大沙发和桌子而已。</p><p>我倒在大厅里的沙发上之后，懒洋洋地躺着宣告：</p><p>「从今天开始，这里就是我们的活动据点了。今后计划要做什么坏事、想讨论活动方针，或是闲得发慌的时候，想过来这里都可以自行前来。简单来说，这里就是我们的聚会处。你们各自带着一把钥匙吧。」</p><p>听见聚会处三个字，悠悠的眼睛发出红光，喜形于色。爱丽丝也不知道到底在高兴什么，变得笑容满面，很没规矩地跳上沙发来。</p><p>最后悠悠也带着一脸松懈的笑容在沙发的最边边坐下，于是我转身面对她们两个坐好。</p><p>「我也没想到会这么简单就得到活动据点，不过裙带关系和老家的力量也是才能之一。能够运用的东西我都会毫不客气地运用……好了。」</p><p>我把手放到桌子上之后。</p><p>「那么，接下来我要正式向你们说明吾等盗贼团的活动方针。」</p><p>以此为前言，到了这个阶段，我总算向她们两个开始说明——</p><p>「——事情就是这么回事。他们并没有中饱私囊，反而是站在老百姓这一边的义贼，尽管如此，政府却当他们是罪犯，悬以重赏，追捕他们。但即使面临这种状况，他们依然为了这个世界，为了人类而战！就算他们的义举没有任何人知道，也没有任何人了解他们，他们现在还是继续奋斗！」</p><p>「太了不起了……！竟然有如此志向高洁又坚强的人……！惠惠，我决定了！一直到刚才为止，我都还以为你又开始玩无聊的游戏了，只是心不甘情不愿地陪着你而已，不过今后我会认真协助你的！」</p><p>「又开始玩无聊的游戏」这段让我很介意，不过她愿意拿出干劲来就好了。</p><p>这时，我发现从刚才开始就默默不语的爱丽丝微微颤抖着。</p><p>「我、我……」</p><p>「依丽丝？你是怎么了，脸红成这样，而且眼睛都湿了……」</p><p>爱丽丝似乎连我指出她的异状都没有听见，用力拍了一下桌子便站了起来。</p><p>「我现在就去找父亲大人，向父亲大人耍任性，请他取消那个盗贼团的悬赏！如果办不到的话至少让我去找兄长大人，我要好好宠坏他！」</p><p>「你这个孩子突然说这是什么话啊！悬赏之类的也就算了，宠坏那个男人的必要性在哪里，我怎么看不出来！」</p><p>她到底是怎么从刚才的话题走向当中导出这个结论的啊？</p><p>『即使对方是公主，知道年纪尚小的少女曝身于危险之中，我们岂能坐视不管。只要有人不知该如何是好，无论是贵族的宅邸还是王城，任何地方我们都会潜入其中。这就是我们面具盗贼团的作风。』</p><p>没错，我只是把之前遇见面具盗贼团的时候，那个面具男对我说的这段话告诉她而已。</p><p>「更重要的是今后的目标。我们现在还只有三个人。而且年纪都还小，要是就这样开始拓展地盘、扩张势力，照现在的状态也只会被别人瞧不起而已。所以，我们要一面增加长相凶狠又能干的团员，一面逐渐提升知名度，最后要茁壮到足以和银发盗贼团并称的程度！」</p><p>听我如此强调，两人似乎各自思索着适合当团员的人选。</p><p>「长相凶狠又能干的团员啊……那些人给我的印象确实非常适合盗贼团之类的不法情事，不过让他们加入肯定没好事……」</p><p>在悠悠一面喃喃自语一面烦恼的时候，爱丽丝一脸凝重地抱着胸说：</p><p>「不好意思，惠惠小姐。之前我来这个城镇的时候，有一位先生对我很好，而且非常优秀，要不要试着邀请他啊？」</p><p>「非常优秀是吧。我不知道你是在怎样的状况下在这个镇上和他相识的，不过他是一个怎样的人啊？」</p><p>被我这么一问，爱丽丝歪着头说：</p><p>「那个人名叫八兵卫，是个整天有大半时间都笑着度过，很开朗的人，非常会搞笑，动不动就夸奖我、宠坏我。他还说，只要报酬谈得拢，任何事情他都愿意帮忙。」</p><p>「听好了依丽丝，你应该现在就立刻和那个家伙断绝关系！我想要的是那种会唱歌会跳舞又会战斗，好玩有趣又优秀的人！」</p><p>不过，今天才刚成立的盗贼团怎么可能突然找到更多团员。</p><p>人员这部分今后再慢慢增加就可以了吧。</p><p>为了准备执行原本的计划。</p><p>「首先，你们两位请看这个。我现在就告诉你们今晚的计划。」</p><p>我这么说完，在桌子上摊开了这个城镇的地图——</p><h3 id="_7" tabindex="-1"><a class="header-anchor" href="#_7"><span>7</span></a></h3><p>这里是某个贵族的别墅。</p><p>在我们的视线前方的，是在正门坚守岗位，负责当警卫的士兵们。</p><p>「——惠惠。我从之前就这么觉得，你是不是白痴啊？你在红魔之里得到最优秀的成绩其实是假的吧？」</p><p>我没有理会从刚才开始就一直在说同样的话的悠悠，仔细观察起那栋宅邸。</p><p>「以警卫的人数和宅邸的规模来看……我愿意的话可以用爆裂魔法一发解决。」</p><p>「惠惠，你应该用红魔族首屈一指的白痴这个称号才对！」</p><p>为了避免引起宅邸里的人们的注意，我堵住大吵大闹的悠悠的嘴，让她安静下来之后，爱丽丝也带着一脸困惑的表情，用力拉了拉我的披风一角。</p><p>「不好意思，惠惠小姐……？我对社会上的常识确实很陌生，不过连我也知道这是不应该做的事情。至少等找到证据之后再说吧……」</p><p>为了让如此表示的爱丽丝放心，我露出充满自信的笑容。</p><p>「放心吧依丽丝，擅长制作魔道具的红魔族自古就有这么一句话。『缺什么东西做出来就有了』。」</p><p>「你给我等一下，那句话的意思不是这样用的吧！」</p><p>我依然看着宅邸，坚定地对忍不住吐嘈的悠悠说：</p><p>「放心吧悠悠，我们有依丽丝在。只要有这个孩子当后盾，上了法庭根本不可能输。」</p><p>「呐，只有这件事情我一直不打算问，不过还是让我问一下好了！依丽丝到底是何方神圣？难不成，以我们的处境来说，现在根本不是做这种事情的时候了？」</p><p>听着悠悠的呐喊，我为了锁定魔法的目标而盯着宅邸的上空看，就在这个时候——！</p><p>「爱……！依、依丽丝小姐，总算找到您了！」</p>`,232),e(m,{src:`/images/C1/23.avif`,alt:`插图`,width:`850`,height:`1257`}),l[12]||=s(`<p>突然有人以快要哭出来的声音从我们背后如此大喊。</p><p>我转过头去，看到的是一名身穿白色套装，腰间插着剑的女子。</p><p>她眼角噙泪，呼吸急促，可见有多拼命在找爱丽丝。</p><p>我记得她应该是担任爱丽丝的护卫的人，名叫克莱儿。</p><p>「克莱儿！你、你怎么会知道我在这个城镇？」</p><p>爱丽丝似乎没有料想会被找到，带着惊愕的表情不住后退。</p><p>「我都在依丽丝小姐身边侍奉您多久了？像我这种程度的忠臣，无论是依丽丝小姐一周长高了多少、依丽丝小姐一天打了几次呵欠、依丽丝小姐用餐的时候试图挑掉青椒的举动有几次，我全都确认得非常仔细。依丽丝小姐的行动当然更是了若指掌！」</p><p>啊啊，这个人是没救的那种人。</p><p>「克、克莱儿，你说得就连我都有点吓到了！不过就算是这样，我还真没想到会被你像这样逮个正着……先不说这些了，克莱儿，拜托你！只要一个晚上就好了，我可不可以去兄长大人的豪宅……」</p><p>「不可以。」</p><p>克莱儿像是想表示唯有这件事绝对不准似的，一把抓住爱丽丝的肩膀，然后紧紧抱住她，不让她逃走。</p><p>「放开我，克莱儿！今晚我不去阻挠的话，兄长大人会被骗走！」</p><p>「那再好不过了！那种男人随便被别的女人骗走沦落为妻奴是好事一桩！好了，依丽丝小姐，要是您继续耍任性的话，我也有我的考量！」</p><p>紧紧抱住爱丽丝的克莱儿红着脸如此大喊之后，在抱住爱丽丝的手上多用了几分力。</p><p>「克、克莱儿？你这样我连话也没办法好好说，总之你先把手稍微松开一下吧？」</p><p>将爱丽丝的恳求当成耳边风的克莱儿把鼻尖凑到爱丽丝的头发，一脸幸福地吸着气。</p><p>「不可以。这可是在处罚您呢，依丽丝小姐。为了避免今后再次发生这样的事情，不才克莱儿决定狠下心来，用力抱紧依丽丝小姐，好好疼爱……痛！好痛！请、请您别这样，依丽丝小姐！不好意思依丽丝小姐，是我太得意忘形了我道歉就是了请您不要认真绞紧我！」</p><p>被爱丽丝反过来用尽全力紧紧抱住的克莱儿的躯干，发出了不应该从人体身上发出的声响，于是放开了爱丽丝，转过来面对我们。</p><p>「好久不见了，惠惠小姐。这次有劳你照顾依丽丝小姐，不胜感激。不过，今后我们会严加监视位于王都的瞬间移动服务处，所以依丽丝小姐应该不会再来到这个城镇了。因此，若是要道别的话请趁现在……」</p><p>听克莱儿这么说，爱丽丝低下头，显得相当失望。</p><p>看克莱儿这么生气，爱丽丝这次果然是偷偷熘出王城了吧。</p><p>既然如此，今后王城也会严加戒备，而且连瞬间移动服务也没办法利用的话，以我们的身分差距而言，确实是不会再见面了。</p><p>被克莱儿轻轻从背后推了一下的爱丽丝，即使站到我的面前还是低着头，表情就像是还没玩够的小朋友。</p><p>于是我以只有这个容易死心又听话的基层人员听得见的声音说：</p><p>「等一下回到城堡之后，你要竖起耳朵仔细听，我会对你打暗号。从明天开始，听到那个暗号的声响，你就设法来到王都的正门前。」</p><p>说得就像是在约定要再出来玩似的。</p><p>「咦？」</p><p>爱丽丝抬起头来，似乎无法理解我说了什么，楞了一楞。</p><p>「虽然只是暂时入团，但你也已经是盗贼团的一员了。都已经入了团，你可不要以为能够那么容易脱离我们喔。」</p><p>听我这么说，爱丽丝的表情一亮……</p><p>「是！那当然了，头目大人！」</p><p>然后笑容满面地这么说。</p><p>「……依丽丝小姐，我不知道两位在说什么悄悄话，不过我可不会再让您脱逃了喔。不、不可以，就算您用那张可爱的脸装得再楚楚可怜也没用！好了，我们快点去瞬间移动服务处吧。蕾茵现在一定在王都哭着到处找依丽丝小姐了。」</p><p>就这样，尽管对克莱儿用尽各种手段央求，爱丽丝依然被带到瞬间移动服务处去了。</p><p>「走掉了呢……」</p><p>跟不上事情发展的悠悠茫然若失地冒出这么一句话。</p><p>「悠悠。我记得你学了瞬间移动魔法对吧？」</p><p>被我这么一问，悠悠微微歪着头说：</p><p>「咦？嗯，对啊。我想说学起来就可以随时回红魔之里，所以最近总算学会了……」</p><p>「原来如此。那么，我有件事要拜托悠悠。你等一下和我一起去瞬间移动服务处。接着，请店里的人送我们到王都去之后，可以请你把王都登录为传送地点之一吗？」</p><p>「登录王都吗？……可以是可以，不过你该不会是在动什么歪脑筋吧？」</p><p>我才不是在动歪脑筋呢。</p><p>只是想做好随时可以去迎接基层人员的准备而已。</p><p>「说什么动歪脑筋啊，真没礼貌，我只是想去远一点的地方完成我每天的例行公事罢了。很遗憾的，今天无法执行那个计划，只能延期了。好了，我们走吧！」</p><p>「可以是可以，不过惠惠的眼睛为什么那么红啊！害我满心只有不祥的预感！」</p><p>——请瞬间移动服务处送我们到王都之后，我们直接来到正门外面。</p><p>「那么，请你把这里登录为瞬间移动的目的地吧。我接下来还有事情要做，登录完成之后请你过来接我。」</p><p>「好是好，不过你有什么事情要做啊？跟你刚才和依丽丝说悄悄话有什么关系吗？」</p><p>我没有回应露出不安表情的悠悠，转过头去，朝着跟正门隔着一段距离的一座有点高的小丘陵走了过去。</p><p>嗯，在这里的话我应该不会被王都的人看见才对。</p><p>为了最基层的团员，我拿出干劲，开始咏唱魔法——</p><p>「等一下惠惠，你在咏唱什么啊！你应该不会是想在这种地方施展爆裂魔法吧！」</p><p>接着，我一面听着登录好瞬间移动目的地之后追过来的悠悠的声音……</p><p>「『Explosion』——————！」</p><p>一面为了将声响传到王城里，施放出最淋漓尽致的爆裂魔法——！</p><h3 id="_8" tabindex="-1"><a class="header-anchor" href="#_8"><span>8</span></a></h3><p>「——惠惠，从今天开始，我要叫你红魔族第一白痴。」</p><p>「如果你真的这样叫我的话，我就叫你红魔族第一边缘人。」</p><p>用悠悠的瞬间移动魔法回到阿克塞尔之后。</p><p>「……我可是能够随便把你丢在路边喔。」</p><p>「喂，把年幼无助的我丢在往来人潮这么多的地方可是罪无可赦喔。要是有人看见耗尽魔力，无法动弹的我，想对我做坏事的话该怎么办？」</p><p>我让悠悠背着我，送我回家。</p><p>「会对惠惠做坏事的奇特人种，即使是在这个一堆怪胎的城镇当中，我也只想得到和真先生一个人……好痛好痛！」</p><p>我把原本环在悠悠的脖子上的手往下移，一把抓住爱乱说话的她的胸部装甲，狠狠地用力捏下去。</p><p>「话说回来，我还真没想到会引发那么大的骚动。」</p><p>「为什么会没想到啊！王都那边都响起魔王军袭击警报的广播了，不过那怎么想都是惠惠的魔法攻击害的吧。」</p><p>「……也罢，当成是盗贼团的华丽处女秀就好了吧。」</p><p>「那样与其说是盗贼团更像是恐怖分子吧！呐，我们解散了好不好？要是一个没弄好，用不了多久我们的悬赏额就会比银发盗贼团还要高了吧。」</p><p>这样也算得偿所望就是了。</p><p>「有什么关系嘛。而且王都的人们不久之后就会习惯了啦，因为接下来我每天都会这样搞。」</p><p>「等一下！这我可没听说耶！」</p><p>「喔，快到家了呢。我的魔力也恢复了一点，送到这里就可以了。」</p><p>「呐，明天你也要这样搞吗？我还是退团好了！」</p><p>把悠悠的大吵大闹当成耳边风，我跨步走向豪宅——</p><p>「——我回来了～～」</p><p>「你回来啦～～！」</p><p>回到豪宅后，阿库娅坐在沙发上殷勤地喂着在她大腿上的黄色毛球，一边向我打招呼。</p><p>接着，便听见厨房那边传来互相叫骂的声音。</p><p>「——我都说了，你的料理又不是特别好吃，很普通啦！料理就交给有料理技能的我，你只要负责收十善后就好了！」</p><p>「——我也有身为女人的尊严要顾！在料理方面输给一个平日闲着无所事事的男人，我怎么对得起我们家那些从小教导我的厨师们！总之，这里交给我就对了，你给我到大厅去闲着等开饭！」</p><p>看来是在吵今天谁要煮饭的样子。</p><p>大概是因为被赶出厨房的关系，和真一脸不开心地来到大厅。</p><p>「哦？你回来啦，惠惠。呐，你听我说，达克妮丝那个家伙又在耍任性——」</p><p>我对倒头往沙发上一躺之后就开始抱怨的和真说：</p><p>「反正一定又是和真说了不该说的话吧……先别说这些了。那个，今晚一定要……」</p><p>「……好、好啊。今晚要那样对吧。嗯，今天晚上一定要那样。」</p><p>大概是因为除了「那样」以外想不到更好的形容了，和真红着脸坐起身子来。</p><p>「怎么了，这是在干嘛？你们两个不太对劲喔，那样是怎样啊～～？」</p><p>「没没、没怎样啊——！是那个啦那个，惠惠今天早上说要成立一个什么奇怪的团体！这么说来那个搞得怎样了？」</p><p>被阿库娅追问的和真为了转移话题，连忙这么问我。</p><p>「进展顺利到我都吓了一跳。今天不但得到活动据点，而且还多了两名部下。」</p><p>「这样啊，听起来好像很有意思，真是太好了。我小时候也经常搭建秘密基地来玩呢。不过，要是活动据点被附近的小朋友占走或是弄坏，你也不可以反击，弄哭人家喔。」</p><p>这个男人！</p><p>「你把我当成什么了啊！应该说，你看了我们的活动据点一定会吓一跳喔！再怎么说，那里都比这间豪宅还要大嘛。而且，今天加入的还是个手拿圣剑，会使用传说级魔法的基层团员，以第一天来说，成果应该算是相当不错吧。照这样发展下去，用不了多久就可以和那个银发盗贼团并驾齐驱了。」</p><p>「这样啊，那真是太好了。那个新交到的朋友又是圣剑，又是传说魔法的，和你应该很合得来吧。不过，你们千万别给别人添麻烦喔。」</p><p>这个男人未免也太没礼貌了吧。</p><p>话虽如此，我又不能跟他说明有关爱丽丝的事情。</p><p>……也罢，总有一天会有机会说明的吧。</p><p>正当我这么想的时候，和真忽然对阿库娅说：</p><p>「总之就是这样。喂，阿库娅。今天我买了还不错的酒，你尽管喝吧，不用客气。你平常那么努力养育爵尔帝，偶尔还是喝点酒早点睡吧。」</p><p>「哎呀，今天吹的是什么风啊？你是不是发现自己平常老是对我做些会遭天谴的事情，悔过向善了啊？既然你都这么说了，酒我就毫不客气地收下了，不过今天我不想喝。今天我想跟惠惠一起思量爵尔帝将来学会的必杀技该叫什么名字，所以酒就改天再喝吧。」</p><p>「啥？不、不对不对！爵尔帝的必杀技应该要等到将来真的学会了再取比较好吧？今天惠惠应该也玩得很累了，也想早点睡觉吧？对吧！」</p><p>略显著急的和真连忙这么说，声音都拔高了点。</p><p>……看来，这个人似乎真的以为我整天都只顾着玩。</p><p>我是很想说明今天一整天的成果，不过这个男人又不是团员，还是先别告诉他好了。</p><p>等到我们变成更大型的盗贼团之后，他肯定会开口要我们让他加入。</p><p>所以，等到哪天这个男人说想要加入盗贼团的时候——</p><p>「说的也是。我今天很累，所以决定吃饱饭就要去睡觉了。事情就是这样，所以我跟和真约好的那件事就等到明天再说吧。」</p><p>「咦！」</p><p>到时候，我再把那天遇见那位面具盗贼的事情也告诉这个人好了。</p>`,110),e(m,{src:`/images/C1/03.avif`,alt:`章节尾页`,collapsed:``,width:`338`,height:`1200`}),l[13]||=a(`h2`,{id:`第二话-增生的盗贼团`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#第二话-增生的盗贼团`},[a(`span`,null,`第二话 增生的盗贼团`)])],-1),e(m,{src:`/images/C1/09.avif`,alt:`章节标题`,collapsed:``,width:`850`,height:`1257`}),l[14]||=s(`<h3 id="_1-1" tabindex="-1"><a class="header-anchor" href="#_1-1"><span>1</span></a></h3><p>爆裂魔法的咏唱传遍这座看得见王都的小丘陵。</p><p>「『Explosion』————！」</p><p>奔流的闪光，爆炸声大响。</p><p>王都也瞬间随之骚动了起来，不过我已经耗尽魔力，当场瘫倒在地，无法动弹。</p><p>『魔王军袭击警报！魔王军袭击警报！请各位冒险者立刻到王城前方集合——』</p><p>我带着事不关己的心情听着从王都传出来的广播声，终于在等待了十几分钟之后。</p><p>「——找到啦啊啊啊啊！你别闹了好不好，我看你真的是白痴对吧！呐，你真的每天都要这样搞吗？」</p><p>「头目大人，抱歉来迟了。我顺利熘出来了！」</p><p>或许是因为有自己在做近乎犯罪的事情的自觉，悠悠将兜帽拉得低到看不见脸孔，但还是可以窥见她的眼睛因为亢奋与气愤而发着红光。</p><p>爱丽丝则是背着一个小背包，穿得像是要去野餐似的，两个人就这样冲到趴在丘陵上的我身边来。</p><p>「你们两个辛苦了。不好意思，可以扶我起来一下吗？」</p><p>「你还敢说什么辛苦了，小心我把你原地掩埋喔！呐，惠惠，你知道现在王都的骚动有多严重吧？之后你到底打算怎么收十残局啊！」</p><p>我被爱丽丝翻成仰躺的姿势之后，眼见手叉着腰的悠悠开始对我教训起来。</p><p>「哪有什么好收十的啊，我们都已经知道这种时候该怎么做了不是吗？之前红魔之里不是也发生过类似的事件吗？没错，就是那起非常令人痛心的事件……」</p><p>「你、你该不会是……」</p><p>我和悠悠过去也有过类似这样的经验。</p><p>在红魔之里有个盯上点仔的神秘女恶魔，每天晚上都乱发爆裂魔法。</p><p>细节或许有点不对，总之就是发生过类似这样的事件。</p><p>「你又想赖到别人身上了吗！」</p><p>「又、又是什么意思，没礼貌耶！如果你是在说红魔之里的爆裂魔的话，那肯定是女恶魔闯的祸。这次的事件嘛……就去警察局说些什么『等我回过神来的时候才发现有个看起来很像魔王的人在那边散步，然后突然发了爆裂魔法之后就跑掉了』之类，随便提供一下目击情报……」</p><p>「我绝对不配合！我才不会去提供这种愚蠢的证词！」</p><p>这时，爱丽丝自顾自地将一直被悠悠骂的我以公主抱的姿势抱了起来。</p><p>「今天，我请家里的人准备了便当和点心。也有你们两位的份，我们找个风景优美的地方吃如何？」</p><p>「呐，这个孩子其实也满没常识的耶，应该说有点大人物的感觉！」</p><p>被爱丽丝抱着的我对悠悠做出指示：</p><p>「再这样下去会被追兵找到。所以我们先回阿克塞尔吧。便当在城镇外面吃好了。」</p><p>「现在便当一点也不重要好吗！啊啊，我不是那个意思啦依丽丝，不要露出那么哀伤的表情好不好？我不应该说一点也不重要的，其实我也很向往去野餐、和朋友一起吃便当之类的情境！」</p><p>这时，或许是悠悠在大声嚷嚷的关系，王都那边有声音传了过来，在说前面好像有人。</p><p>「都是因为悠悠大吵大闹害我们被发现了啦，不过是和朋友一起吃便当而已不需要那么兴奋吧，真是的，边缘人就是这样！好了，快点咏唱瞬间移动魔法啦！」</p><p>「呐，是我的错吗？我总觉得不太能够接受！」</p><p>依然继续大吵大闹的悠悠迅速完成了咏唱之后。</p><p>「『Teleport』！」</p><p>便摸着我们施展了瞬间移动魔法。</p><p>——我们来到阿克塞尔附近的湖边后，便坐在爱丽丝喜孜孜地摊开的野餐埝上吃便当。</p><p>「呐，依丽丝，这个便当是谁做的啊？嗯，真的很好吃。是真的，真的很好吃喔。只是，里面用的食材好像太豪华了，感觉好像不是带来野餐的便当耶。」</p><p>「我只是说『我想和最近交到的朋友一起玩，想偷偷熘出门去，可不可以协助我脱逃』，这样拜托女仆们之后，不知怎地，大家就充满干劲，连便当都帮我准备好了。」</p><p>「呐，依丽丝，你们家是有很多女仆的大宅门吗？绉绸盘商到底是在做什么的啊？虽然听到依丽丝说我是你最近交到的朋友，让我飘飘然到差点要觉得无所谓了，但还是觉得后来好像听到什么无法听过就算了的词汇……」</p><p>拿筷子夹起鱼翅烧卖的悠悠，一脸凝重地看着烧卖，同时这么问。</p><p>「那种事情根本无所谓吧。无论是胸围还是身高、朋友的人数还是家里的状况，人总有一些不该问的事情。」</p><p>「也对，是我不好。惠惠说的没错。」</p><p>不知道是因为被说服了，还是因为我提到她自己也不想被问的事情，悠悠乖乖吃起便当。</p><p>而魔力恢复到有办法吃便当的程度之后，我也大口狂吃起高级便当，同时这么说：</p><p>「话说回来，依丽丝在食粮补给方面的能力相当不错呢。我就任命你为吾等今后的补给负责人了。换句话说就是升官。」</p><p>「我升官了吗！谢谢头目，我会加油的！」</p><p>「依丽丝，她只是叫你以后也要继续带好吃的东西来而已，不要被她骗了！」</p><p>不久之后，吃完便当的我们一下子打赤脚进湖里追小鱼，一下子拿扁平的石头往湖面上丢，并教了爱丽丝打水飘的玩法，然后差点砸中在湖的对岸钓鱼的人，只好拼命道歉。</p><p>玩着玩着，最后来到平静的午后时刻……</p><p>「我今天玩得相当开心。如果每天都这么好玩的话，我也会更乐意参加。那么，熘出来太久的话依丽丝家里的人大概又会担心到跑来接她，我们差不多该回去了。」</p><p>听悠悠依依不舍地这么说，爱丽丝便将野餐埝和便当盒塞回背包里。</p><p>「那我们回家吧。我今天玩得很开心，改天再来野餐吧！」</p><p>两人就这么边哼着歌边走向阿克塞尔，于是我也慢步跟上……</p><p>「不对吧！吃完便当就回家是怎样！今天什么时候变成是出来野餐了，吾等的活动现在才要开始好吗！」</p><p>悠悠一脸厌恶，像是想表达居然被发现了似的。</p><p>「所以，头目大人，今天要做什么呢？」</p><p>我回答了爱丽丝的提问。</p><p>「那么，我来说一下今天的行程。不久之前，吾等得到了活动据点。总之先以这里为阿克塞尔的总部……然后在各地陆续增设分部，最后将势力扩张到世界规模。为了完成这样的预定计划，吾等需要能够运用的资金。所以，我们今天要去确保赚取资金的收入来源。」</p><p>「呐，你说世界规模是在开玩笑对吧？有时候我会搞不清楚惠惠到底是在开玩笑，还是在说真的耶……」</p><p>我当然是在说真的啊。</p><p>应该说……</p><p>「吾等盗贼团都已经有阿克塞尔总部和王都分部两个单位了。接下来应该还会陆续增加才对。王都分部的活动据点是依丽丝家。依丽丝，等到吾等盗贼团的象征标志定案之后，要挂到你们家的高处去喔。从今天开始你就是王都分部的分部长了。补给负责人兼王都分部长。连升好几阶了呢。」</p><p>「谢谢头目，我会加油的！」</p><p>「依丽丝，不可以被骗了，她打算连你家都侵占耶！」</p><p>吾等之团旗在这个国家的王都城堡上飘扬已经是指日可待了。</p><p>为此，我们也得先获得资金才行——</p><h3 id="_2-1" tabindex="-1"><a class="header-anchor" href="#_2-1"><span>2</span></a></h3><p>「就是这么回事，请给我工作。最好是能够长期稳定地赚取金钱，并且又能够得到名声，类似这样的工作。」</p><p>「这个嘛，你觉得去找个地方打工如何？」</p><p>来到冒险者公会的我们，为了找工作而向柜台小姐商量。</p><p>正当爱丽丝以闪闪发亮的眼神看着公会里的冒险者们时，立刻得到这个冷淡回答的我毫不气馁地说：</p><p>「不是这样的，我们想要的是更适合我们的工作。我们三个对自己的实力都很有自信喔！所以，有没有那种在威胁城镇安全的敌人出现的时候由我们负责击退，但是相对的平常要给我们保护费之类的工作……」</p><p>「不久之前好像有一间保全公司开始做起类似的业务，但是没多久就倒闭了耶。」</p><p>听柜台小姐这么说，一旁的悠悠不知为何别开了视线。</p><p>关于那间倒闭的保全公司，她是不是知道些什么啊？</p><p>「姑且先不说这个，我总不能分派太野蛮的工作给你们三个女生吧……」</p><p>问题果然是出在我们的外貌啊。</p><p>之前在找同伴的时候，我们也是因为外貌而吃了很多苦头。</p><p>「拜托你，大姐姐，不是那种可以一次赚到一大笔钱的工作也没关系！请给我可以稳定赚钱，同时又可以受到镇上的人们感谢，进而让大家想加入盗贼团的工作！还有，可以的话最好是战斗类的工作！」</p><p>「符合那种条件的工作也不是说有就有呀…………啊！」</p><p>或许是想到什么符合条件的工作了吧，大姐姐轻轻叫了一声。</p><p>「怎么了，有那种工作吗？那就麻烦你介绍给我们！」</p><p>「不，要说有是有没错，不过该说是已经有人在做了还是怎样呢……其实是这样的，城镇的政府机关委托了一项工作是要驱除在垃圾场作乱的乌鸦，但是不知为何，有个人一直在免费从事这项工作。」</p><p>驱除乌鸦。</p><p>的确是可以受到镇民们感谢，原则上也是战斗类的工作，既然是公家单位委托的工作应该也可以持续性地稳定赚到钱，但是……</p><p>嗯，再怎么说也不能叫红魔族和公主殿下去驱除乌鸦吧。</p><p>这样就成了所谓的大材小用，杀鸡用牛刀了。</p><p>「再怎么样我们也不能接下那种委托。身为尊贵的红魔族，要是得到乌鸦杀手这种不名誉的外号，是要我怎么活下去啊。别提那个了，没有其他任务了吗？不一定要是公家单位，像是大型商店、某某团体之类的也好，没有那种会稳定提供工作的单位吗？」</p><p>听我这么说，柜台小姐烦恼了一下。</p><p>「原则上，也不是没有符合你的条件的任务啦……」</p><p>——位于阿克塞尔郊外的一栋看起来最近才刚改建完成，规模中等的教堂前面。</p><p>「没想到我居然还会来到这里……」</p><p>「呐，惠惠，还是算了吧？唯有这里还是算了吧！」</p><p>这里是阿克西斯教团的阿克塞尔分部。</p><p>「这栋教堂不但才刚盖好，而且好蓝好漂亮喔！……你们两位不进去吗？」</p><p>或许是因为不太了解阿克西斯教团，只有抬头看着教堂的爱丽丝一个人说出这种天真的感想。</p><p>「依丽丝，这是这个城镇当中最为棘手的团体，这里是非常危险的地方。如果里面的人们做出什么奇怪的举动，我准许你出手攻击。」</p><p>「依丽丝，只有这次，惠惠所说的完全正确。要是有什么奇怪的人突然跳出来的话，你不需要客气。」</p><p>听见我们的警告，爱丽丝歪着头，轻轻推开教堂的门……</p><p>在此同时，一个东西翻倒、破裂的声音响起。</p><p>「啊啊！放在门前面那个据说只要持有就可以得到幸福的昂贵陶瓮！摔破了这个的一定是不怀好心，想要夺走我的幸福的人吧！既然如此，只好请你选择要养我一辈子，还是要赔偿，还是要信仰阿克西斯教以示负责……哎呀，这不是惠惠小姐和悠悠小姐吗？」</p><p>亢奋不已地一口气说完这些台词的祭司一看见我们，便露出一脸傻楞的表情。</p><p>「不好意思，我们是接了公会的委托才过来的……还是说我们可以走了？」</p><p>听见我这么回答，赛西莉的表情为之一亮。</p><p>「——那个，我真的不用赔偿吗？只要持有就可以得到幸福的陶瓮，一定是相当昂贵又强而有力的魔道具吧……」</p><p>见爱丽丝一脸歉疚地这么说，赛西莉的眼中浮现感动的眼泪，并且像是要祈祷似的握起双手。</p><p>……不，她是真的开始祈祷了。</p><p>「啊啊，感谢阿库娅女神！没想到女神竟然派一个如此纯真的小萝莉来我身边……！」</p><p>已经完全不管什么委托的赛西莉看来今天依然是正常运转。</p><p>或许还是当作什么事情都没发生过，直接走人比较好吧。</p><p>「依丽丝，那个陶瓮是这位大姐姐故意摆在门前的，所以你不用在意。她就是在等人开门打破那个陶瓮，是一种相当恶毒的手法，借此刁难打破陶瓮的人，以赔偿金为名义大敲竹杠，或是逼迫对方入教。」</p><p>见爱丽丝依然一脸担心又为难的样子，我为她说明了赛西莉在做什么。</p><p>结果，听了我这番说明，爱丽丝不知为何对赛西莉投以尊敬的眼神。</p><p>「居然还有这种手法可以获取金钱、增加信徒，我连想都想不到。赛西莉小姐真是聪明呢！」</p><p>「依丽丝，不需要为了这种事情佩服她！这位赛西莉小姐的所作所为已经游走在犯罪边缘了！」</p><p>我倒觉得已经是游走在合法边缘的犯罪了。</p><p>「你是依丽丝小姐对吧？我是这间教堂位阶最高的人，也是阿克西斯教团的美女祭司，名叫赛西莉。不用客气，叫我赛西莉姐姐就可以了。」</p><p>「好的，请多指教，赛西莉姐姐。我是依丽丝。」</p><p>依丽丝乖乖叫了赛西莉姐姐，让赛西莉的呼吸开始变得越来越沉重，越来越急促。</p><p>「呐，惠惠小姐，我会不会明天就死掉啊？我会不会因为今天把运气统统用完，而结束此生啊？」</p><p>「这种程度的小事就可以让你的人生圆满了吗？依丽丝，这样会害这位大姐姐的情绪变得不稳，至少停留在大姐姐的阶段就好了。」</p><p>「这、这样啊，我、我知道了……」</p><p>「啊啊，怎么这样！」</p><p>赛西莉似乎大受打击，不过再这样下去的话完全没有办法谈事情，所以我硬是改变了话题。</p><p>「好了，言归正传……我们是接了公会的委托，才会来到这里的。我们可以谈一下工作的事情吗？」</p><p>我拿出公会给的委托书，递到沮丧地蹲下去抱着膝盖缩成一团，开始闹起脾气的赛西莉面前。</p><h3 id="_3-1" tabindex="-1"><a class="header-anchor" href="#_3-1"><span>3</span></a></h3><p>「好了，那么我们来谈工作上的事吧。话虽如此，其实也不是什么太困难的工作。委托内容就和告示上面写的一样。」</p><p>我们从公会接到的工作大致上有两项。</p><p>一项是最近这间教堂附近有可疑人物出没，要找出犯人并击退之。</p><p>另一项是担任顾摊小姐，确保教团的资金来源。</p><p>姑且不论搜寻可疑人物，顾摊小姐算是相当好赚的工作。</p><p>听说只要一个月固定来个几次，每次露脸几个小时就可以了。</p><p>光是这样，就可以分到营业额的一成。</p><p>顾摊小姐的工作原本附注需面试，不过赛西莉表示我们没问题。</p><p>我不知道她到底想卖什么，但是条件可以说是超乎寻常的好。</p><p>「顾摊小姐的工作感觉很轻松所以没关系。至于另外一项工作……」</p><p>听我这么一问，赛西莉伸出手指抵着自己的脸颊，露出烦恼的表情。</p><p>「事情是最近这一阵子发生的……」</p><p>根据赛西莉的说明，教堂后面的田地里种的蔬菜会被偷吃，放在教堂冰箱里的食物也会被偷拿走。</p><p>听说犯人完全不会发出任何声响，等到发现的时候食物就已经不见了。话虽如此，即使问了附近的邻居，也得不到任何可疑人物的目击情报。</p><p>「偷蔬菜又乱翻冰箱啊。真搞不懂犯人的目的是什么。如果目的是偷取食物的话，也不需要特地对这么危险的地方下手吧。比起这种被抓到的话不知道会被怎样的地方，应该有更安全，也更容易下手的地方才对吧。」</p><p>「呐，惠惠小姐，我觉得阿克西斯教团并没有那么狠毒，也没有那么惹人厌耶。」</p><p>正当我烦恼着该如何找出犯人的时候，悠悠战战兢兢地开了口：</p><p>「惠惠，这该不会是某种出自怨恨的举动吧？比方说被阿克西斯教团害得很惨的人前来报复之类的……」</p><p>「挟怨报复是吧……大姐姐，你记不记得自己做过什么会遭人怨恨的事情啊？无论是多小的事情都可以说来听听。」</p><p>听我这么说，赛西莉抬头看着天花板，像是在回想什么似的。</p><p>「……我不太清楚耶。」</p><p>说完，她一脸哀伤，轻轻摇了摇头。</p><p>阿克西斯教团的祭司不可能没有遭人怨恨——我好像因为这种先入为主的观念，说出了有点失礼的话也说不定。</p><p>「这样啊。不好意思，我问了奇怪的问题。也罢，其实是在自己也不知情的状况下给别人添了麻烦，结果因此反遭怨恨，这也是很有可能的事情……」</p><p>「不，我不是那个意思。应该说是因为我做过太多会遭人怨恨的事情，所以根本无从锁定起吧……」</p><p>「我对你失望透顶了，把我刚才的道歉还给我！你到底都干了些什么好事啊，我们干脆去向所有你想得到的人道歉算了！」</p><p>但赛西莉果然还是赛西莉。</p><p>「话又说回来了，如果被偷的频率那么高的话，没有目击者也太奇怪了吧。赛西莉小姐，犯人有没有固定的犯案时间啊？」</p><p>「你问犯案时间我也不知道啊，我都是等到发现的时候才知道食物不见了……」</p><p>悠悠和赛西莉看着彼此，苦思不已。</p><p>「大姐姐，你和邻居的关系怎么样呢？比方说，你是不是做过什么多余的事情，导致邻居和犯人合伙犯案之类的……」</p><p>「就算是我也不敢小看和邻居的关系好吗。在上一个城镇的时候，我就是因为经常和邻居发生冲突，结果闹出差点必须搬离原址的骚动呢。」</p><p>我到底该拿这个人怎么办才好呢？</p><p>「无论如何，没有线索的话也无从查起。追查犯人的工作晚点再说，你先告诉我们顾摊小姐的工作到底要卖什么东西吧。」</p><p>听我这么说，赛西莉兴高采烈地从教堂里面抱了一样东西出来。</p><p>是装在箱子里面的大量白色粉末。</p><p>「……不好意思，大姐姐，这该不会是……」</p><p>我的问题还没问完，赛西莉却竖起食指说：</p><p>「嘘——！惠惠小姐，不可以继续说下去了。这是只需要放进嘴里就可以变得非常幸福的，很普通的粉末喔。」</p><p>「咦咦！」</p><p>听她这么说，悠悠露出震惊的表情，爱丽丝则是歪头不解。</p><p>「大姐姐，这是违禁品对吧？要是被发现了，可是又会挨骂的喔。」</p><p>「又！又的意思是你已经有前科了吗！」</p><p>悠悠动不动就插嘴吐嘈，而听见违禁品这几个字，爱丽丝的眉毛也动了一下。</p><p>「呵呵，没问题啦惠惠小姐。这不是那个违禁品。而是以那个为基础，经过改良再改良，还没有遭到禁止的特制品。而且也已经确认过对人体无害了。呵呵呵呵，一旦吃过这个之后，这个城镇的大家也会变得没有这个就不行了！」</p><p>「！」</p><p>见赛西莉露出可疑的笑容，悠悠便从腰间抽出魔杖。</p><p>接着她以魔杖指着赛西莉，一脸哀伤地厉声表示：</p><p>「我原本还以为赛西莉小姐虽然个性很那个，言行也很奇怪，但并不是会做出这种事情来的人！赛西莉小姐对我而言也不是陌生人，所以我一定会让你改过自新的！」</p><p>悠悠好像产生了什么重大的误会。</p><p>接着，爱丽丝也轻轻抽出剑来。</p><p>「既然会被指定为违禁品，应该都是会危害这个国家的东西才对。而且还是经过改良的特制品的这番话，既然都被我听到了就不能置之不理。」</p><p>「等一下，你们两位为什么要用那么严厉的态度对待姐姐啊？如果我做错了什么我愿意道歉，也会把这个分给你们两位！」</p><p>正当赛西莉因为事出突然而着急到不行的时候。</p><p>「居然还想引诱我们用那种东西……难道说，你该不会也引诱惠惠用过这种东西吧？」</p><p>「咦？这……这是当然的吧，我想跟她分享这个的美好之处啊……」</p><p>悠悠的眼睛发出红光。</p><p>怎么搞的，总觉得我好像看过类似这样的剧情。</p><p>「等一下！你们听姐姐说！姐姐觉得你们一定是误会什么了！」</p><p>这时，我对一点一点逼近感到害怕的赛西莉的两人说：</p><p>「我看你们好像是误会什么了。这是因为容易害小朋友和老人家吃了噎到，现在被禁止交易的点心，琼脂史莱姆的粉末。」</p><p>「「咦！」」</p><p>举着武器的两人听了我这番话，停下动作。</p><p>「呜呜……这可是老爷爷吃了也不会噎到的，划时代的特制品耶……」</p><p>见赛西莉哭哭啼啼的，两人只能面面相觑。</p><h3 id="_4-1" tabindex="-1"><a class="header-anchor" href="#_4-1"><span>4</span></a></h3><p>「——真是的！大姐姐怎么可能会经手那种可疑的粉末啊！我好歹也是神职人员喔！」</p><p>「「对不起！」」</p><p>赛西莉因为立场翻转而采取强硬态度开始说教，而两人异口同声地对这样的她道歉。</p><p>我觉得是赛西莉每次遣词用字都很容易引人误会的问题就是了。</p><p>「这可是我花了很多时间改良，不会哽在喉咙的划时代特制品。可是，如果直接用琼脂史莱姆这个名称拿出去卖的话会引来警察关切，所以我想用『阿克西斯教团的白粉』这个名称来卖。」</p><p>「我觉得这个名称肯定更容易引来警察就是了。」</p><p>我们讨论了一阵子之后的结果，决定至少用「阿克西斯教团的那个」这种神秘的名称定案。</p><p>应该说，她真的想卖这个吗？</p><p>最根本的问题是，这个真的卖得出去吗？</p><p>尽管我们心里这么想。</p><p>「那么，我们立刻动身吧！只要有你们在，一定很快就可以销售一空！」</p><p>赛西莉还是兴冲冲地搬起装着那个的箱子。</p><p>——嗯，我早就有不祥的预感了。</p><p>「头目大人，我们只是把粉末交给客人而已耶，做这种工作拿那么多钱真的可以吗？总觉得这项工作未免太简单了。」</p><p>将那个亲手递给一位客人的爱丽丝露出一脸不解的表情这么问我。</p><p>我也同样拿了一包那个交给客人。</p><p>「工作本身是很单纯，确实也很轻松没有错。不过，我们还是有足够的权利收取昂贵的工资。」</p>`,209),e(m,{src:`/images/C1/12.avif`,alt:`插图`,width:`850`,height:`1257`}),l[15]||=s(`<p>然后斜眼瞄了一下赛西莉。</p><p>「来来来，这是吾等教团以有点不可告人的手法制造出来的『阿克西斯教团的那个』喔——！使用方法非常简单，只要用水调开，吃下去就可以了！黏黏稠稠的包君满意！来来来，大家想不想吃吃看那些美少女拿在手上的那个啊？」</p><p>该怎么说呢，这肯定已经出局了吧。</p><p>从各种层面来说都出局了吧。</p><p>为什么这个人的遣词用字总是这么那个啊？</p><p>我身旁的悠悠听着赛西莉的揽客台词脸都红了，却还是认真地将那个交给上门的客人。</p><p>之所以说顾摊小姐需要面试，原来是这么回事啊。</p><p>美少女亲手把那个交给客人。</p><p>我们要做的事情只有这样，不过……</p><p>「请问，这个果然是那个违禁品对吧？」</p><p>「可不是喔，这位客人。这是经过改良以后已经符合安全标准，不再受到管制的那个。来来来，保证上瘾喔。」</p><p>「我要了，我要三包！」</p><p>尽管揽客方式如此可疑，那位先生还是特地从我们三个手上分别买了一包那个。</p><p>「大姐姐，我姑且还是问一下，那真的是改良过的琼脂史莱姆对吧？是那种口感滑熘，也很好吃的东西对吧？」</p><p>「是啊。我不知道惠惠小姐还想到什么别的东西，不过这是你说的那种东西没错。」</p><p>大姐姐和客人的说词太令人介意，害我忍不住多想。</p><p>「来来来，快来买喔快来买喔！美少女们羞怯地紧紧握住的那个！现在只收您……哎呀，这位不是……」</p><p>「哎呀，这不是赛西莉小姐吗，好久不见了。」</p><p>一位路过的老绅士看见赛西莉，向她搭话。</p><p>他们两位似乎彼此认识。</p><p>「喔喔，这该不会是……！是那个吗？用热水调开然后那个之后，就可以品尝到天国的滋味的那个……！」</p><p>「没错，就是把那个再经过那个之后，将对人体的影响降到最低限度的东西。既然彼此都是同好，我就稍微分你一点……」</p><p>「这真的是琼脂史莱姆对吧！这真的纯粹只是遭到管制的琼脂史莱姆对吧！」</p><p>「「嘘——！」」</p><p>我忍不住如此大喊，不知为何却反过来被凶了，简直不可理喻。</p><h3 id="_5-1" tabindex="-1"><a class="header-anchor" href="#_5-1"><span>5</span></a></h3><p>结果，在各种意义上都相当引人非议的那个，一下子就卖完了。</p><p>遣词用字当中的猥亵词汇和危险词汇固然很多，不过最令我意外的是琼脂史莱姆这种食物其实相当受欢迎，知道了这件事让我难掩惊讶。</p><p>回到教堂来之后，开心的赛西莉出言慰劳我们。</p><p>「你们三位都做得很好！下一次如果可以准备用热水调开的那个，在客人们眼前吸食的话就更好了……」</p><p>「我才不要！呐，惠惠，我们再也不会做这个工作了吧？我总觉得这个打工在两种层面上都不太正经……」</p><p>悠悠这么说的时候，脸上的表情仿佛失去了什么重要的事物似的，但是这个工作可以在这么短的时间内赚到一大笔钱耶。</p><p>没有理由不继续做吧。</p><p>「赛西莉大姐姐，我今天很开心！这是我第一次赚到钱呢！」</p><p>「啊！等一下，依丽丝小姐，不要用那么正直的眼神看姐姐！你这样害得姐姐忽然好想向阿库娅女神忏悔！」</p><p>在爱丽丝以纯真的眼神注视之下，赛西莉抱着自己苦闷地挣扎。</p><p>不久之后，赛西莉说要让我们也吃吃琼脂史莱姆，便逃进厨房里……</p><p>「啊——！又遭殃了！」</p><p>然后突然放声这么惨叫。</p><p>——我们走进厨房，在附近寻找有没有什么线索。</p><p>「离开教堂之前里面确实还有食材对吧？」</p><p>「有，不会错的。因为琼脂史莱姆的粉末也存放在这里，那个时候我也确认过食材的数量。」</p><p>犯案时间只有我们去卖那个怪东西的这不到一个小时。</p><p>我不知道犯人到底带走了多少食材，但除非是待在教堂外面监视，看见我们都出门之后就动手，不然应该无法以如此精湛的手法犯案才对。</p><p>这时，爱丽丝突然大声表示：</p><p>「赛西莉大姐姐，请看这边，这里有可疑的痕迹！这显然是某种拖行的痕迹，应该是带走食物的人留下来的吧？」</p><p>我看了一下，确实有某种将油性物体与地板接触并拖行之的痕迹。</p><p>赛西莉看了，一脸认真地点了一下头。</p><p>「这是不久之前，我在炸天妇罗的时候摔了一跤，打翻了锅子。我还记得，那个时候我全身沾满了油在地上打磙，还一边对自己施展恢复魔法，一边爬行。」</p><p>这个人到底在干嘛啊？</p><p>这时，轮到打开魔道冰箱的悠悠有了新发现。</p><p>「赛西莉小姐，你看这个！不知为何，冰箱里面有……就是那个……男性用的内裤！在女性住在里面生活的这间教堂的冰箱当中放了这种东西，犯人肯定是个变态！」</p><p>听她这么一说，我看了看冰箱里面，确实放了一件冰凉的内裤。</p><p>大概是因为同样身为女性，看见这种性骚扰无法置之不理吧。</p><p>悠悠拿起那条内裤，用力握紧，显得相当气愤。</p><p>面对这样的悠悠，赛西莉再次一脸认真地点了一下头。</p><p>「那是一位家里没有冰箱的男性阿克西斯教徒放在里面的。他说洗完澡之后就是要穿冰凉的内裤才舒服，所以每天去福斯浴场之后回程都会绕过来这里。」</p><p>正当悠悠奋力甩开那件内裤时，赛西莉下定决心大喊：</p><p>「再这样下去也没完没了。惠惠小姐，既然事情都已经变成这样了，我们直接去找可能对我怀恨在心的人，一个一个问清楚吧！惠惠小姐只要在我后面亮起红眼，用力挥舞法杖就可以了。然后我会这么说！你应该有话要告诉我才对吧？不乖乖开口的话，后面那个红魔族会怎么样我可不知道……」</p><p>「我不会协助你恐吓别人喔！请你好好跟人家谈！」</p><p>——第一个嫌犯，是地点离阿克西斯教堂最近的肉店的大叔，我们决定先找他问话。</p><p>「好了，请你一五一十地招出来吧！之前我说『请给我像十四岁左右的女生的脸颊一样柔软的肉』的时候，你说谁知道啊，还一副很不耐烦的样子对吧？后来我开始散播『那间肉店根本不懂肉的好坏，是一间没用的肉店』的流言，所以你就愤而犯案……」</p><p>「喂，你等一下，你上次来店里提出那种脑洞的要求妨碍我做生意也就算了，居然还散播那种谣言吗！跟我一起去警察局，我要告你妨碍营业！」</p><p>「啊啊，请、请你先等一下，别闹上警察局！最近我每次去那里的时候，有个感觉人还不错的年轻小伙子就会露出轻蔑的眼神说『怎么又是你』！至少等我先确认过那个小伙子有没有恋人之后再说……！」</p><p>……还是丢下她先走人好了。</p><p>我以这样的眼神看向悠悠，结果她好像难得接收到我的讯息了，点头如捣蒜。</p><p>好，走人吧。</p><p>「……不好意思，这位叔叔，请您先等一下。我也向您道歉，可以请您原谅赛西莉大姐姐吗？」</p><p>在难以化解的紧张气氛之中，突然响起天真纯洁的少女的声音。</p><p>「这、这个嘛。没有啦，该怎么说呢，说要上警局是我太冲动了。好、好了。看在这个小妹妹的分上，我原谅你就是了，你可别再做出这种事情来了喔。」</p><p>在爱丽丝以央求的眼神注视之下，肉店的大叔别过头去，对赛西莉撂下这句话。</p><p>目送着大叔慢步走回店里的身影，赛西莉哭丧着脸，巴住爱丽丝。</p><p>「啊啊啊啊依丽丝小姐谢谢你咿咿咿！为了答谢你，姐姐收你当妹妹！」</p><p>「这、这个就……不用了……我最近才刚多了一个新的哥哥……」</p><p>望着困惑的爱丽丝，我心里想着错失了丢下赛西莉的机会，正觉得有点可惜的时候。</p><p>「刚才真是好险啊。被那个大叔套话了。」</p><p>「是大姐姐自己大嘴巴，自己被逮到而已吧。」</p><p>重新振作起来的赛西莉没有理会我的吐嘈。</p><p>「接下来就去那里吧！没错，就近一个一个问这种想法根本大错特错！应该直接去概率最高的地方逼供才对！」</p><p>她这么说完，没有等我们回应就冲了出去。</p><p>「她好有行动力喔……」</p><p>爱丽丝说出这样的感想，不过我觉得那不能说是有行动力，只是什么都没在想而已。</p><p>「……呐，惠惠，今天还是应该吃完便当就回家才对吧。」</p><p>唯有今天我无法反驳。</p><h3 id="_6-1" tabindex="-1"><a class="header-anchor" href="#_6-1"><span>6</span></a></h3><p>我们跟在赛西莉身后追了上去，结果该说是不出所料呢，还是该说果然是阿克西斯教团的宿敌呢。</p><p>「混帐，该死的艾莉丝教徒，快磙出来！把我留着舍不得吃的统二布丁还给我！」</p><p>赛西莉一脚又一脚踹着艾莉丝教团的教堂的门。</p><p>「依丽丝不可以看！不要看人的那一面，你要维持着心灵的纯净继续成长。」</p><p>为了不让爱丽丝看见赛西莉现在的模样，悠悠从她身后捂住她的眼睛。</p>`,90),e(m,{src:`/images/C1/10.avif`,alt:`插图`,width:`850`,height:`1257`}),l[16]||=s(`<p>「大姐姐，你怎么没头没脑的就这样乱来啊？我知道你和艾莉丝教团的关系很不好，不过这样也太躁进了吧！」</p><p>尽管我打算带走赛西莉，她却开始拍打教堂的门，不肯从教堂前面离开。</p><p>就在这个时候。</p><p>「你怎么又跑来了！都叫你别再来我们的教堂了，到底要说几次你才听得懂啊！」</p><p>艾莉丝教的祭司打开教堂的门，出现在我们面前。</p><p>——我们说明了状况之后，艾莉丝教的祭司重重叹了口气。</p><p>「不好意思，我们平常忙着治疗冒险者们的伤势、分发救济餐，并没有闲到可以去你们的教堂捣乱。而且我们并不缺乏食物。侍奉艾莉丝女神的我们怎么可能会偷东西呢？」</p><p>「骗子！真的不缺食物的话，上次我故意在你眼前啃串烧给你看的时候，你就不会用那种眼神看着我了！」</p><p>「你还做了这种事啊？」</p><p>尽管我傻眼地如此嘀咕，不知为何艾莉丝教的祭司却瞬间露出畏缩的表情。</p><p>「艾莉丝教以清贫为美德。不过是有人在眼前吃串烧，我才不会……」</p><p>「啊！你又说谎了！我说艾莉丝教徒就是因为缺乏蛋白质才不会长胸的时候，你明明还挺烦恼的！」</p><p>「你、你这个家伙，可恨的叛教者，竟敢口出狂言！」</p><p>拉开又开始打架的两个人之后，我忍不住出言抱怨：</p><p>「我知道两位的宗派之间关系并不好，可是为什么你们身为神职人员却老是打架啊？」</p><p>艾莉丝教的祭司似乎因为自己沦落到和赛西莉一样的水准而感到羞耻，脸赫然变红。</p><p>「呜……这、这个嘛。我真是太丢脸了……」</p><p>「哈哈哈，被骂了吧！」</p><p>「大姐姐也一样啦！」</p><p>正当我对在我背后继续挑衅的赛西莉感到傻眼的时候。</p><p>「可是，这个胸埝祭司也不知情的话，到底是谁啊……想得到的人还剩下太多了，真的完全无法锁定是谁干的……」</p><p>「你再不收敛一点的话，小心我拿锤头杖去你的教堂踢馆喔。」</p><p>我硬逼赛西莉向遮住胸部的艾莉丝教祭司道歉之后，离开了现场。</p><p>该怎么说呢，这真的是挟怨报复吗？</p><p>毕竟，就像艾莉丝教徒刚才的反应一样，无论有多火大，大家还是不会想跟阿克西斯教徒扯上关系。</p><p>既然如此，就算稍微吃了点亏也不会有人去报复吧？</p><p>「大姐姐，我们再回教堂去看一下如何？」</p><p>我对正打算在艾莉丝教堂的招牌上涂鸦，但遭到悠悠和爱丽丝制止的赛西莉如此提议。</p><p>「——又遭殃了。」</p><p>回到教堂之后便这么表示的赛西莉瘫坐在地上。</p><p>「损失多少啊？我觉得看起来没有比刚才少太多耶……」</p><p>我瞄了一下坐在冰箱前面的赛西莉，看着里面的东西，但是看不出太大的变化。</p><p>「我放在最里面的琼脂史莱姆不见了……这到底是第几次了啊……每次都可以针对我最喜欢吃的东西来偷，难不成这也是魔王军搞的鬼吗？」</p><p>「我不觉得魔王军会来一间小教堂从冰箱里面偷走点心就是了，不过我注意到一件事情。」</p><p>刚才爱丽丝找到的那个拖行的痕迹。</p><p>那个痕迹从厨房一直延续到教堂的后门。</p><p>我记得赛西莉说，遭窃的有教堂的冰箱，和后面的田里的作物。</p><p>我用力推开后门一看——！</p><p>「……那个，大姐姐。琼脂史莱姆在吃蔬菜耶。」</p><p>「啊啊，怎么会这样！应该已经被我宰掉的史莱姆居然活力十足地大吃特吃……！难道是阿库娅女神引发的奇迹吗！」</p><p>「赛西莉小姐，这怎么看都是史莱姆引发的事件吧！请你去向怀疑过的人们道歉！」</p><p>「——真是一起……令人讨厌的事件呢……」</p><p>犯人是被赛西莉魔改之后，生命力变得更加旺盛的史莱姆。</p><p>见赛西莉看着远方，一点也没有要反省的意思，我和悠悠便开始教训她，训着训着却被爱丽丝制止，说适可而止就好。</p><p>「真是的，依丽丝应该要多了解一下阿克西斯教徒才对。再怎么不谙世事，也该有个限度吧。」</p><p>「虽然你们这么说，可是我不觉得赛西莉大姐姐是个多坏的人啊……对于看人的眼光，我很有自信喔。」</p><p>我觉得她的眼睛大概和阿库娅差不多瞎。</p><p>这时，我发现挨了我们骂的赛西莉好像不太对劲。</p><p>自动跪坐在地板上的赛西莉，整个人不停微微颤抖……</p><p>「依丽丝小姐，请你务必要加入阿克西斯教团！没错，你绝对应该这么做！」</p><p>「依丽丝，今天该回家了。打从一开始我就不该带你来这里，我也不会再带你来这里，所以请你把今天发生过的事情全部忘掉吧。」</p><p>光是把爱丽丝带到王城外面来就已经够糟糕了，要是她在我不注意的时候被迫加入阿克西斯教，那我肯定只有死刑一途。</p><p>「赛西莉大姐姐，我对阿克西斯教的教义不太清楚，请问到底有些哪些内容呢？」</p><p>「问得好！依丽丝小姐有没有在忍耐什么事情啊？以我们阿克西斯教的教义来说，忍耐对身体有害，请忠于自己而活，这就是最主要的教义。可以做自己喜欢的事情。可以再任性一点也没关系。如果有喜欢的人的话，无论对方的身分地位有多么崇高也不需要忍耐，反而应该想着来硬的也要将喜欢的人的身分地位拉低到和自己一样的水平，凭着这样的冲劲行动才对。」</p><p>「依丽丝，不可以听！乖，把耳朵捂起来！」</p><p>见赛西莉兴高采烈地开始传教，悠悠便赶紧捂住爱丽丝的耳朵。</p><p>——就在这个时候。</p><p>有人勐然打开教堂的大门，同时，一道熟悉的声音在里头回荡。</p><p>「消息指出有个金发碧眼的可爱少女被带进这里来了。所有人不准抵抗，乖乖就范……啊啊，依丽丝小姐！我找到您了！」</p><p>出现在那里的是身穿白色套装的女护卫，克莱儿。</p><p>爱丽丝见状便垂头丧气，垮着肩膀说：</p><p>「已经到了来接我的时间了啊……」</p><p>「依丽丝小姐，并不是来迎接您的时间到了！我一开始就不曾允许过您出来外面游荡啊！」</p><p>感觉越来越习惯这个状况的爱丽丝害得克莱儿不禁如此吐嘈，这时，赛西莉快步走向克莱儿。</p><p>「不好意思，请问您是……？初次见面，我是本教堂的负责人兼任祭司，阿克西斯教团阿克塞尔分部长，名叫赛西莉。依丽丝小姐在这里由本教堂照顾得相当妥善，所以用不着担心。您尽管放心吧。」</p><p>说着，明明是反过来被我们照顾得相当妥当的赛西莉，以完全不像是阿克西斯教徒的真诚态度应对自如。</p><p>「咦？这、这样啊，劳烦您了。」</p><p>或许是被赛西莉影响了吧，克莱儿瞬间困惑了一下之后……</p><p>「我是依丽丝小姐的护卫，名叫克莱儿。看来依丽丝小姐似乎受到了您的照顾，真是非常感谢您。原来阿克西斯教团当中也有像您这样的人啊。」</p><p>也跟着这么说，并且端正姿势，深深一鞠躬。</p><p>这位大姐姐明明相当易怒，之前甚至还想拔刀砍向和真，但如果是为了爱丽丝，好像也能够如此以礼待人。</p><p>正当我像这样偷偷在心中感到佩服的时候。</p><p>「这样啊，您是依丽丝小姐的护卫……我现在正好在为依丽丝小姐讲授阿克西斯教的教义。如何？护卫小姐也请一起听吧。」</p><p>「讲授阿克西斯教教义！不、不用了，我不能容许那种会引发重大问题的事情……不对，应该说依丽丝小姐尚未成年，所以您这样做会造成我们的困扰……更何况，依丽丝小姐必须维持公平的观点才行，所以若是倾向特定的宗派，会让我们很为难……」</p><p>在对方是明智的神职人员，又是女性的状况下，即使是克莱儿也无法过于强硬，只能设法婉拒。</p><p>「您很适合当阿克西斯教徒。我看得出来，因为我从您身上感觉到志同道合的气息。」</p><p>「志、志同道合的气息……」</p><p>克莱儿露出有点厌恶的表情，闻了闻自己的衣袖。</p><p>「您是不是犯了不可能结合的相思病？心中是不是怀有不见容于世的爱意？在阿克西斯教，只要对象并非不死怪物和恶魔女孩，无论是同性还是身分地位差距，一切的一切都可以得到宽容。」</p><p>「无论是同性还是身分地位差距都没关系吗！这这、这真是太……可是……」</p><p>不知道是阿克西斯教的哪个部分触动了她的心弦，只见克莱儿显得动摇不已。</p><p>「来吧，忍耐对身体有害喔。忍耐这两个字违反阿克西斯教的教义。顺从您的渴望，依循您的意念……！」</p><p>「啊啊啊啊！我、我今天就先告退了！依丽丝小姐，请向各位道别！」</p><p>大概是觉得再听下去会不太妙，克莱儿牵起依丽丝的手，连忙准备离开教堂。</p><p>「……那么，头目大人、悠悠小姐、赛西莉大姐姐，明天见！」</p><p>「没有明天见！您别想出门，我明天会监视您一整天！」</p><p>知道要被带回去的时候还垂头丧气的爱丽丝，现在不知为何一脸开朗，向我们挥了挥手就被带走了。</p><p>「——感觉明明很有可能成功的说，可惜被她跑走了……」</p><p>赛西莉遗憾地表示。</p><p>她觉得很有可能成功的是爱丽丝，还是克莱儿呢？</p><p>感觉只要再用力劝说一下，两个人都很有可能加入阿克西斯教团，让我感到很害怕。</p><p>「惠惠，那位克莱儿小姐说『依丽丝小姐必须维持公正的观点才行』对吧，那依丽丝该不会是……」</p><p>说到这里，悠悠用力甩了甩头。</p><p>像是想说「这不可能」似的。</p><p>而我丢下这样的悠悠，转身面对赛西莉。</p><p>「大姐姐。」</p><p>「你以前叫过我赛西莉姐姐的，真希望你改回去……」</p><p>我对依然故我的赛西莉说：</p><p>「其实，我们希望打工不是只有这次，今后也想持续赚钱。」</p><p>「这对我而言也是好事一桩。除了『阿克西斯教团的那个』以外，我还有很多应该赚得到钱的好主意喔。『美少女捏的饭团』、『美少女吹的气球』、『美少女……』……」</p><p>「全都只是美少女做的东西而已嘛！可以的话我希望是比较正当一点的赚钱方式……」</p><p>听我这么说，赛西莉开心地咯咯笑了几声。</p><p>「你这么想赚钱，是不是和刚才被带回去的依丽丝小姐有关啊？」</p><p>赛西莉平常明明是个很随便的人，只有在这种时候就像是完全看穿了我的想法似的。</p><p>「这个嘛，和那个孩子也算是有点关系啦。如果我们能够稳定地赚取资金，逐渐将吾等之组织做大的话，我相信，总有一天，协助那个人打倒魔王也不是白日梦……」</p><p>「打倒魔王也不是白日梦啊，口气还真不小呢！」</p><p>没错，并不是白日梦。</p><p>我总觉得，那个难以捉摸的面具盗贼应该连魔王都有办法打倒。</p><p>然后，如果打倒了魔王的话……</p><p>「等到世间因为没有魔王而变得和平之后，我想，那个孩子一定可以比现在更自由地在外面走动吧。」</p><p>到时候，无论要像今天一样出来野餐还是要约她做什么都可以了吧。</p><p>那个孩子一定也会很开心才对。</p><p>「关于赚钱这回事我不太拿手，所以可以请你协助我吗？大姐姐感觉很擅长想各种方式来赚钱。」</p><p>照理来说，我其实大可拜托那个男人就是了。</p><p>不过，等到我们的组织变得更大之后，我是想向他炫耀没错。</p><p>悠悠对于我想拜托这位令人伤脑筋的大姐姐这个决定似乎也没有什么异议，还带着有点开心的表情点了头。</p><p>然而……</p><p>「我可不会轻易答应喔。」</p><p>赛西莉摇了摇头，像是想说不会被这种博取同情的说词所蒙蔽。</p><p>「我是特别喜爱小萝莉的阿克西斯教徒。既然依丽丝小姐和惠惠小姐、悠悠小姐在做那么好玩的事情……」</p><p>然后突然冒出这番令人无言的台词，眼睛闪闪发亮地表示：</p><p>「如果你们让大姐姐也加入那个可疑的组织，大姐姐就愿意答应！」</p><h3 id="_7-1" tabindex="-1"><a class="header-anchor" href="#_7-1"><span>7</span></a></h3><p>「——我回来了～～」</p><p>「嗨，你回来啦，惠惠。今天我要大展厨艺，好好做一顿大餐！敬请期待！」</p><p>今天同样回到豪宅之后，呼吸急促的达克妮丝跑出来迎接我。</p><p>接着，没规矩地躺在大厅沙发上的和真说：</p><p>「呐，惠惠，你也去阻止她一下啦。我昨天不过是稍微嫌弃了一下她的料理，这个家伙就说什么今天一定要让我刮目相看，有够难搞的。」</p><p>「不准说我难搞！明明就是因为你这个家伙瞧不起我！你等着瞧，再怎么说我也是个女人，我今天的料理绝对不会输给你这个尼特！」</p><p>正当达克妮丝一边发脾气，一边准备窝回厨房里的时候，和真对这样的她说：</p><p>「喂，达克妮丝，像昨天那种汤汤水水的东西不合我的喜好喔——！那或许是高级料理，不过我喜欢的是更垃圾食物类的东西。我今天想吃比较油腻的料理。」</p><p>「油腻的料理啊……我都已经煮了，不过既然你都这么说那也没办法，我就另外再追加一道菜好了。真是的，想这样耍任性的话就不能早点说吗……」</p><p>这时，达克妮丝的话还没说完，换成阿库娅打断了她。</p><p>「我想吃清爽一点的东西耶。如果是口感滑熘的东西就更好了。」</p><p>「口感滑熘……我想想，那就是面类喽？呜呜，没办法，我现在马上再追加那一道就是了……惠、惠惠呢？」</p><p>连阿库娅也追加指定了一道菜之后，达克妮丝也问了我有没有什么要求。</p><p>「你已经煮了对吧？那我吃那个就可以了，达克妮丝煮的东西虽然普通，但也没有不好吃的。」</p><p>「不要连惠惠都说普通好吗！不过，你没有乱点东西真是太好了。我现在马上准备追加的料理，你们稍等一下。」</p><p>说完，达克妮丝又窝回厨房里，阿库娅则是拿着那套战棋游戏来到躺在沙发上的和真身边。</p><p>「和真先生、和真先生，在晚餐煮好之前和我对战一局吧。今天的我不太一样喔。毕竟我今天有压箱底的秘密计策。」</p><p>阿库娅一边说着这种怎么听都是败战旗标的台词，一边迅速摆好棋子。</p><p>「什么压箱底的秘密计策啊。你上次也说过同样的话，还说『既然没有时间限制我就用牛步战术！我的脑袋或许拼不过你，不过比体力的话我可不会输！我会花上很多时间，玩到熬夜也在所不惜，你就好好加油吧！』之类莫名其妙的台词，结果才开始玩十分钟你就睡着了。」</p><p>「吵死了，那个归那个，这个归这个好吗。嘿嘿，我这次的计策很厉害喔！先攻让给和真。来，请下吧。」</p><p>相对于自信满满的阿库娅，和真动了一颗棋。</p><p>「你中计了和真！聪明的我想过了。只要故意选择后攻，和对手走完全一样的棋步就可以了！换句话说，对手等于是在跟实力与自己相当的人对决。可是，执行这个战术的人是我。没错，只有对手的力量会战到不相上下，但如果再加上我的力量呢？」</p><p>自信十足的阿库娅一边这么说，一边走了与和真完全相同的棋步。</p><p>「没错，这个划时代的作战计划能够赢过任何对手，是可怕秘密策略！我不需要思考任何事情，只要模仿对手下棋就好。等到对手因疲劳而失误的瞬间，我再拿出真本事……！」</p><p>说到这里，阿库娅僵住了。</p><p>看来她很快就陷入了危机。</p><p>自己说出要模仿对手下棋的话，只会被先攻的人任意摆布。</p><p>没有理会烦恼到开始低吟的阿库娅，我抱起跑到我脚边来磨蹭的点仔，同时报告今天发生的事情。</p><p>「和真，我今天的战果相当丰硕喔。首先，吾等军团成功获得了今后的活跃所需的稳定资金来源。如此一来可以说是朝目标迈进了一大步吧。」</p><p>听我这么说的同时，和真的视线没有从棋盘上移开。</p><p>「那真是太好了。获得资金来源是怎么办到的啊，你们去打工吗？」</p><p>「算是吧。我们接了公会的委托，还打倒了史莱姆。」</p><p>然后用力下了一步棋。</p><p>「驱除史莱姆啊。如果是这种程度的委托，以你的等级或许不会有危险，但要是其他小朋友面临危机的话，你可要出手救他们喔。哎呀，这么快就将军了啊。」</p><p>「呐，太奇怪了吧。我们明明是走同样的棋步，为什么是我比较不利啊？」</p><p>看来他好像还是只把我在做的事情当成小朋友在玩耍的样子。</p><p>他可能以为我只是和附近的小朋友一起赶跑了史莱姆吧。</p><p>也罢。</p><p>等到组织变得更大，大到会让和真吓到软脚的规模之后再好好告诉他真相也不错。</p><p>「各位，晚餐煮好了。今天你们绝对无从挑剔。好了，到位子上坐好吧！」</p><p>在我帮忙将达克妮丝端出来的晚餐摆到桌上的同时。</p><p>「这么说来，还有一件事。」</p><p>相对于缓缓下了一步棋的阿库娅，和真不假思索地反击，迅速解决掉棋局。而我对这样的他说：</p><p>「我们又多了一位新团员。」</p><h2 id="第三话-乱闯的盗贼团" tabindex="-1"><a class="header-anchor" href="#第三话-乱闯的盗贼团"><span>第三话 乱闯的盗贼团</span></a></h2>`,168),e(m,{src:`/images/C1/20.avif`,alt:`章节标题`,collapsed:``,width:`850`,height:`1257`}),l[17]||=s(`<h3 id="_1-2" tabindex="-1"><a class="header-anchor" href="#_1-2"><span>1</span></a></h3><p>——太顺利了。</p><p>首先，我们在盗贼团成立的第一天就得到了秘密基……我是说活动据点，以及力量强大的基层战斗员。</p><p>然后上次也成功获得定期收取零用钱……不对，我是指盗贼团的资金来源，以及会用恢复魔法的团员。</p><p>老实说，我没有想到会进展得这么顺利。</p><p>应该说，感觉组织规模会变得比我当初设想的还要大。</p><p>因为……</p><p>「——惠惠小姐，听我说听我说！大姐姐寄信回阿克西斯教团的总部报告这个盗贼团的事情，结果想要入团的询问度高到爆表。这应该是一举扩大势力的大好机会吧。」</p><p>借机把行李搬进我们当作活动据点的，阿克塞尔最大的宅邸里住了下来，现在已经把自己当成宅邸主人的赛西莉对我这么说。</p><p>「……阿克西斯教徒啊。不好意思，让我稍微考虑一下。」</p><p>占领了看起来很贵的沙发在上面磙来磙去的赛西莉，那个模样让我联想到我们家的阿库娅。</p><p>如果阿克西斯教徒全都像这样的话，我实在不太想答应让他们入团。</p><p>「我在信上写到成员除了我以外只有小萝莉，结果杰斯塔大人就说要辞去教主之位过来这里，好像还闹出了一阵骚动呢。要是碰上了什么麻烦，阿克西斯教团随时都愿意协助你们喔。」</p><p>「谢、谢谢大姐姐，要是真的有需要的话再拜托你们了。」</p><p>我不禁感到浑身无力，应该不只是因为使用过爆裂魔法之后耗尽魔力的缘故吧。</p><p>这时，刚才还在读信的悠悠也坐立难安地对着和赛西莉一样把自己埋进沙发里的我说：</p><p>「那、那个，惠惠？我最近也写了信给父亲大人，结果回信上面说我们在做的事情好像很帅气又很好玩，所以红魔之里也有很多人表示希望可以加入我们耶……」</p><p>「…………不，红魔族的大家有监视魔王城这个重大任务在身，而且更是在王都陷入危机的紧急事态时以备不时之需，形同隐藏王牌的战力，不可以来这种地方吧。」</p><p>故乡的各位以战力而言无从挑剔。</p><p>没错，如果是要闯进魔王城的话确实无从挑剔，但是我们要对付的只是黑心贵族。而且我们不是要攻进去当强盗，而是当义贼。</p><p>「说的也是，我还想说同伴可能又会变多，开心到都忘了。那我就回信说，要是碰上什么麻烦再请大家帮忙好了。」</p><p>「说、说的也是，到时候再说……」</p><p>在我支吾其词的时候，对于同伴增加感到无上喜悦的那个永远的边缘人露出笑容。</p><p>看来，规模真的会变得比我当初设想的还要大。</p><p>没错，因为——</p><p>「之前我自豪地对父亲大人说我和朋友们组成了一个正义的团体，父亲大人便表示需要人手的话想带几个优秀的骑士去都可以。父亲大人还说，需要资金的时候无论需要多少都可以拿走！头目大人，要是碰上什么麻烦的话随时都可以告诉我喔！」</p><p>……嗯，真的是太顺利了。</p><p>不过，总觉得团体的规模快要和我当初设定的完全不一样了。</p><h3 id="_2-2" tabindex="-1"><a class="header-anchor" href="#_2-2"><span>2</span></a></h3><p>事情就是这样。</p><p>「你们三个的入团申请人名册我都收到了，不过我没办法完全看完。应该说，这些光论人数就已经比不怎么样的骑士团或佣兵团还要多了。我们的目的，是要暗中协助即使遭到悬赏也要坚持自己的道路的银发盗贼团，可是如此一来无论怎么想都没办法暗中行动吧。」</p><p>我稍微休息了一下，魔力恢复到能够行动的程度之后，便稍微浏览了一下她们三个给我的一大叠纸张。</p><p>阿克西斯教徒和红魔族，甚至是在王都也相当出名的骑士和武功高强的冒险者。</p><p>我们的目标是像他们那种少数精英制的盗贼团。</p><p>我并不是因为突发奇想而开始的事情变得比自己设想的还要夸张而开始退缩。</p><p>正当我苦口婆心地如此劝说她们的时候，悠悠扬起嘴角傻笑。</p><p>「……喂，你有话想说的话就说啊，我洗耳恭听。」</p><p>「没有啊～～？我并没有觉得惠惠还是一样不擅长处理超乎预期的事情喔。」</p><p>听那个边缘人说得好像她早已看穿我的个性似的，于是我摆出架势准备攻击她，这时爱丽丝坐立难安地对我说：</p><p>「头目大人，你说的我都明白，不过至少再多找几个人吧？我们有两个魔法师、一个祭司。剑和魔法我都会用，所以在这个小队我可以担任前锋，但是我希望至少可以再多一个前锋职业的成员。」</p><p>「我们不是要去冒险打倒怪物，所以没有讲究队伍平衡度的必要喔。应该说，以袭击贵族的宅邸而言，我觉得现在的战力都已经过强了。」</p><p>有两名红魔族的大法师，甚至还有继承勇者血统，强到破坏平衡的公主殿下。</p><p>剩下一个的实力如何我不太清楚，不过光是作为事有万一的时候能够负责恢复的成员待在队上就已经是一大助力了。</p><p>然而，爱丽丝一脸伤脑筋地表示：</p><p>「不好意思，我们可以偶尔去冒险一下吗？而且我也想要在团内有个后辈，不然我永远都是最基层的一个……」</p><p>「……关于冒险呢，因为那个边缘人的眼睛也闪闪发亮，一副很期待的样子，我会考虑看看。话说回来，你是因为那种无聊的理由才想要新团员吗？真拿你没办法，我升你为吾之左手就是了，你忍耐一下吧。顺便告诉你，右手是悠悠，所以你可是第三把交椅喔。」</p><p>无论头衔是右手还是左手，我们既不发薪水，也没有津贴，所以光是说说也不用钱。</p><p>而且我们只有四个人，就算是第三把交椅也没有什么了不起的，但是爱丽丝听了还是天真地开心了起来。</p><p>再怎么强，她也不过是个小朋友。</p><p>这个孩子或许意外的和悠悠一样好骗。</p><p>「大姐姐呢？呐，惠惠小姐，你可以封大姐姐一个什么吗？也给大姐姐一个可以向人炫耀的头衔吧！」</p><p>问题是这个有时候比爱丽丝还要幼稚的成年人。</p><p>我对抓着我的肩膀不住摇晃的赛西莉表示：</p><p>「大姐姐已经是阿克西斯教团的阿克塞尔分部长了啊，这个头衔已经够气派了吧。」</p><p>「不是那种啦！什么都好，我也想要像是右手啦左手啦情人啦情妇啦老公啦老婆啦那种更亲密的职位！」</p><p>「你说到一半就开始偷渡奇怪的词汇了喔！……不然顾问之类的应该可以吧。身为祭司，大姐姐应该也会在听教徒忏悔的时候给人家意见，要是碰上什么问题的话我就找大姐姐商量…………商量……」</p><p>找这个人商量……？</p><p>「为什么不把话说完啊？碰上问题的时候随时都可以找大姐姐商量喔！尤其是恋爱的问题大姐姐最懂了！惠惠小姐现在正值青春期，不是正好吗？」</p><p>正当我觉得赛西莉是个任性的成年人时，她突然说出这种令我为之动摇的话语。</p><p>该怎么说呢，这个人有时候真的很敏锐。</p><p>我努力不让内心的动摇显露出来，并且说：</p><p>「你怎么会说这种话啊，大姐姐。我是打算穷究爆裂道之人，才没有时间为了儿女私情而分心呢。」</p><p>「就是说啊，赛西莉小姐。要是惠惠开始讨论起恋爱话题，就要怀疑是幻形妖变的冒牌货喔。」</p><p>正当爱丽丝坐立难安地观望着话题的去向时，三人当中和我的交情最久，眼睛却不知道长到哪里去的悠悠乱插嘴揶揄我。</p><p>……该怎么说呢，这个孩子偶尔就是少根筋。</p><p>「嗯——根据大姐姐的看法，最近的惠惠小姐该说是变得比较有机可乘呢，还是说待人接物的态度变得柔和多了……而且偶尔会露出那种怎么看都很少女的表情。」</p><p>我本来还想说不过就是阿克西斯教徒，但这个大姐姐或许并不是普通的怪人。</p><p>「说穿了，你一定是对大姐姐抱持着近似爱意的崇拜对吧！毕竟你正值青春期嘛，这也是没有办法的事情。站在大姐姐的立场是随时欢迎你喔！对了，每个星期惠惠小姐当四天老公，我当三天如何？我觉得惠惠小姐比较适合当男生。」</p><p>看来是我多心了。</p><p>或许是对恋爱话题这四个字有兴趣吧，爱丽丝一副按捺不住，欲言又止的样子，但是我不想再被追问下去了。</p><p>「你们够了喔！言归正传……如此一来，我们就已经得到活动据点和资金来源了。接下来要聚集优秀的人才。目前我们团内只有奇人异士，是该找个正常一点的人的时候了。」</p><p>「你给我等一下，我们当中最奇异的就是你了，居然还敢说这种话。不过，事后找个正常人入团这一点我也赞成。比方说，除了像这样聚在一起的时候以外也愿意和我一起去吃饭，心地善良的人……」</p><p>「头目大人，找前锋！找个前锋冒险者才方便去冒险！」</p><p>「根据大姐姐的情报，这个镇上既年轻又有钱的男人大概有四个。只要是上流阶级的金发型男我都不会挑剔，不过如果是愿意一辈子宠我惯我的人我也不是不愿意妥协。」</p><p>这些家伙怎么各个都这么不合群啊。</p><p>我开始觉得和真平常能够统率我们好像是一件非常厉害的事情了。</p><p>「不，我们要找思想健全，职业是盗贼的团员。这不是在找朋友，也不是在找冒险同伴，更不是在找老公。目前我们的团员组成都跟盗贼团差太远了。」</p><p>「大姐姐经常在抢夺艾莉丝教徒的救济餐被他们叫成小偷，所以应该也可以称得上是适合加入盗贼团的人才吧。」</p><p>「你想从祭司改行当盗贼吗？我可以带你去冒险者公会，真的叫你转职喔。」</p><p>就在这个时候。</p><p>「说到上流阶级的金发型男和人才，各位知道这件事吗？听说这个镇上，其实有一位在邻国原本是贵族身分的人在当冒险者呢。」</p><p>爱丽丝突然提起这件事，不知为何眼睛还闪闪发亮。</p>`,82),e(m,{src:`/images/C1/07.avif`,alt:`插图`,width:`850`,height:`1257`}),l[18]||=s(`<p>贵族那些人基本上天生都具备着高强的能力。</p><p>这是因为，虽然不像爱丽丝他们王族那么彻底，不过贵族也经常将女儿嫁给号称英雄或勇者的人们为妾，积极采纳其血统。</p><p>「原本是贵族的人？虽然不知道家道中落的原因是什么，不过他应该有可能还藏了一些财产呢。大姐姐也对这件事很感兴趣。」</p><p>就连对潜在能力与实力以外的部分产生了兴趣的赛西莉，也跟着眼睛闪闪发亮了起来。</p><p>「这在许多国家的王族和贵族之间是相当有名的故事。邻国有一名下级贵族少年，当上了名为龙骑士的超稀有职业，而且还创下了最年少纪录。听说那名少年展现出身为龙骑士的优异才能，使起长枪可谓王国第一，而且天生就受到龙族喜爱，个性老实、诚恳、有耐性、人品极佳，简直就是骑士的楷模。想当然耳，他也是年轻女性们倾慕的对象，然而……」</p><p>据说，那名少年年纪轻轻就被任命为该国公主的护卫。</p><p>年纪与少年相仿的公主，会对人人倾慕的他怀有淡淡的情愫，也是无法避免的事情。</p><p>身为王族，公主当然有未婚夫，而且因为身分地位之差，也无法对少年表白自己的心意，每天过着既开心又难过的生活。</p><p>然而，偶然之间，那个少年知道了公主的心意……</p><p>「——在那之后，少年明知会引发严重的问题，还是带公主骑到龙的背上离开了。据说后来全国上下开始搜索，却完全掌握不到他们的踪迹。但在过了约莫一星期之后，少年带着公主再次回到城里。少年尽管没有被处刑，却被剥夺了龙骑士的资格，家门也遭到废除。」</p><p>爱丽丝不知为何说明得感慨万千，而听得入迷的我们则叹了口气。</p><p>「也就是说，他是个因为绑架公主殿下而让自己身为菁英的仕途毁于一旦的败家子吗？掳走公主殿下的工作一向都是由坏魔法师和魔王负责，抢走别人的工作是不好的事情。」</p><p>「不、不是啦！这个故事是在说两人的恋情因为身分地位之差而绝对不可能开花结果，但他却以自己的方式试图回应公主的心意，是个很棒的故事！根据我听来的说法，想要骑到龙的背上好像是公主殿下的心愿。然后，坐到少年身后的公主一定是这么说了吧——『如果可以就这样和你一起远走高飞就好了……』这样！」</p><p>「呀——！这是怎样，太棒了吧！也、也就是说，那个人为了实现公主殿下的一个小愿望，不惜舍弃了身为国家英雄的名誉和仕途吗……！」</p><p>听了想像力旺盛的爱丽丝的故事，不知为何连悠悠都显得有些亢奋。</p><p>「没错，就是这样！即使这么做的结果必须接受处分，他还是为公主实现了不被允许的梦想！这就是贵族和王族的千金们擅自妄想出来，广为流传的真相！如何？你们不觉得这样非常令人崇拜又帅气吗？虽然是一段悲恋故事，也让人难过又心酸……！」</p><p>她刚才是不是说了擅自妄想出来，广为流传的真相？</p><p>「依丽丝，你的意思是说，那个人被赶出国外之后，来到这个镇上当冒险者了吗？让他加入、让他加入，我们绝对要让那个人成为同伴！」</p><p>她们两个聊得一头热，越讲越起劲，不过如果这件事是真的，那确实有点帅气。</p><p>不，我说如果是真的的话。</p><p>无法开花结果的恋情，或许让同样身为公主殿下的爱丽丝有点感同身受吧。</p><p>还有，对于朋友和同伴都很少的悠悠而言，能够为别人如此牺牲奉献的人，大概也让她很心动吧。</p><p>「话说回来，他们逃亡的那一个星期内不知道到底发生过什么事呀。是不是发生过什么足以改变人生的重大事情呢？到、到底进展到什么程度了呢……！」</p><p>「依丽丝真是的，你在想像什么啊？那种事情……！那、那种事情……！」</p><p>两人红着脸不住尖叫，吵闹个没完。</p><p>……看来，纯粹只是那个状况很容易让正值青春期的她们胡思乱想而已。</p><p>「真是的，你们到底还要吵闹到什么时候啊，我们去找那个人吧。就连我都有过跟和真一起泡澡、睡在同一床棉被里的经验了。即使是以我们现在的关系来说，都有可能因为某种契机而一路冲到最后。他们两个的年纪一定比我们还要大，我想他们一定已经跨越最后一道界线了吧。」</p><p>「等一下，惠惠你刚才说了非常不得了的话对吧！」</p><p>「你说了对吧！」</p><p>坐在沙发上讨论得相当热烈的两个人弹了起来。</p><p>「哪有什么非常不得了的，以我们的年纪而言，没有这种程度的经验还比较奇怪吧。应该说，以我的状况而言，都已经和他住在一个屋檐下了，会这样也是理所当然。好了，我们快点去逮住那个高手吧。你们学一下大姐姐，人家那么冷静……」</p><p>正当我对捂着嘴巴，一脸惊愕的两人说到这里的时候。</p><p>「呐，惠惠，赛西莉小姐睡着了耶……」</p><p>「……叫醒她会搞得很麻烦，所以就这样让她睡下去吧。」</p><p>我好像可以体会老是在照顾阿库娅的和真的心情了。</p><h3 id="_3-2" tabindex="-1"><a class="header-anchor" href="#_3-2"><span>3</span></a></h3><p>我们走在阿克塞尔的后巷里，朝着冒险者公会前进。</p><p>之所以不走大路，是因为那些人今天应该也来找爱丽丝了才对。</p><p>就算要被带回去，当然也是尽可能在较为不起眼的状况下比较好。</p><p>「所以，我们该怎么找出那个原本是龙骑士的菁英贵族才好啊？」</p><p>感受着后巷特有的那种人烟罕至的氛围，我试着这么问爱丽丝。</p><p>「这个嘛……那位先生就像所有源远流长的贵族世家一样是金发。而且他拥有足以创下龙骑士的最年少纪录的实力，在这个城镇想必也立刻就崭露了头角。最后一个特征，大概就是他在邻国也是个相当厉害的长枪高手吧。」</p><p>金发男子在这个城镇很少见。</p><p>就算看到了，多半也是和贵族有关的人。</p><p>所以金发的男冒险者还真的是几乎没见过就是了……</p><p>「先、先别说这个了，头目大人？关于你刚才说你和兄长大人曾经一起泡澡、睡在同一床棉被里之类的那件事情……」</p><p>从刚才开始就一脸凝重的爱丽丝战战兢兢地这么问我。</p><p>「就是字面上的意思啊。无论如何，青春期的健全男女在一个屋檐下生活了将近一年，发生这种事情也不奇怪吧。」</p><p>「「！」」</p><p>我没有理会为之语塞的两人，露出赢家的笑容继续说了下去：</p><p>「除此之外，就像我之前提过的，我跟和真约好了，改天会在半夜去他的房间玩，不过要是随便跨越了最后一道界线会被他当成很容易拐到的轻浮女人。所以我一直延后，算是身为大人玩一些欲擒故纵的手法吧……」</p><p>听了我的英勇事迹，两人露出敬畏的表情，然而悠悠却说：</p><p>「反、反正你其实是怕了对吧？不然就是刚好被人阻挠之类。而且基本上，以惠惠的个性，除非是有什么契机，否则八成不可能会做出这种事情来。如果真的发生了这种事情，多半是在碰上什么令你大受打击的事情时，凭着自暴自弃的冲动之下而行动……大概会是这种感觉吧。」</p><p>「吵死了，连和男生牵手的经验都没有的边缘人懂什么啊！」</p><p>「！」</p><p>成熟的我瞬间逼到悠悠泪眼汪汪，于是立刻拿出记录着我和悠悠过去的对战成绩的纸张出来，添上一个胜场标记。</p><p>尽管以眼尾余光注意着我的动作，悠悠却佯装平静地喃喃说道：</p><p>「话说回来，金发又在镇上小有名气，擅使长枪的强者是吧……还有，一定也很彬彬有礼，为人老实又诚恳，又有绅士风范……而且……一、一定也是高大又帅气……的话就好了呢……」</p><p>「你说到一半就开始加入自己的期望了喔。不过，贵族多半都是相貌堂堂，传闻中的形象似乎也是很老实无误，所以大致上好像也没错啦……」</p><p>既然有这么多特征的话，一定很快就会找到了吧——</p><p>「那些特征全都具备的冒险者，我好像没听说过。」</p><p>不久之前我还乐天的这么想过。</p><p>抵达冒险者公会的我们立刻去问了柜台的大姐姐，然而……</p><p>「那有没有条件接近的人啊？用长枪的冒险者也没有那么多，而且这个城镇的冒险者当中问题儿童特别多，光是老实又诚恳应该就已经相当显眼了才对。」</p><p>「这里最显眼的冒险者小队就是惠惠小姐的队伍了喔。应该说，如果是一两项的话还有符合的人，全部符合的人我就想不到了……」</p><p>听见一脸伤脑筋的大姐姐这么说，我们面面相觑。</p><p>「……那么，可以介绍那些符合几项的人给我们认识吗？」</p><p>于是。</p><p>我们为了寻找过去在邻国声名远播的龙骑士，在柜台小姐的带领之下，前去见见符合条件的人——</p><p>「——我自认一生活到今日未曾做过见不得人的事情，也有活得相当真诚的自信。而且武功也还算不错，过去也算是颇为出名……不过，你们来找我这种经从第一线退下来的老人有什么事吗？」</p><p>柜台小姐第一个向我们介绍的是一位老爷爷。</p><p>「呃，算是有点想听老爷爷的英勇故事之类的吧。好了，依丽丝、悠悠，你们表现的时候到了。依丽丝那么崇拜冒险者，应该很喜欢听冒险故事吧？还有悠悠也是，你爱怎么跟人家聊天都可以。可以和人家聊天你很开心吧？」</p><p>「老爷爷，请您说说年轻时候的冒险故事吧！」</p><p>「咦咦！对我来说光是可以和人家聊天就很开心了是没有错啦，可是他和我们在找的人在年龄上完全不符合吧！」</p><p>我决定总之先把柜台小姐介绍的这位看起来很老实的老爷爷推给她们两个处理。</p><p>「——我的确还算出名，实力也算是相当不错，但是我从来没有握过长枪呢。不过，另外一种枪我倒是每天晚上都在握就是了！开玩笑的啦，哈哈哈哈哈！」</p><p>接下来介绍的是这个第一次见面就突然冒出最差劲的黄色笑话的冒险者，害我气到握起拳头。</p><p>「——长枪我确实很拿手，而且在练这项运动的人当中大概没有人不知道我的名字……不过我没想到会有女生对掷标枪这种运动有兴趣呢，还真是难得。」</p><p>甚至还介绍了不是冒险者的人。</p><p>然后——</p><p>「哦？怎么，这不是爆裂女孩吗。你找我到底有什么事情？如果要谈钱的事情我可没办法喔，毕竟没有任何地方愿意再借我钱了。我已经连喝酒的钱都没有了，不如说你借我钱吧，万一我得到一大笔钱再加倍还你。」</p><p>柜台小姐表示这是最后一位符合条件的人而介绍给我的，是名叫达斯特的金发小混混。</p><p>嘴上说着没钱却不去工作的达斯特，大白天就在冒险者公会的一角偷懒。</p><p>我使劲把介绍了这个家伙的柜台小姐拉到一旁去。</p><p>「不好意思，我觉得那个绝对不可能是。我们要找的人是年轻留有一头金发，帅气又有实力，还算小有名气又老实，更是诚恳又坚忍不拔，同时兼具绅士风范的长枪好手。那个根本只有发色是金发这一点符合吧。而且他的金发感觉还很暗沈。」</p><p>「如果有那么优秀的男人存在，我才希望你介绍给我认识呢……无论如何，已经没有其他符合你们提出的特征的冒险者了。基本上，这个城镇的金发冒险者，就只有拉拉蒂娜小姐和达斯特先生两位……原则上，他虽然一天到晚喝得醉醺醺的，不过实力出乎意料坚强，也还算出名……」</p><p>「出名归出名，但那是恶名昭彰吧！我可是曾经看你劝过一群菜鸟冒险者，叫他们不要接近那个喔！」</p><p>在这个之前的那些人是也都很不像话，但我现在有种在最后抽到下下签的感觉。</p><p>『别这样嘛——！我和悠悠又不是没交情，请我喝个酒又不会怎样——！』</p><p>『我和你不是朋友，纯粹只是点头之交！再这样下去旁人看待我的眼光又会变得比现在更差了，快住手！』</p><p>正当我忙着和柜台小姐对谈的时候，悠悠不知何时被小混混缠上了。</p><p>我对着还在听老爷爷的冒险故事的爱丽丝招了招手，示意要她过来。</p><p>「依丽丝，你听我说。这个城镇的金发男性冒险者，好像只有那个了。」</p><p>「我刚才听到长枪被一击熊折断之后，老爷爷赤手空拳搏斗的力量因而觉醒，下定决心正要凑过去的时候，故事正精彩的说……既然金发的先生只有那个人的话，总之先问他看看如何？」</p><p>回到我身边来的爱丽丝提议先试探看看。</p><p>「不，我可以断定，唯有那个人绝对不可能。那个是只要我们稍微一不注意就会立刻邀和真去做一些不好的消遣，换言之就是坏朋友。」</p><p>我看着依然在纠缠悠悠的小混混如此力劝。</p><p>应该说，没想到连乖巧的悠悠都会那么毫不矫饰地出言抱怨，她和那个小混混之间到底发生过什么事啊？</p><p>我经常听说悠悠最近都和一些奇怪的人混在一起，难不成和那个传言有关吗？</p><p>之前我一直没有空多理她，也许应该在她还没被奇怪的男人缠上的时候多关心她一下比较好。</p><p>「我想起来了！我也见过那位大哥哥。之前我来这个城镇的时候，他突然撞了正好路过的大姐姐，还说什么他的脚骨折了之类。我还记得，由于他威胁对方请他吃一顿饭当成慰问，我就派克莱儿去教训了他一顿……」</p><p>那个男人到底都在干些什么啊？</p><p>或许是终于连自尊心都舍弃了，达斯特因为想要酒钱而在我们眼前跪倒在悠悠脚边。</p><p>至于悠悠则是害羞到惊慌失措，连忙从钱包里拿出钱来。</p><p>我开始觉得在众目睽睽之下跪在地上求人请客，在某种意义上也是一种恐吓了。</p><p>为了向年纪比自己小的女生强取酒钱，在众目睽睽之下跪倒在地上的前龙骑士……</p><p>「……嗯，再怎么说都不可能吧。既然如此，那个人可能已经到别的城镇去了。基本上我们连名字都不知道，实在无从找起。我们还是就此放弃，今天在活动据点玩一玩之后就回家吧。」</p><p>「头目大人，我觉得这种时候应该要收集情报才像是盗贼会做的事情吧。我们这样真的可以自称是盗贼团吗……」</p><p>爱丽丝像这样踩了我的痛脚，不过现在也不是说这种话的时候……</p><p>……嗯？</p><p>「依丽丝，你刚才的发言非常正确！没错，我们是盗贼团。我们应该找的是优秀的盗贼！」</p><p>「事、事到如今才说这种话也有点怪就是了。真要说的话，在盗贼团的头目是身为魔法师的惠惠小姐的时候就已经……」</p><p>「少啰嗦，那种事情现在一点也不重要！我正好找到一个优秀的盗贼！快点，依丽丝，我们走！」</p><p>我拖着疑惑的爱丽丝，冲到很久没在公会现身的某个人身边。</p><h3 id="_4-2" tabindex="-1"><a class="header-anchor" href="#_4-2"><span>4</span></a></h3><p>「现在遇见你正好。克莉丝，好久不见了。虽然有点突然，不过我组成了一个盗贼团，请你加入吧。」</p><p>「噗哗！」</p><p>我随便寒暄了几句就开始挖角，结果克莉丝把嘴里的牛奶全都喷了出来。</p><p>「你在做什么啊，年轻女生怎么可以在众目睽睽之下喷牛奶呢？」</p><p>「咳喝、咳呼……！什么叫做我在做什么！还不是因为你突然说出那么夸张的事情！」</p><p>在艾莉丝女神感谢祭之后，我已经好一阵子没见到克莉丝的踪影了，她现在带着一脸工作告了一个段落的满足表情，一个人坐在这里休息。</p><p>而我就是看见这样的她才如此向她搭话……</p><p>「有什么好夸张的，克莉丝是盗贼耶，所以加入盗贼团也没有什么好奇怪的吧？」</p><p>「是是是、是这样说没错！应该说盗贼团是怎样！难不成，惠惠其实已经察觉到我的真实身分了吗？」</p><p>正当我因为克莉丝说出这种让我听不太懂的话心生疑惑时，爱丽丝已经跟了过来。</p><p>我简略地对爱丽丝说明了一下我跟克莉丝的关系。</p><p>然而，明明应该是和克莉丝第一次见面的爱丽丝不知为何歪着头说：</p><p>「不好意思，你是克莉丝小姐对吧？冒昧请教一下，我们是不是在哪里见过面啊？」</p><p>听爱丽丝突然这么说，克莉丝也同样歪了头……</p><p>「你叫依丽丝是吧？其实我也是从刚才就觉得好像有见过你……等等，啊啊啊啊！」</p><p>看她这个反应，大概是认得身为王族的爱丽丝的脸吧。</p><p>这也难怪，依丽丝这个化名那么微妙，她又几乎没有遮住自己的脸。</p><p>既然是王族，大头照之类的会在坊间流传也很正常。</p><p>「不愧是消息灵通的盗贼，看来你好像知道依丽丝的真实身分。不过，这是微服私访。要是你大肆声张的话会造成很多麻烦，所以……」</p><p>我原本以为克莉丝是因为发现对方是王族才会那么惊讶，但她的状况好像不太对劲。</p><p>「这、这样啊！谁教我是盗贼嘛！到了我克莉丝小姐这个程度，只要看一眼就可以马上知道对方是谁，还有是打哪来的了！既然是微服私访就没办法了，那、那么，我还有点杂事要办，先走一步……」</p><p>说了这种莫名其妙的话就想闪人的克莉丝被我一把抓住。</p><p>「你想上哪去啊？我有件事情想拜托消息灵通的克莉丝。」</p><p>「什、什么事情啊？我是清白正直没有做过任何亏心事的正义盗贼，不过应该没有什么可以帮得上你的忙的事情吧？」</p><p>手腕被我抓住的克莉丝不断偷瞄爱丽丝，举动看起来相当可疑。</p><p>「我们又不会把克莉丝怎样。我刚才也说过了，我试着组织了一个盗贼团，但是找不到优秀的人才。如果是骑士、大法师或祭司倒是有办法找到很多，但明明是盗贼团，最重要的盗贼却是一个也没有……」</p><p>「如果是骑士、大法师或祭司就找得到吗？呐，既然如此你还是别搞盗贼团了，乖乖弄个佣兵团应该还比较赚钱吧？应该说，那些才是应该比较难找的人吧……」</p><p>而爱丽丝看着露出心情复杂的面容的克莉丝，还是一脸狐疑。</p><p>「战力方面倒是无从挑剔。只是没有最关键的盗贼，所以我才想拜托克莉丝加入。还有，其实我们现在在找人，所以也想拜托你帮忙找那个人。」</p><p>「盗贼团啊……不，我自己也因为向往那种感觉，并尝试过很多事情，所以能够体会你的心情就是了。」</p><p>我对意外的反应还不错的克莉丝说：</p><p>「你很上道嘛。其实我们也是因为崇拜某个有名的盗贼团才组织了这样的团体……对了，你知不知道一群叫银发盗贼团的人啊？」</p><p>「嗯，我知道啊。而且大概比任何人都还要清楚。」</p><p>不愧是克莉丝，情报网果然是盗贼规格。</p><p>我弯下身子，压低声音说道：</p><p>「我接下来要告诉你的事情可别说出去喔。其实聚集在这里的都是崇拜那个银发盗贼团的人。我们受到那个银发盗贼团的义行所感化，打算瞒着他们暗中支持，偷偷略尽棉薄之力，说穿了就是从粉丝俱乐部再更进一步的团体吧。」</p><p>「这样啊——然后你把这些全都告诉我了是吧——呐……惠惠，我姑且问你一下，你这不是在调侃我对吧？」</p><p>我对不知为何一脸大澈大悟，目空一切的克莉丝说：</p><p>「你在说什么啊？我们可是再也认真不过了！啊啊，说要支持被悬赏的罪犯听起来很像在开玩笑是吧？你可别说出去喔，其实他们之所以被悬赏是有原因的。」</p><p>「啊啊……嗯，没关系，这个我也知道所以你不用说了。也就是说你们是为了支持银发盗贼团而擅自集结了一个下游组织的感觉吗？然后，你还希望我加入那个组织？」</p><p>「就是这么回事。拜托你，不然当作是试用性的暂时入团也可以。不过如果是这样的话，就要请你从基层人员开始当起了。」</p><p>听我这么说，克莉丝露出一脸夹杂着困惑与怀疑，相当有韵味的表情。</p><p>「基、基层人员……我是银发盗贼团的下游组织的基层人员啊……也罢，要我陪你们玩是没关系啦。应该说，惠惠，我再问你一次，你并不是把所有事情全都摸清楚了之后才这样调侃我的对吧？」</p><p>「……你从刚才开始就一直说这种话耶，为什么要那么疑神疑鬼的啊？」</p><p>「我只是觉得，艾莉丝女神感谢祭的时候，我不知道怎么搞的被迫去阿克西斯教团顾摊那次也好，这次也罢，我的运气明明应该很好才对啊，为什么却老是碰到这种很搞笑的状况呢……」</p><h3 id="_5-2" tabindex="-1"><a class="header-anchor" href="#_5-2"><span>5</span></a></h3><p>克莉丝几乎在任凭摆布的状况之下决定入团后，我对她说了有关那个龙骑士的事情。</p><p>「既然那个前龙骑士是金发的话，大概就是那个人了吧？」</p><p>克莉丝一边这么说一边指着的人，当然是达斯特。</p><p>我看向那边，达斯特似乎没有赚到一杯酒之后就放过悠悠的意思，开始对她讲述有关与人相处的课程。</p><p>我原本以为，凭那个男人也敢谈与人相处的道理，就算是悠悠也会揍他，没想到悠悠听得兴致勃勃还不住点头，甚至做起笔记。</p><p>「那个不是喔。原来消息那么灵通的克莉丝也有不知道的事情啊。」</p><p>「咦咦？可、可是，你们在找的人是金发对吧？说到这个城镇的金发冒险者，就只有他和达克妮丝了吧。」</p><p>这个疑问已经有很多人提过了。</p><p>「我们在找的人和那个小混混符合的特征就只有金发而已。真是的，克莉丝的眼睛未免也瞎得太严重了吧。」</p><p>「是、是这样吗！居然还说我眼睛瞎了，我觉得只有在这个状况下的惠惠没有资格说我耶！」</p><p>只有我没资格说她是什么意思啊？正当我想这么问的时候，忽然察觉到一件事情。</p><p>「……你从刚才开始就安静过头了吧，怎么了？」</p><p>「没有啦，只是我总觉得一定在哪里见过克莉丝小姐，但就是想不起来……」</p><p>「我觉得也没有必要想起来啦！再说了，我就不记得曾经见过依丽丝，所以我们肯定是第一次见面无误！」</p><p>克莉丝的声音从刚才开始就有点大得过头了。</p><p>「先别说这个了，你刚才说要找的那个人，以我的直觉判断，绝对是那个金发男没有错。虽然他腰间插着剑，但从他的步法和不经意保持的那个间距等等，都看得出是使用长枪的人的特征。而且在我看来是相当厉害的高手。」</p><p>克莉丝突然露出认真的表情，看向起身站到悠悠面前，开始做出奇妙举动的达斯特。</p><p>『你仔细看好，这样走路就不会被第一次见面的人给看扁。你这个人太想要朋友，所以会表现得比较自卑。冒险者要是被别人看扁了就完蛋了。猫啊狗啊之类的动物也是，在双方第一次见面的时候，就会定出哪一边的地位比较高！』</p><p>在我们的视线前方，达斯特用力耸起肩膀，摇晃着身子，拖着不稳的步伐走了起来，看起来就是个醉鬼。</p><p>而悠悠也被当成这样的达斯特的同类，在好奇的目光包围下羞赧地把自己缩得小小的。</p><p>「……原来如此，那就是长枪高手的步法啊。克莉丝观察人的眼光相当出色呢。」</p><p>「那个人为什么要在这种时候做那种奇怪的事情啊！」</p><p>——后来也不断做出奇怪举动，吸引了附近所有人目光的达斯特，习以为常地带着悠悠走出公会。</p><p>悠悠好几次用眼神示意要我们救她，但是既然克莉丝都说我们要找的人肯定是那个男人无误了，我们便顺水推舟地让悠悠继续陪达斯特玩下去，并且跟踪他们两个。</p><p>我打了暗号要悠悠就这样跟达斯特走之后，她便认命地跟着他。</p><p>「因为克莉丝都说到那个地步了，我才不惜像这样将那个孩子当成祭品，不过我还是觉得我们找错人了。」</p><p>「我的直觉告诉我，他的行动是伪装。他一定是因为有什么苦衷才装成那种笨蛋。」</p><p>我不懂克莉丝为什么那么想把那个塑造成非比寻常的高手，不过看来在她的心目中真的认为对方是相当厉害的角色。</p><p>我的直觉告诉我那不是在假装，纯粹只是真正的笨蛋就是了。</p><p>前一阵子也是，他来我们家找和真出去玩的时候，还跟在家里无所事事的阿库娅一起针对「艾莉丝教徒为什么多半胸部都不大」这种冒犯神明的话题，一脸认真地讨论得很热烈。</p><p>……这个时候。</p><p>「在我看来，也觉得他的走路方式看起来有点不太自然呢。感觉就像是舍弃了长年已经成为身体一部分的习惯动作，硬是改成新的走路方式……应该说，我隐隐约约可以从那位先生身上感觉到强者的气息。」</p><p>只有克莉丝就算了，现在就连在战斗方面的表现相当不错的爱丽丝都说出这种话来。</p><p>难不成真的是那个男人吗？</p><p>另一方面，在我们前方，悠悠对带着她不知道到底想走去哪里的达斯特开口说：</p><p>『达斯特先生，你今天走起路来好像不太自然耶？该说是很像企鹅走路吗，感觉好像脚受了伤一样……』</p><p>『喔，你看得出来啊？没有啦，只是有点刺痛而已，其实并没有受伤啦。我上次听一个名叫奇斯的好友说，就是……该怎么说呢，在过了成长期之后，还是有办法可以让那话儿变大，所以我就试了他教我的方法。那个方法呢，是用生姜和蒜头和芥末切碎了以后……喂，你的眼睛是怎样，我刚才说的并不是像平常一样在对你性骚扰，别咏唱魔法好吗！』</p><p>对年纪轻轻的小女生说出那种差劲到不行的话之后，达斯特的嘴巴还是没有停下来。</p><p>『女生为了让胸部变大也会喝牛奶、按摩之类的，尝试各种方法对吧？男生无论何时都梦想着要变得更雄伟。你不也有梦想吗？你的梦想是想要朋友，我的梦想是想要变成雄伟的男人。这两者不都是非常了不起的梦想吗？』</p><p>——长久以来一直殷殷切切地期盼着得到朋友的少女的梦想，和想要变得更雄伟的男人的梦想。</p><p>悠悠在呐喊着「不要玷污我从小到大的梦想！」的同时和达斯特扭打了起来，而我一边看顾着这样的她，一边说：</p><p>「你们两个的眼光都很独到呢。他之所以会走得那么不自然的理由似乎就像我们刚才听见的那样喔。」</p><p>听了我这番话，刚才充满自信地解说的两人以双手遮住泛红的脸颊。</p><h3 id="_6-2" tabindex="-1"><a class="header-anchor" href="#_6-2"><span>6</span></a></h3><p>「悠悠也气得跑掉了，我们再继续跟下去真的有意义吗？跟踪那个男人害我觉得自己变成了非常糟糕的人种。」</p><p>在悠悠因为自己从小到大的纯真梦想和最差劲的梦想被相提并论而哭着离开之后。</p><p>我们在开始有点赌气的克莉丝的带领之下，依然继续跟踪。</p><p>「我的直觉告诉我，那个人肯定有什么秘密。别看我这样，其实我很有看人的眼光。应该说是可以看穿那个人的本质吧……不过，我现在的身体不是真正……应该说状况不太好，所以无法斩钉截铁地断定就是了。」</p><p>状况不好是什么意思我搞不太清楚，不过克莉丝说自己很有看人的眼光，但身为虔诚的艾莉丝教徒，她在艾莉丝感谢祭的庆功宴上看见巴尼尔和维兹时好像也不太在意的样子啊。</p><p>「我有一件事想问克莉丝。你觉得不死者和恶魔怎么样？」</p><p>「觉得他们怎么不快点灭亡算了。」</p><p>她如此秒答。</p><p>「即使是有无论如何都想实现的愿望而迫于无奈变成不死者的人，或者是基本上非常喜欢逗弄人类，但是试着聊过之后会发现其实出乎意料的不是什么坏蛋的恶魔也……」</p><p>「毫无任何例外全都该快点灭亡算了。」</p><p>真是典型的艾莉丝教徒啊。</p><p>拒人于千里之外就是像这样吧。</p><p>她大概也只把巴尼尔当成有点奇怪的人，不过克莉丝的眼睛瞎到什么地步，这样就已经很显而易见了。</p><p>正当克莉丝因为我突然这么问而一脸不解的时候。</p><p>「啊，你们两位快看那个！」</p>`,220),e(m,{src:`/images/C1/27.avif`,alt:`插图`,width:`850`,height:`1257`}),l[19]||=s(`<p>听爱丽丝这么呼唤，我们看了过去，发现达斯特停在被乌鸦搞得一塌煳涂的垃圾场前面，确认附近有没有人。</p><p>「什么嘛，他果然是个很老实的人啊。你看你看，他为善不欲人知，都私下这么做呢。居然还特地先四处张望，确认没有任何人之后，才像那样开始打扫垃圾场，就算是一般人也很难办到那种事情呢。他符合的条件越来越多了吧！」</p><p>……不对。</p><p>「原来如此，那样是在将没有分类好的垃圾分门别类啊。我误会那位先生了！以前他纠缠路上的女人的时候，一定也是有什么缘由……！」</p><p>她们两个误会大了，那是在翻找垃圾，将卖得了钱和卖不了钱的东西分门别类。</p><p>看他找到卖得了钱的东西就乐得灿笑，就更能够证实我的想法。</p><p>「看吧惠惠，我看人的眼光还算了得吧？」</p><p>果然瞎到和阿库娅差不了多少。</p><p>「请看，那位先生不只做好垃圾分类，还将散乱的垃圾都收十得干干净净的。传闻中的那位前龙骑士的个性，听说也是老实诚恳又坚忍不拔……」</p><p>对于处理垃圾的状况不太熟悉的爱丽丝似乎也有了奇怪的误解，不过我想那只是因为任垃圾散乱一地的话，以后就没办法翻垃圾了。</p><p>捡到可以卖钱的东西，一脸幸福的达斯特将垃圾场打扫干净之后，立刻带着手上的东西到附近的五金行去。</p><p>「那是他刚才捡起来的东西对吧？虽然说是放在垃圾场的东西，不过捡到东西之后可以拿去换钱吧？」</p><p>克莉丝回答了爱丽丝的这个疑问。</p><p>「反、反正是已经被丢掉的东西嘛。与其丢在原地当成垃圾，不如像那样回收再利用，也算是对世间有所贡献吧……」</p><p>但是事情并不像她们两个说得这么好。</p><p>「大概是不满意收购价格吧，他跟老板吵起来了……啊，最后大概是被迫便宜卖了吧，他踢飞垃圾桶泄愤，弄得满地都是垃圾！」</p><p>「「…………」」</p><p>不久之前还一脸得意地称赞达斯特的两人再次遮住泛红的脸。</p><p>——后来我们还是不死心地继续跟踪。</p><p>「惠惠，你看那个，他在搭救被陌生冒险者缠上的女生！这次他真的做了善事……！」</p><p>「……然后换那个男人要人家跟他走当成是答谢他的搭救，纠缠起那个女生来了。」</p><p>在纠缠女生的时候被警察骂了就逃跑。</p><p>「……哎呀，达斯特的钱包掉了耶。」</p><p>「真的耶。现在不是跟踪那位先生的时候了，我们得快点去捡起来还给他才行……哎呀，走在后面的人捡起来交给他了呢，真是太好了！」</p><p>「等等，啊啊！他说『我的钱包里原本有更多钱的，是你抽走了对吧』什么的，开始找好心人的麻烦了！」</p><p>故意把钱包丢在地上然后找帮他捡起来的那位先生的麻烦，结果又被警察骂到逃跑。</p><p>「机会来了！有菜鸟冒险者在镇上的空地练习长枪！如果是长枪高手的话应该多少会有所反应才对……！」</p><p>「……他完全没有表示任何兴趣，一边挖着鼻子一边走过去了。」</p><p>「……不仅如此，他还去找刚才骂他的警察，说有冒险者在镇上乱挥武器你怎么不去骂他，找人家麻烦呢。」</p><p>就像这样，达斯特将他的下三漤本事发挥到淋漓尽致。</p><p>后来，他继续充分展现出不愧对于这个镇上最应该小心的人物之恶名的废物模样，最后来到的地方是——</p><p>「——于是，为了保护其他面临危险的冒险者而自愿当诱饵的我，勇敢地冲到多头水蛇前面被杀掉之后，就被送到了艾莉丝女神身边。我实际见到的艾莉丝女神，充满了神圣的光辉。」</p><p>「喔喔……！我也好想见艾莉丝女神一面啊，但是安享天年的话又无法实现这个心愿。话虽如此，不好好珍惜生命，故意前往危险的地方，应该也算是违反艾莉丝女神的旨意吧。啊啊，能够见到艾莉丝女神真是太令人羡慕了……！」</p><p>在镇上徘徊，到处给人添了一堆麻烦之后，达斯特再次回到冒险者公会，逮住一个看起来像是艾莉丝教徒的老祭司，说起这种可疑到不行的英勇故事。</p><p>我记得，如果是因为被怪物杀掉之类的不幸遭遇，在阳寿未尽的状况下死亡的人，灵魂会被送到艾莉丝女神跟前。</p><p>所以，曾经被名叫多头水蛇的怪物杀掉的达斯特，就算真的见过艾莉丝女神也不奇怪，但是……</p><p>「然后艾莉丝女神对我说：『你命不该绝。命运注定你终将协助勇者打倒魔王。好了，再次回到现世去，帮助即将拯救这个世界的勇者吧。愿你为这个世界带来光明……』祂是这么说的。」</p><p>「什么，艾莉丝女神说过那样的话吗！你身上背负着如此坎坷的命运啊！如果有什么我能够效劳的事情请你尽管说，任何事情都可以！」</p><p>艾莉丝女神是不是真的对他说过那些话十分令人怀疑，不过那位祭司不疑有他，相当感动。而一旁的克莉丝看见这一幕，不知为何浑身发抖。</p><p>克莉丝是虔诚的艾莉丝教徒，大概是因为那个男人见过艾莉丝女神所以也很羡慕他吧。</p><p>听祭司那么说，达斯特将怎么想都是用艾莉丝女神的故事换来的酒一饮而尽，对那个看起来人很好的祭司露出笑容之后……</p><p>「哦，这样啊？其实呢，我也很想为了拯救世界而和勇者一起并肩作战，无奈的是我没有钱……不知道有没有个愿意为了世界和平资助我的，虔诚的艾莉丝教徒呢……」</p><p>「你在说什么鬼话啊啊啊啊啊啊啊啊啊！」</p><p>克莉丝扑向达斯特。</p><h3 id="_7-2" tabindex="-1"><a class="header-anchor" href="#_7-2"><span>7</span></a></h3><p>「真是的，就差那么一点点了说，你要怎么赔我啊。你是那个人对吧？第一次见到和真就被他脱掉内裤然后哭着跑走的盗贼对吧？」</p><p>「我我、我才没有哭！而且那个算是意外！」</p><p>在冒险者公会的一角，我们正在请达斯特吃饭。</p><p>突然暴怒的克莉丝揪住达斯特，结果不知为何却是达斯特以妨碍他做生意为由反过来怒骂克莉丝，还要她请吃饭……</p><p>「头目大人，兄长大人脱了克莉丝小姐的内裤是真的吗？刚才头目大人还说和兄长大人一起泡过澡，兄长大人平常都在做什么啊？」</p><p>「对那个男人而言这样叫正常运转啦。不久之前，他还在豪宅的厕所里试图把达克妮丝的内裤拉下来呢。」</p><p>「到底是发生了什么事情才会弄出那种状况来啊！」</p><p>就在我将和真到目前为止所犯下的各种性骚扰灌输给爱丽丝知道的时候，因为是克莉丝请客就毫不客气地狂点的达斯特说：</p><p>「这么说来，你们今天好像一群人跟在我后面，是在干嘛啊？难不成是我的粉丝吗？」</p><p>「怎么可能会有你的粉丝这种奇特的人种存在啊……应该说，你察觉到我们的气息了吗？就算我没有使用潜伏技能好了，看来事情果然正如我所预料，你并不是普通人物。」</p><p>大概是还没有放弃达斯特原本是贵族又是菁英的想法，克莉丝以挑衅的口吻如此套话。</p><p>「不，你们什么都不做就已经够显眼了，还大声吵闹成那样，任谁都会发现吧。」</p><p>「这、这种事情不重要啦。更重要的是，就算见过艾莉丝女神你也不可以乱说话吧！要是遭天谴我可不管喔！」</p><p>克莉丝平常给人的印象那么温厚，没想到原来是这么虔诚的艾莉丝教徒啊。</p><p>达斯特明知道克莉丝在生气，还是不以为意地说：</p><p>「喂喂，你怎么可能知道我是不是在说谎啊，你应该没见过艾莉丝女神吧？一定没有对吧，没死过当然见不到。」</p><p>「这个嘛……因、因为，艾莉丝女神不可能说出那种带有预言意味的话……」</p><p>感觉到情势对自己不利的克莉丝尴尬地别开视线。</p><p>这时，爱丽丝似乎是克制不了自己的好奇心，兴致勃勃地倾身向前问：</p><p>「艾莉丝女神看起来怎么样？容貌和画像一样吗？」</p><p>「哦，你是怎样，我好像没看过你耶。艾莉丝女神就如同阿克西斯教团放出来的流言，果然有埝。那肯定是埝出来的……等等，啊啊啊啊啊啊啊！」</p><p>说出这种亵渎神明的话的达斯特看着爱丽丝的脸大叫。</p><p>「等一下，什么埝不埝的，不要再散布那个谣言了！」</p><p>「吵死了，现在哪管得了女神的胸埝那种问题了啊！喂，你是之前在我搭讪的时候派那个没耐性的金发护卫过来对付我的，和巴尼尔老大走在一起的小鬼对吧！那个凶巴巴的护卫今天不在吧？」</p><p>「呃——如果你是指克莱儿的话，她目前不在喔。」</p><p>这么说来，爱丽丝刚才好像有提过这件事。</p><p>「等一下，真的不要再提什么胸埝的了！更重要的是不可以捏造你和艾莉丝女神的对话，小心真的遭天谴喔！」</p><p>克莉丝用力拍桌，惹得达斯特兴致盎然地露出贼笑。</p><p>「所以说，你有办法证明我在说谎吗？我觉得虽然是第一次见面，不过艾莉丝女神肯定是煞到我了。瞧她看着我的那个眼神，肯定没错。」</p><p>「不对，因为你的死法太白痴了，她是用怜悯的眼神看着你！」</p><p>「说那种失礼的话还讲得好像是你亲眼看到似的，我可是勇敢的冲向多头水蛇耶，给我道歉！」</p><p>「你只是想独占功劳才被一口吞掉而已吧！」</p><p>两人争执不下，直到达斯特点的菜上桌了才暂时中断。</p><p>「……所以呢？言归正传，你们为什么跟踪我啊？」</p><p>「其实，我们基于某个目的而组织了盗贼团。然后，我们听说这个镇上有个武功高强的金发型男冒险者，所以想挖角那个人。我们问了柜台小姐有没有那样的人，结果她说金发的冒险者就只有你一个，于是我们就想评估一下你的实力……」</p><p>大口吃着料理的达斯特将嘴里的东西吞下去之后，很没规矩地拿叉子指着我说：</p><p>「武功高强的型男冒险者？真是的，你们这些家伙各个都还是只看长相嘛。晚一点我要去找和真告状，说你们想要反过来搭讪型男冒险者。」</p><p>「不、不是啦，我才不是要反过来搭讪人家呢！而且对我而言就算没有型男要素也无所谓，只是传言的内容是如此罢了！」</p><p>我不知为何连忙如此辩解，而达斯特一脸狐疑地看着我说：</p><p>「你们在找的家伙是个怎样的人啊？那个内裤被偷的盗贼看样子是找不到，不过也许你看不出来，我对这个镇上的冒险者也相当熟悉喔。发色这种东西想怎么染都可以。那个家伙的个性如何，你说说看吧。」</p><p>「据说他一头金发，是个型男又武功高强，个性老实诚恳又坚忍不拔。年轻女生们好像都很仰慕他呢。」</p><p>「…………这个世界上真的有那种人存在吗？」</p><p>眼神已经充满怀疑的达斯特表示：</p><p>「要说有哪个家伙比较接近这样的人的话，大概就只有那个叫御……什么的奇怪老兄了吧？不过那个家伙算是坚忍不拔吗？那个家伙没耐性到我不过是摸了一下他身边的小姐的屁股就乱发脾气耶。」</p><p>我真的问错人了。</p><p>这时，原本一直乖乖听他说话的爱丽丝说：</p><p>「不好意思，我有一件事情想问你，可以吗？」</p><p>「啊？怎么了小不点，原则上我是没有女朋友没错，不过我跟和真不一样，我一点萝莉控倾向都没有喔。」</p><p>「请不要说兄长大人是萝莉控！不，我要问的不是这个……请问，你会使用长枪吗？」</p><p>听见长枪这两个字，达斯特的眉毛动了一下，略显尴尬地抓了抓头之后……</p><p>「我……」</p><p>「依丽丝小姐————————————————！」</p><p>话才说到一半就被响彻公会内部的呐喊声打断了。</p><p>声音的主人不是别人，就是爱丽丝的护卫克莱儿。</p><p>「啊啊！你是那个之前突然就拿剑砍我的奇怪女人！」</p><p>「啊啊！是那个时候的那个不知分寸的搭讪男吗！混帐东西，什么人不挑，这次你偏偏挑上依丽丝小姐伸出魔爪……！」</p><p>「大骗子！喂，小不点，你刚才不是说那个女的不在吗！」</p><p>「这、这不能怪我啊……」</p><p>对克莱儿感到害怕的达斯特，一面如此抱怨爱丽丝，一面逃出公会。</p><p>——和克莉丝一起目送爱丽丝离开之后，时间也已经相当晚了，我们决定就此解散。</p><p>「到头来还是没找到传闻中的那个龙骑士呢。不过相对的，克莉丝决定加入我们倒是不错。」</p><p>「武功那么高强的冒险者也没有理由一直停留在新进冒险者的城镇嘛。不过，看来那个叫达斯特的人真的不是。我原本还觉得自己看人的眼光很准的说。」</p><p>待在这个镇上还没发现那么引人注目的巴尼尔和维兹的真实身分，我想就足以证明她的眼睛果然很瞎了。</p><p>「不过，为什么那位龙骑士为什么要掳走公主呢？如果事情就像依丽丝说的那样，或许是一段佳话没错，可是感觉好像还有什么内情呢。」</p><p>「这个嘛，任何人都会有一两个秘密嘛。像我也有一些部分是连和真也没看过的嘛。」</p><p>吾等红魔族每一个人在身体上的不同部位，都刻有与生俱来的编号和印记。</p><p>以我而言，是在一个不太方便给人家看的地方，所以……</p><p>「呐，惠惠，女生不可以随便说要给人家看喔！」</p><p>「我又不是在说那种引人遐想的事！先别说我了，克莉丝应该也有个什么秘密吧？」</p><p>听我这么说，克莉丝轻轻笑了一声。</p><p>「我的话嘛，大概有两个惠惠不知道的秘密吧……而且还是我跟和真之间的秘密喔。」</p><p>「哎呀，你这是在向我挑战吗？这是挑战对吧？很好，最近冒出太多勾引那个男人的家伙，我早就觉得碍眼了，尽管放马过来吧！」</p><p>「等等等、等一下，我可没有那个意思喔！」</p><h3 id="_8-1" tabindex="-1"><a class="header-anchor" href="#_8-1"><span>8</span></a></h3><p>回到活动据点看见赛西莉还在睡她的大头觉，所以我就告诉她今天要先回家了。</p><p>赛西莉好像完全爱上了那栋宅邸打算正式住进去，不过随时有人在里面总是比房子空荡荡还来的好。</p><p>今天有一位优秀的盗贼加入。</p><p>没错，终于有了期待已久的盗贼。</p><p>总觉得我们好像每天都在埋头乱闯，不过这下子总算可以开始做些比较像盗贼团的正式行动了。</p><p>该怎么说呢，团里的成员全都很有个性，想避免她们失控真的很累。</p><p>而面对这样的一群队友依然能够贯彻自己的意见，即使几经风波也能凝聚成一个团队的和真，或许真的很厉害。</p><p>——正当走在回豪宅的归途上，想着这些事情的时候，一个熟悉的男人的身影映入了我的眼中。</p><p>尽管天色已经越来越暗了，刚才在镇上的空地里练习长枪的菜鸟冒险者依然挥着长枪。</p><p>而达斯特站在有点距离的地方，盯着那个菜鸟冒险者看。</p><p>他大概是又想胡乱捉弄人家了吧。</p><p>正当我在找附近有没有警察的时候，只见达斯特走向菜鸟冒险者——</p><p>「……喂，长枪给我一下。我示范给你看。」</p><p>然后突然说出这种令人意外的话。</p><p>被达斯特这么搭话的冒险者似乎还不知道他的臭名，一面擦着斗大的汗珠，一面乖乖将手上的长枪交给他。</p><p>达斯特为了确认长枪的长度和状态，用力挥了好一阵子，然后示范了好几次刺击。</p><p>即使是像我这样的门外汉，也看得出他的刺击有多么俐落。</p><p>菜鸟冒险者擦汗的手也停了下来，看得目瞪口呆。从他这样的反应看来我的判断无误。</p><p>长枪划破空气的声音逐渐变得越来越锐利，最后菜鸟冒险者更是紧张到吞了一口口水。</p><p>就连附近的空气似乎也变得紧绷了起来，紧张的感觉越来越强烈。</p><p>平常那个废人不知道消失到哪去了，达斯特显得专注到令人害怕。不久之后，他举着长枪，摆出架势，马步蹲低之后——</p><p>「——我回来了～～」</p><p>「欢迎回来～～今天的晚餐是大家最喜欢的寿喜烧喔。阿库娅从刚才开始就在催我们快点开动吵得要命，所以你赶快去洗手吧。」</p><p>今天负责煮饭的好像是和真，他端着一个不断沸腾的锅子对我这么说。</p><p>阿库娅已经在餐桌旁边坐好了，想等到我回来再开动的达克妮丝则是一一在大家的杯子里斟了酒。</p><p>「和真，我有点事情想问你可以吗？」</p><p>「哦？怎么这么突然……啊～～你是想问我几点睡觉吗？」</p><p>或许是想到我们之前的约定吧，和真故意装傻这么说。</p><p>「不是啦，我不是要问这个。就是……和真有没有什么事情瞒着别人啊？比方说有什么秘密之类。」</p><p>「秘密？我的秘密可多着呢。应该说，不可能有人没有任何秘密吧？」</p><p>……这么说也对。</p><p>刚才的光景给我的冲击实在太大，所以我一不小心问出这种蠢问题来。</p><p>达斯特或许真的是那个人吧。</p><p>最后那招之精彩，让我不禁这么觉得。</p><p>如果之后他没有说「想要我教你刚才那招的话就拿一百万艾莉丝过来」的话，或许我也会不禁为之折服。</p><p>「你突然间是怎么了，惠惠？顺道一提我就没有秘密喔。因为我相信你们，所有的事情都会告诉你们。」</p><p>达克妮丝对烦恼的我露出柔和的笑容这么说。</p><p>「你还真敢说啊，加入我们队上的时候明明就没说自己是贵族千金，后来还想瞒着我们出嫁，引发了那么大的骚动不是吗。」</p><p>然后瞬间被和真驳倒，都快哭出来了。</p><p>这时，坐立难安地等着寿喜烧的肉片煮熟的阿库娅说：</p><p>「哎呀，我也有秘密喔。其实呢，我正在想说是时候向大家坦承了。」</p><p>「喂，反正你又要说自己是女神的那件事了对吧？她们两个也不会相信……」</p><p>「其实呢，已经差不多快要到我们组成小队一年的日子了，和真为了庆祝还买了很贵的酒，可是我忍不住先喝掉了！」</p><p>听阿库娅这么说，和真不禁整个人僵住。</p><p>「对不起啦～～！」</p><p>「什么叫『对不起啦～～！』，你瞧不起我啊！你这样不叫秘密，只是做错事情不敢说而已！……喂，你的眼神有点飘忽不定喔。你刚才只是先说了一件比较轻微的事情看我会不会生气，其实还隐瞒了更严重的事情对吧！给我从实招来！」</p><p>……也罢。</p><p>毕竟我组织了盗贼团这件事对和真而言也还是秘密。</p><p>没有理会像平常一样开始吵架的两人。</p><p>达克妮丝举起酒杯，心情愉悦地向我问道：</p><p>「对了，惠惠。你最近好像跟很多人一起活动对吧？你们今天做了些什么呢？」</p><p>今天发生了些什么事啊……</p><p>像是多了一个手下之类的，发生了很多事情，不过真要举出一件事情的话……</p><p>「我今天见识到很多人令人意外的一面。如果他们本人表示我可以说的话，改天我再告诉达克妮丝。我想你一定会大吃一惊。」</p><p>会这样想确实是跟爱丽丝还有悠悠有点像……不过他和邻国公主之间究竟发生过什么事情，下次我一定要问看看。</p>`,174),e(m,{src:`/images/C1/24.avif`,alt:`章节尾页`,collapsed:``,width:`338`,height:`1200`}),l[20]||=a(`h2`,{id:`第四话-袭击的盗贼团`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#第四话-袭击的盗贼团`},[a(`span`,null,`第四话 袭击的盗贼团`)])],-1),e(m,{src:`/images/C1/19.avif`,alt:`章节标题`,collapsed:``,width:`850`,height:`1257`}),l[21]||=s(`<h3 id="_1-3" tabindex="-1"><a class="header-anchor" href="#_1-3"><span>1</span></a></h3><p>在已经完全变成我们的聚会处的活动据点。</p><p>看过想加入吾等盗贼团的入团申请人名册之后，克莉丝说：</p><p>「我有点不太懂你在说什么。」</p><p>我对一脸茫然地看著名册，动也不动的克莉丝说：</p><p>「你怎么突然这么说啊，我才不懂你是什么意思。那是想加入盗贼团的人的名单啊。」</p><p>「我不懂人数为什么会这么多！而且拿阿克塞尔最豪华的宅邸当成活动据点也很莫名其妙，名册上面随处可以看到略有耳闻的高手的名字更是让我搞不懂！」</p><p>这个基层人员到底是怎么了啊？</p><p>「有什么好大惊小怪的啊？组织当然是越大越好啊。」</p><p>「话是这么说没错！不对，真的是这样吗？呐，和真知道这件事吗？」</p><p>我对带着混乱到不行的表情拼命表达意见的基层人员说：</p><p>「原则上像是有了同伴、有了活动据点等等诸如此类的事，我都有向和真报告喔。」</p><p>「这、这样啊。尽管如此他还是没有表示任何意见吗……咦咦？只有我觉得这件事已经搞到太大了吗？」</p><p>果然是基层人员的料，克莉丝好像很胆小的样子。</p><p>「规模大得吓到你了吗？只要我认真起来就是这样啦。」</p><p>「这样啊…………惠、惠惠很厉害嘛……」</p><p>听了我的发言，克莉丝以夹杂着惊讶和敬畏的眼神看着我。</p><p>就在这个时候。</p><p>「惠惠明明也因为规模变得大到超乎你的预期，而导致心里有点畏缩还敢讲……」</p><p>以俐落的手势在桌子上叠扑克牌金字塔的悠悠如此嘟哝。</p><p>「喂，不希望从一大早就搭建到现在的努力结晶遭到破坏的话你说话就小心一点。」</p><p>「我、我知道啦。我今天用了五叠扑克牌，正在更新最高纪录，所以拜托你别动手。」</p><p>悠悠不知不觉间已经将一个人玩游戏的技术磨练得越来越专精了，不过这孩子到底想往什么方向发展啊？</p><p>「对了……」</p><p>克莉丝显得有些尴尬。</p><p>「从刚才开始就看着我的那位是什么人啊？」</p><p>然后瞄了一下整个人躲在沙发后面，只探出头来的赛西莉，接着这么问我。</p><p>赛西莉明明就非常喜欢女生，偏偏今天却不知道怎么了，一直对克莉丝保持警戒。</p><p>「那位大姐姐是在这个家定居下来的祭司，名叫赛西莉……大姐姐，你怎么了？那种引人侧目的奇怪行动是和平常一样没错，但是你今天特别怪异耶。」</p><p>尽管我这么问赛西莉，她还是以狐疑的眼神凝视着克莉丝。</p><p>「大姐姐自己也不太清楚，不知道为什么，我的美少女感应器毫无反应。这种事情还是第一次发生，我也相当困惑……呐，你该不会是冒充美少女的男生吧？不过对我而言这样应该也还不坏才对，所以还是有什么事情不太对劲。」</p><p>「我穿短裤的时候偶尔是会被误认为男生没错，不过我确实是女生……」</p><p>大概是过因为短发和宽松的服装而有过被误认的经验吧，克莉丝显得有些消沈。</p><p>「啊，因为克莉丝是虔诚的艾莉丝教徒吧。一定是因为这样大姐姐才会对她没感觉。」</p><p>听见艾莉丝教徒这几个字，赛西莉从沙发后面站了起来。</p><p>「竟有此事！好不容易有这个美少女云集的圣域，我绝对不容许艾莉丝教徒来犯！……我知道了～～你是因为羡慕我只要每天在这里打混就可以得到美少女们宠幸的生活才跑过来的对吧？竟敢企图抢走这么好康的地位，想都别想你这只狐狸精！」</p><p>「狐狸精？等、等一下，你好像有什么奇怪的误会，我是在近乎半强迫的形式之下加入的耶……！」</p><p>正当赛西莉像是有艾莉丝教徒过敏症似的，和克莉丝争执不下的时候。</p><p>「这么说来，悠悠，依丽丝今天不在吗？」</p><p>「依丽丝啊，我去了我们平常碰面的地方，结果来的只有负责传话的女仆，说今天好像有什么典礼，她没办法来……等、等一下，不要这样啦，不要对扑克牌金字塔吹气。对了，惠惠，我实在很好奇那个孩子的真实身分，已经快要好奇到受不了了……」</p><p>原来如此，有王族的行程啊。</p><p>人数也差不多够了，我原本想说是时候该执行一次袭击，但这也是无可奈何的事情。</p><p>「如果是这样的话就没办法了。既然是典礼，如果硬是把她拖来肯定会出问题吧。」</p><p>「呐，惠惠，告诉我依丽丝的真实身分……你为什么要别开视线！为什么连克莉丝小姐都把头转过去了！等等，不要摇晃我，金字塔会倒掉！」</p><p>抓着悠悠的肩膀用力摇晃，逼她闭嘴之后——</p><p>「事情就是这样，毕竟也有正职盗贼加入了，我想差不多该来一次袭击了！执行日期就订在依丽丝能够参加的日子！在那之前我们要调查袭击目标，拟定作战计划……以上！」</p><p>「哇啊啊啊，我的金字塔！你给我等一下——————！」</p><p>我便用力拍桌，如此宣言——</p><p>——当天晚上。</p><p>回到豪宅，吃完晚餐的我，问了和真一个问题。</p><p>「顺利统整一群问题儿童的秘诀？你这又是问了个奇怪的问题啊。」</p><p>尽管说好要袭击了，但这个盗贼团募集到的成员完全只有奇人异士。</p><p>还是问问以擅长统整难搞的同伴而闻名的和真，请教一下其中的秘诀好了。</p><p>于是这样想的我便试着问了和真……</p><p>「先别说什么秘诀了，我自己不觉得是在统整你们啊。你想想那些训练怪物的训兽师，他们也没办法对自己饲养的怪物下达太精准的指令吧？我也是只给你们笼统的指示，然后若有似无的诱使你们做出正确的行动罢了。」</p><p>「笼统的指示……是吧。真亏你能够靠这招顺利带领我们呢。」</p><p>不过经和真这么一说，他确实不是每次都指示得非常详细。</p><p>「因为，就算我指示得非常详细，你们也不会听啊。像我这种程度的网游大大，状况判断这种事情只要临场靠当时的灵感就可以得心应手了。毕竟我还在自己的国家时，加入的那个公会里面，有很多比你们还夸张的问题儿童嘛。」</p><p>「你所谓的大大，意思是名列前茅的人对吧？和真以前也有战友吧，你说过你们会一起攻城、打王之类。」</p><p>这也是有关和真的众多谜团之一。</p><p>他说过自己和许多同伴并肩作战，每天熬夜狩猎怪物和打王，闯出了不小的名气。</p><p>「是啊，我在公会里面也算是干部之一呢。负责的工作是培育新人和编排打王的行程。我之所以能够处理像你们这样的人，我想也是因为有这样的经验吧。」</p><p>和真的话语当中充满了坚定的自信。</p><p>这件事无论他说了几次，听起来都不像是在说谎。</p><p>「不过，如果硬要说有什么秘诀的话，就是无论面对的是多么难搞的队友，都不可以有找个地方把对方丢掉的想法，要努力去理解人家。」</p><p>「和真，为什么你说这个的时候要看着我啊？」</p><p>原来如此，理解对方是吧。</p><p>「谢谢你。我明天会和大家聊聊看的。」</p><p>「无论是怎样的废物至少都会有一个优点。如果能够找到那种人的优点，会发现意外的能够派上用场。即使是那种让人想要在远征地城时顺便丢在里面不管的人，仔细观察一下或许还是能够找到意外的一面。」</p><p>「呐，所以说为什么说那种话的时候要看着我啊？」</p><p>意外的一面。</p><p>这么说来，我对她们的认识都还不够深入。</p><p>「再说，对于身为一流玩家的我而言，只要当成是限制玩法的一环，在生活条件已经相当宽裕的现在，就算你们再怎么扯我后腿我也不会生气了。」</p><p>听充满自信的和真这么说，一脸松懈地摸着缠着她的点仔的达克妮丝有了反应。</p><p>「喂，和真，在大家面前说出那种猥亵的字眼不太好吧。」</p><p>「我说的限制玩法不是你最喜欢的那种被绑起来自爽的游戏好吗。少侮辱一流玩家。」</p><p>不过，年纪轻轻的就能够当上公会的干部，这个男人或许不是普通人。</p><p>正当我再次对和真刮目相看的时候，坐在他身旁的阿库娅一面殷勤地喂着她大腿上的爵尔帝吃东西，一面这么说：</p><p>「你从刚才开始就说得好像我们是问题儿童似的，不过用不着确认也知道，其中并不包括我对吧？你指的是她们两个对吧？」</p><p>「……你这个天字第一号问题儿童在说什么啊？」</p><p>听和真这么说，因为指尖被点仔轻轻咬了一下而露出舒爽的表情的达克妮丝也说：</p><p>「呐，和真，我不是你口中的问题儿童吧？我很有自信，在这三个人当中我是最理智的一个吧……」</p><p>……喂，给我等一下。</p><p>「你那是从哪里冒出来的自信啊。战斗中的你们在我的眼中，顶多只是比较聪明一点的哥布林喔。」</p><p>「跟我到外面去，你居然敢把美丽又聪明的我当成是哥布林！」</p><p>「阿库娅说的对，这个男人最近太嚣张了。不过是顺利葬送了几个魔王军干部也没有资格把正值青春年华的少女说成哥布林，饶不了你。」</p><p>两人因为和真的发言而义愤填膺，简直和哥布林一样暴躁易怒。</p><p>「你们两个确实是问题儿童无误。这里面最理性、最冷静的是高智商的我。毕竟大法师最大的卖点是冷静沉着嘛……不过，这下伤脑筋了。我正在计划要带着一群很难搞的人去做某件事情，但她们实在都太有个性了，害我不觉得事情可以顺利进行。」</p><p>「你、你这个人明明就像是没有火种也会擅自爆炸的不良品烟火，还敢说自己冷静沉着是在开什么玩笑啊？」</p><p>「呐，惠惠，如果是在战斗中的话，我相信自己比惠惠还要冷静喔。」</p><p>「唯有我们当中最暴躁易怒的惠惠没资格说我吧！」</p><p>他们三个纷纷对我反驳，但是双手抱胸，陷入沉思的我完全听不到。</p><h3 id="_2-3" tabindex="-1"><a class="header-anchor" href="#_2-3"><span>2</span></a></h3><p>「大姐姐，我问你喔。你现在最想做的事情是什么？」</p><p>「和惠惠小姐结婚吧。」</p><p>隔天早上，一大早就在活动据点一个人跳起诡异舞蹈的赛西莉，毫不犹豫如此秒答。</p><p>「……不好意思，我是女生，所以没办法和大姐姐结婚……」</p><p>那种诡异的舞蹈似乎是献给阿库娅女神的祈祷，她轻声说着「阿库娅女神，请保佑我的今天也是美好的一天」之后表示：</p><p>「不同于食古不化的艾莉丝教，在我们阿克西斯教，只要对象不是恶魔女孩和不死怪物，无论是种族的隔阂还是性别的隔阂都是枝微末节，所以没有问题啦。」</p><p>问题可大了。</p><p>「这个嘛，大姐姐的心意我很高兴，不过可以的话我还是想当新娘出嫁，所以只能说对不起了。」</p><p>「真拿你没办法。那大姐姐努力当个好新郎就是了。」</p><p>「不是啦，我是想真正嫁给男生！别、别那么沮丧好吗，平常那么不正经的人在这种时候却这么失落根本是作弊！」</p><p>当我因为赛西莉带着被抛弃的小狗般的表情看着我而感到困惑时，她便笑盈盈地说：</p><p>「真是的，惠惠小姐真的很可爱耶！没办法了，这件事是我听来的，据说有一种传说级的神器，连改变性别都办得到。为了惠惠小姐，大姐姐无论如何都会取得那个东西。」</p><p>「就算大姐姐变成大哥哥我也不见得会嫁给你，请你别这样做！应该说，你就没有别的事情想做了吗？大姐姐平常心里充满了欲望，应该有一大堆事情想做才对吧？」</p><p>我好不容易把抱着我用脸颊磨蹭的赛西莉推开，试着这么问。</p><p>「惠惠小姐，你在说什么啊，我可是阿克西斯教徒耶？」</p><p>「……？我当然知道啊，那又怎样？」</p><p>她对歪头不解的我说：</p><p>「既然身为阿克西斯教徒，要是有什么事情想做的话，我当然会毫不犹豫立刻去做啊。为了不愧对阿库娅女神，我每天都活得像自己，想做什么就去做。就像这样。」</p><p>说着，赛西莉紧紧抱着我，轻轻微笑了一下。</p><p>「所作所为和说出来的话都很不像样，但我不禁觉得这样的生存之道有一点帅气。很有爱好自由的阿克西斯教徒的风范呢。」</p><p>「谢谢！我也觉得惠惠小姐那种像仙女棒一样的生存之道很帅气喔！」</p><p>可以不要把我说成仙女棒吗？</p><p>这时，赛西莉摸着我的头说：</p><p>「如果你有什么烦恼的话可以找大姐姐商量喔，毕竟大姐姐的职位是顾问嘛！」</p><p>她还是一样，展现了意外敏锐的一面。</p><p>没错，最近这一阵子一直令我烦恼的问题，那就是——</p><p>「上次问的时候不了了之，不过惠惠小姐有喜欢的人对吧？」</p><p>到底该怎么做，才可以靠这支奇葩到不行的队伍发动一次成功的袭击呢？</p><p>「不不、不对啦，你在说什么啊！我在烦恼的是该怎么样才能以现在的成员成功袭击，才不是在烦恼那种事情！」</p><p>真的在不必要的方面特别敏锐的赛西莉这么说，害我的耳朵都变红了。</p><p>看着这样的我面露温柔微笑的赛西莉，总觉得看起来就像个称职的神职人员。</p><p>这个人偶尔会表现出像这样令人意外的一面，真是太奸诈了。</p><p>「要是再继续调侃你的话大姐姐会被讨厌，所以就当成是这么回事好了！这个嘛，首先得决定我们要袭击的贵族是谁。接着，要决定如何袭击那个贵族。最后，要确认那个贵族是不是真的在做坏事，才知道我们这样乱来会不会出问题。也就是说，我们应该锁定的目标是并非默默无名，又有钱，感觉背地里还有在做坏事的贵族家。」</p><p>原来如此，那样调侃我是让我不太高兴，不过她难得说出实用的意见呢。</p><p>「说是这么说，但其实我在听了惠惠小姐的计划之后，就已经看中一个目标了。」</p><p>「大姐姐这是怎么了，今天未免也太可靠了吧。」</p><p>说真的，这个人到底是怎么了啊？</p><p>那个名叫杰斯塔的货真价实的变态也好，大姐姐也罢，阿克西斯教徒偶尔会发挥惊人的实力呢。</p><p>眼神当中充满期待的我，等着要听大姐姐看中的贵族家时……</p><p>「你知道有名的达斯堤尼斯家的宅邸就在这个城镇吗？」</p><p>「…………」</p><p>我不禁哑口无言，赛西莉不知为何却越说越起劲。</p><p>「目标当然是越大越好。从这点来说，达斯堤尼斯家自然是十二分的符合。接下来的条件是有没有钱，他们家可是这个国家数一数二的大贵族，当然没有贫困的道理吧。」</p><p>他们家虽然不到贫困，但以贵族来说并不算太有钱就是了。</p><p>「而且最重要的是，听说他们整个家族都是虔诚的艾莉丝教徒！既然是完全受到邪恶的艾莉丝教徒污染的家系，他们背地里肯定有在做坏事！」</p><p>「不好意思，唯有他们家绝对不能下手。应该说拜托你放过他们吧。」</p><p>认真听这个人说话的我真是太丢脸了。</p><p>「既然惠惠小姐这么说的话，那就没办法了……不然，我还想到另一个贵族家，当成第二顺位的选项。我们先去调查那一家如何？」</p><h3 id="_3-3" tabindex="-1"><a class="header-anchor" href="#_3-3"><span>3</span></a></h3><p>「——贝尔海姆家？嗯……那里对新手而言难度应该有点高吧。目前我也没听过他们家有什么不好的传闻，而且警备又很森严，我不太推荐。」</p><p>过了中午之后来到公会的我，逮住在里面看起来好像很闲的克莉丝，向她打听大姐姐告诉我的贵族家的情报。</p><p>「说什么不推荐给新手，讲得好像你很习惯入侵贵族家似的。」</p><p>「噗哈！咳咳……！你也知道，我的职业是盗贼嘛，就算没有要实际进去偷东西，还是会盘算一下嘛！」</p><p>将含在嘴里的深红啤酒大口喷出的克莉丝连忙对我这么说。</p><p>原来如此，大概就和爆裂魔法师寻求又硬又大，值得破坏的东西的习性很类似吧。</p><p>克莉丝拿手帕擦了擦嘴角之后说：</p><p>「我姑且还是会帮你详细调查一下贝尔海姆家，不过一开始还是挑更有小咖气息的贵族宅邸比较好吧？如果是不法情事一曝光就会立刻被抄家的程度的小咖，就算被偷了多半也不会把事情公开。」</p><p>「我姑且问你一下，你只是在心里盘算而已对吧？至于实际熘进去偷东西的经验……」</p><p>「没没没没有喔！讨厌啦惠惠，我怎么可能做出那种以身犯险的事情嘛！」</p><p>克莉丝嘴上这么说，但她好像不太擅长说谎，眼睛不断乱飘。</p><p>还把手帕放在桌子上折起来又摊开，摊开又折起来，完全静不下来，举止相当可疑。</p><p>「……克莉丝是艾莉丝教徒对吧？你敢对艾莉丝女神发誓，说你没有做过只身入侵贵族宅邸那种危险的事情吗？」</p><p>「要发誓喔……没、没有啦，我当然敢毫无保留地发誓。我敢发誓是没错啦……只是，这种不知道该做何反应才好的感觉是什么啊……」</p><p>尽管对如此干脆地发誓的克莉丝感到意外，我依然松了口气。</p><p>克莉丝好像是虔诚的艾莉丝教徒，这应该不是在虚应故事才对。</p><p>我原本还在担心她有没有乱来，看来是杞人忧天了。</p><p>「对了，我有个问题想问克莉丝。你现在最想做的事情，最希望实现的心愿是什么？」</p><p>「我吗！问我最希望实现的心愿喔……呐，惠惠，你真的不知道我的底细对吧？真要说的话，我不是希望人家帮我实现愿望的那一边，而是帮人家实现愿望的那一边才对耶……」</p><p>克莉丝又说出这种奇怪的话来了。</p><p>我还以为这孩子是吾等盗贼团当中最正常的一个人，但意外的好像不是这么回事。</p><p>「其实是和真告诉我，如果想顺利统整团队的话就要确实理解对方。说穿了，就是我想多认识你一点。」</p><p>听我这么说，克莉丝一脸不可思议地凝视着我。</p><p>「是喔，和真也会说这么正经的话啊。不过……希望实现的心愿、想做的事情是吧。嗯～～我已经随心所欲在做想做的事情了，目前大概没有吧。」</p><p>「随心所欲在做想做的事情是吧。赛西莉也说了同样的话呢。阿克西斯教徒和艾莉丝教徒其实在根本的部分是一样的嘛。」</p><p>「等一下，再给我一次机会！我会仔细思考过之后再回答你！」</p><p>或许是不喜欢被当成和阿克西斯教徒是同类，克莉丝眉头深锁，开始低吟。</p><p>烦恼了一阵子之后，克莉丝害羞地带着腼腆的笑……</p><p>「我想做的事情…………比方说和女生朋友一起去逛街、买一大堆衣服，或是去时下流行的店里吃好吃的圣代之类的……我想做的大概都是这种很世俗的事情吧。」</p><p>说出这种和活泼的外表正好相反，很有少女情怀的事情。</p><p>「你应该办得到吧。你又不是悠悠那种边缘人，也不像爱丽丝有身分地位要顾。在当冒险者，消息又很灵通的女盗贼，给我的印象就只有经验丰富又很敢玩而已耶。」</p><p>「太、太过分了！我连约会的经验都还没有耶！」</p><p>第一次遇见克莉丝的时候她突然就找和真打赌，我原本还以为她是个嗨咖盗贼，没想到或许意外的有纯情的一面。</p><p>原来如此，真的跟和真说的一样。</p><p>无论是赛西莉还是克莉丝，都展现出我所不知道的一面。</p><p>话说回来，约会是吧。</p><p>我好像也还没有一对一正式约会过的经验。</p><p>…………</p><p>「我忽然想到还有一个问题想问你。」</p><p>「什么问题？我和达克妮丝的交情已经很久了，和阿库娅小姐也算是有一段过去。和真和我也已经是共享秘密的关系了，你们的小队里就只有惠惠和我没什么交集。没关系，你想问什么都可以。」</p><p>克莉丝晃了晃啤酒杯开心地这么说，于是我问了她：</p><p>「你和我们家和真是什么关系？」</p><p>「……算是朋友吧。」</p><p>我把脸凑到别开视线的克莉丝面前。</p><p>「以朋友而言，你最近这阵子和那个男人的感情好像也太好了一点。再说，克莉丝刚才说和我没什么交集，可是我觉得和真跟克莉丝应该也没什么交集才对吧。」</p><p>「这、这个嘛，你也知道的啊，我教过他盗贼技能，诸如此类的啦！不过我们真的只是普通朋友喔！我对他并没有特别的感觉！」</p><p>看她这样拼命解释反而更令人怀疑，「共享秘密的关系」的部分更是让我非常在意。</p><p>「以前和真认识的女人顶多就只有我们，可是他最近莫名开始有女人缘，让我非常介意。如果是长期以来都在一起的人也就算了，要是被哪个突然冒出来的来路不明的女生抢走了，我可受不了。」</p><p>原本一直认真听我说话的克莉丝的脸颊微微泛红，像是反击我刚才的发言似的，以调侃的视线看着我说：</p><p>「这样啊～～这么说来，我听说惠惠最近好像跟和真走得很近是吧。呐，你喜欢他吗？你对他到底有多认真啊，告诉大姐姐嘛。」</p><p>「我喜欢和真啊。你要问我有多认真的话，我只能说认真到不行。」</p><p>听我这么说，克莉丝楞了一下，脸变得更红了。</p><p>「一开始我只觉得他是个经常做出怪异举动的怪人，后来变成了很会照顾人的人，然后又变成了待在一起可以很放心的人。这大概就是等到自己发现的时候已经喜欢上对方的那种状况吧。现在我每天想到和真的频率已经跟爆裂魔法差不多了。」</p><p>「是是是、是喔！惠惠在奇怪的时候很有男子气概呢。我原本还以为你会更困惑，或是更不好意思一点，没想到你会这么直接回应我，反而是我不知道该做何反应才好了……」</p><p>我觉得克莉丝看着我的眼神当中不知为何多了几分尊敬。</p><p>「事情就是这样，所以我想趁现在消灭任何有可能变成情敌的人。和真跟你真的只是普通朋友吗？」</p><p>「真的只是普通朋友！所以你的眼睛不需要变得那么红！那个，不然我去调查一下贝尔海姆家好了！」</p><p>说着，克莉丝像是在害怕什么似的，匆匆忙忙地冲出公会。</p><p>我也决定离开冒险者公会，前往下一个目的地。</p><p>也差不多该是悠悠带那个孩子过来的时候了。</p><h3 id="_4-3" tabindex="-1"><a class="header-anchor" href="#_4-3"><span>4</span></a></h3><p>「这、这个很可爱吧！你看，那个也是！」</p><p>「是啊，我不曾走进这样的商店，所以非常有兴趣……话说回来，悠悠小姐，我们不用去活动据点吗？」</p><p>这间面向主要乾道，非常受到女生喜爱的小物商店。</p><p>我很熟悉的两个人正在这间店里面闲晃。</p><p>「没关系啦。现在这个时候大家大概正在无所事事地吃着点心，然后惠惠因为被赛西莉小姐性骚扰而发脾气，克莉丝小姐一边说真拿你们没办法，一边苦笑…………这样想一想，那边好像也很好玩的样子……」</p><p>「那么，我们也差不多该过去了吧？逛街是很开心没错，不过要是被头目大人发现了应该会挨骂吧。」</p><p>听爱丽丝这么说，悠悠「呜」了一声，显得有点畏缩。</p><p>「是、是啊。我一点也不怕惠惠，不过一直到处闲晃让大家等也不太好。那么……」</p><p>「喂，你这个家伙带着比你小的女生到处乱跑，趁机实现藏在自己心里的愿望，居然还敢说那种话啊。」</p><p>听见我从背后这么说，悠悠抖了一下。</p><p>悠悠战战兢兢地转过头来——</p><p>「——真是的。就算再怎么没朋友也不应该硬拖着懵懂无知的依丽丝陪你吧，你到底在想什么啊？我是为了保留我的爆裂魔法才指定会合时间叫你去接她的，结果你第一天就搞出这种事情来！」</p><p>「……对不起。」</p><p>走在前往活动据点的路上。</p><p>脸已经红到耳根子去的悠悠双手掩面，跟在我后面。</p><p>「你八成是向往和年纪相近的朋友一起逛街吧，你这样我都不知道是为什么叫你去接依丽丝了。如果你那么想去逛那种店下次我陪你去就是了，请不要动不动就做出这种傻事。」</p><p>听我这么说，悠悠带着参杂了惊讶和期待的表情说：</p><p>「真、真的吗？惠惠真的愿意陪我去逛街吗？我一直在收集哪天交到朋友之后想要一起去的店家清单，已经快要累积到三本笔记本的分量了……」</p><p>「太多了啦，至少锁定个几间好吗！先别说这个了，我有个问题想问你们两个。」</p><p>说着，我对她们两个提出和刚才一样的问题。</p><p>「我想做的事情？呃，你怎么突然问这个啊，惠惠？要我回答也可以啦，但可能光是要列出我想做的事情，就算花上一整天也列不完吧……」</p><p>「就跟你说太多了啦！总有一件真正想做的事情，最想实现的愿望吧！」</p><p>听我这么说，悠悠不知为何不断瞄着我看。</p><p>「如果是这样的话，我差不多想跟惠惠真正一决高下了。」</p><p>然后怯生生地轻声这么说。</p><p>「我们不是早就分出高下了吗？无论是等级、名声，还是身为女性都是。」</p><p>「你给我等一下，等级和打倒几个魔王军干部也就算了，你要提到身为女性的话我可无法接受！」</p><p>悠悠眼中闪现红光，双手交叠，像是在对我炫耀似的挺起胸膛。</p><p>……这个家伙。</p><p>「我又不是在说身体的发育状况。你空有那个年纪轻轻却莫名情色的身体却钓不到男人，居然还想跟我对抗，未免太没有自知之明了。」</p><p>「你不过是跟和真先生走得比较近一点而已，不要以为这样就算赢过我了！只要我有心……！有、有心的话……」</p><p>面对声音越来越小的悠悠，我也得意洋洋地挺起胸膛。</p><p>「瞧，你连一个男生朋友都没有对吧？啊啊，前几天的那个金发小混混好像是你的朋友是吧。那个男人应该跟你很配喔，祝你们幸福！」</p><p>「就算是开玩笑我也不会原谅你这番话，唯有那个人绝对不可能！很好，我要让你知道什么叫有些话可以说，有些话不该说！我们现在就在这里一分高下吧！」</p><p>眼睛发出红光的悠悠从腰间抽出魔杖。</p><p>「你、你是怎样，想打架吗？很好，放马过来吧！你之前曾经对和真发动攻势说要跟他生小孩，其实让我心里非常不是滋味！我现在就在这里好好把事情弄清楚，让你再也不敢勾引别人的男人！」</p><p>「别、别提了！那是我的一时偏执和误会造成的意外，所以你可以忘记了！」</p><p>见悠悠放下魔杖害羞地如此呐喊，我在心中记下今天的胜利。</p><p>「到底有多少人在追求兄长大人啊！他在大庭广众之下脱过克莉丝小姐的内裤，还听说他也对拉拉蒂娜做过见不得人的事情。现在连悠悠小姐都要和他……生、生小孩……！」</p><p>「别提了——！真的不是，我对和真先生没有那种感觉！更更、更重要的是，我想听听依丽丝想要实现的愿望是什么！惠惠，你也这么想对吧！」</p><p>悠悠拼命想要转移话题，爱丽丝则是红着脸颊说：</p><p>「我、我啊，就是……」</p><p>……怎么每个家伙都这样。</p><p>「我想和……兄、兄长大人……！」</p><p>「你可别想继续说下去了！你们这些人是怎样，各个满脑子都在想谈情说爱！这个年纪的女生这样才叫正常吗！」</p><h3 id="_5-3" tabindex="-1"><a class="header-anchor" href="#_5-3"><span>5</span></a></h3><p>我带着被爱情冲昏头的两人回到活动据点时，里面呈现出奇怪的光景。</p><p>「以艾莉丝教徒而言，你的眼光还不错嘛。没错，阿库娅女神就是那么尊贵，而且非常惹人怜爱。」</p><p>「嗯，我知道，我是觉得她不是个坏人啦。嗯。」</p><p>赛西莉似乎正在对抱着膝盖坐在地毯上的克莉丝传教。</p><p>看来她好像是在解说阿库娅女神的优点。</p><p>「你回来啦，惠惠小姐。现在，我正好在劝克莉丝小姐改信阿克西斯教呢。」</p><p>「咦咦！等一下，再怎么样我也不会改变宗教信仰喔！」</p><p>克莉丝虽然乖乖听着赛西莉传教，但似乎没想到她会这么说，结果大吃一惊。</p><p>「你在说什么啊？不然我问你，你觉得恶魔和不死者怎么样？」</p><p>「当然是觉得他们怎么不快点灭亡算了。」</p><p>见克莉丝毫不犹豫地如此秒答，赛西莉笑容满面地对她说：</p><p>「太棒了，克莉丝小姐，你果然拥有阿克西斯教徒的资质！没错，阿库娅女神说过。恶魔必杀，魔王必灭，不死者必须回归尘土！好了，你也加入阿克西斯教吧……！」</p><p>「原则上艾莉丝教的教诲也是说恶魔和不死者是应该憎恨的存在喔！应该说我完全没想过会有人想拉我进阿克西斯教。为什么我最近这么常陷入这种搞笑的状况啊！」</p><p>她们两个分别是阿克西斯教徒和艾莉丝教徒，我本来还以为会吵起架来的，没想到相处得挺融洽，真是太好了。</p><p>我把争论不休的两人叫了过来，然后将预定计划告诉大家。</p><p>站到桌子前面的我将双手放在上面，挺身向前——</p><p>「那么，各位，感谢你们今天聚集到这里来。吾等盗贼团已经获得活动据点、得到后盾，更有了定期的收入来源。人员方面也有大量的入团申请者涌现。这应该算是非常值得高兴的状况吧。」</p><p>「是啊。人数和聚集的频率都增加了，事情大部分都已经上了轨道了呢。」</p><p>听我那么说，悠悠也点头如此表示。</p><p>「没错，目前发展得相当顺利。既然吾等盗贼团都已经差不多具体成形，我想也是可以开始正式活动的时候了。」</p><p>听我这么说，爱丽丝微微歪着头说：</p><p>「活动？今天到底要做什么呢？上次是去山上采山菜，再上一次是去河边钓鱼。可是我今天没有请家里的人做便当耶，要去的话不如明天再去吧？」</p><p>「谁跟你说我们要去玩了！不，最近的确是有种开始搞不懂这是什么团体的感觉没错，但是请你们不要忘记原本的目的。回想一下，吾等一开始是为了什么而聚集在一起的。」</p><p>听我这么说，她们一个一个依序开口：</p><p>「我想是为了交朋友吧……」</p><p>「我以为是要去冒险……」</p><p>「大姐姐是想被可爱的美少女包围，受到大家爱戴，才被吸引过来的喔。」</p><p>「奇怪！这跟我听说的好像不一样！」</p><p>见大家都忘记了原本的目的，我在大家面前用力拍了拍桌子。</p><p>「不对吧！我自己也不时会有点脱轨没错，但我们原本的目的是认同银发盗贼团的义行，所以要帮忙他们吧！是袭击！我们要袭击黑心贵族，打响我们的名号！事情就是这样，克莉丝，请你告诉大家调查的结果！」</p><p>「调查的结果没有问题。他们家好像没有在做什么坏事，我想还是不要选这里当成目标比较好。应该说，你为什么会想要选这里啊？」</p><p>听了克莉丝的报告，赛西莉一脸无趣地说：</p><p>「我之前去他们家要求捐款给阿克西斯教团，得到的回答却是他们对宗教那类的事没兴趣。还说无论是艾莉丝教还是阿克西斯教，他们对那种可疑的东西一向都是拒绝往来……」</p><p>听赛西莉这么说，克莉丝突然激动了起来。</p><p>「就决定去那里了！敢说宗教可疑的人都是神敌，应该遭受天谴！」</p><p>「就这么决定，就这么决定了！你很懂嘛，克莉丝小姐，你果然比较适合阿克西斯教！惠惠小姐，就这么决定可以吧？」</p><p>我对亢奋不已的两人说：</p><p>「完全不可以。既然没有做坏事我们就不可以袭击那里，选别家吧。阿库娅女神和艾莉丝女神都不会允许我们那么做的。」</p><p>「会啦，艾莉丝女神完全允许！」</p><p>「阿库娅女神一定也会允许我们的！不如说我好像都听到阿库娅女神叫我们放手去做的神谕了！」</p><p>我该怎么处理这两个人呢？</p><p>应该说，我原本以为最正常的克莉丝原来思想意外的这么激进，让我大吃一惊。</p><p>我深深体会到和真说的没错，理解同伴确实是非常重要的一件事情。</p><p>「原来如此，状况我都了解了。也就是说我们终于要去当正义使者了对吧！那么不如这么办吧，其实王家有列入观察的贵族名单。我们就依照上头记载的名字，总之先去袭击贵族宅邸再说，要是什么都没找到的话再请父亲大人出面赔罪……」</p><p>「你还是乖乖听话就好了！不可以搬出你的父亲大人！」</p><p>正当我如此吐嘈做出更加激进发言的爱丽丝时，悠悠用力拉了拉我的披风。</p><p>「算了啦，这个团体还是维持现状，大家每天开开心心玩在一起不就好了？你看，这是依丽丝的女仆为我们作的点心喔。很好吃，惠惠也吃吃看……等一下啊啊啊啊啊啊——！」</p><p>我把悠悠递给我的点心全都倒进嘴里，接着用力嚼了嚼，吞下去之后。</p><p>「没办法了，就算要袭击也得有对象才能够行动。还是暂时观察一下状况吧。」</p><p>毕竟，这次不同以往，我不是要一个人去引发骚动。</p><p>这次我有头目的责任要顾。</p><p>「谁教你连我的份都吃掉了啊啊啊啊啊！」</p><p>一边被悠悠用力摇晃，我一边烦恼不已。</p><h3 id="_6-3" tabindex="-1"><a class="header-anchor" href="#_6-3"><span>6</span></a></h3><p>「——我回来了～～」</p><p>「欢迎回来～～你怎么一脸很累的样子啊？」</p><p>后来，我们完全讨论不出半点共识，只有时间不断流逝。</p><p>不知为何，克莉丝说她有办法找到适合熘进去偷东西，难度不高的贵族家，所以今天就先解散了，只是……</p><p>「没有啦，我只是觉得理解大家、统整大家实在是很辛苦的事情。有个大姐姐一直调戏我，原本以为最正常的人意外的非常激进，自称竞争对手又爱跟我吵架，还再次认知到那个小女孩仍然在虎视眈眈地伺机而动，害我觉得好累。」</p><p>因为我平常都是随心所欲地大闹特闹的那一边，没想到变成阻止别人的立场会这么累。</p><p>「虽然听不太懂，不过好像真的很辛苦呢。你就趁这机会好好体会一下我的辛劳吧。」</p><p>我往闲适地坐在沙发上的和真身旁一屁股坐下，然后抬头盯着他的脸看。</p><p>「喔，怎么了？干嘛盯着最近广受公会内女冒险者好评的我看？你也和那家伙一样，到了现在终于发现我的魅力了吗？」</p><p>虽然我好像也没资格说这种话，不过爱丽丝为什么会看上这个男人啊？</p><p>本人似乎觉得自己摆了一个很帅的表情吧，他皱起眉头，歪着身子，鼓着鼻孔这么说。</p><p>「你最近确实广受公会里的女生们的好评呢。大家都叫你稍微捧一下就会随便请人家吃吃喝喝的好骗真先生。」</p><p>「那些家伙给我记住，下次被我碰到就等着接下『Steal』吧。」</p><p>尽管我就在他身旁，这个男人还是一边咬牙切齿，一边毫不在乎地做出对其他女性的性骚扰发言。</p><p>我为什么会看上这个家伙呢？</p><p>我回想起白天和大家的对话。</p><p>我说爱丽丝和悠悠满脑子只想着谈情说爱，但是自己在面对这个处处留情的男人的时候，说来说去还是会原谅他，大概是因为我也被爱情冲昏头了吧。</p><p>基本上是懒惰虫一只，明明很弱嘴巴却很坏，还会在冒险者公会吹嘘自己的功绩，一点也不谦虚。</p><p>外表很普通，个性既不是了不起的好人，也不到算是坏人的地步，是个胆小鬼。</p><p>「……呐，你到底是怎么了？这样一直盯着我的脸看，再怎么样我也会有点害羞耶。怎么？你是喜欢我吗？」</p><p>然后明明本性就是个色狼，但是像这样稍微被看一下就会为之动摇。</p><p>而且只要我稍微对他表示一下好感……</p>`,325),e(m,{src:`/images/C1/08.avif`,alt:`插图`,width:`850`,height:`1257`}),l[22]||=s(`<p>「我喜欢你啊。我也不知道为什么会这么喜欢你，所以才会像这样认真考察起来。」</p><p>「呼啊！」</p><p>没错，他就会变成这样。</p><p>「你、你这个家伙，我从很久以前就告诉过你多少次了，不要突然就随便说出那种话来好吗，我也是需要心理准备的。今后你要说这种事情的时候，必须事先确实透过写信之类的方式，预先告知要在几月几号的几点说。」</p><p>「那是什么毫无气氛可言的告白方式啊？我只是依照自己的心意，总是把想说的事说出来罢了。昨天和真不是也告诉过我，要尝试理解对方吗？所以我现在想要试着理解和真。」</p><p>我目不转睛地凝视着和真这么说，他便惊慌失措，举止可疑了起来。</p><p>看着这样的他，我不禁轻声一笑。</p><p>「和真相当了解我，所以才能够顺利下达指示对吧？你知道我现在在想什么吗？在我们两个独处的现在，你知道我想和你做什么吗？」</p><p>「……做……」</p><p>喂。</p><p>「不对，等一下。刚才那个不对啦，不算！」</p><p>「在这种气氛之下你原本打算对少女说什么，我洗耳恭听！」</p><p>和真看见我的眼睛的颜色之后就把话吞了回去，手足无措了起来。而我看见这样的他，忽然开始觉得认真思考的自己很可笑。</p><p>没错，像这样准备周全、拟定计划再去袭击，完全不是我的行事风格。</p><p>什么统整大家、阻止大家。</p><p>什么思考后果之类的，这样一点也不像我。</p><p>无论何时我都是全力以赴。</p><p>我到底在烦恼什么啊？</p><p>「不是啦，惠惠。我觉得是你那种问法太狡猾了。这样好了，三选一的话我一定猜得到。再给我一次机会吧。」</p><p>如果演变成我自己无法处理的状况，虽然一直依赖他让我很过意不去，不过到时候再拜托这个人就是了。</p><p>我对着还在说傻话的和真开了口：</p><p>「不用啦，没关系。」</p><p>并且露出笑容，表示我已经不生气了。</p><p>……但是。</p><p>「等一下，是我不好啦，原谅我吧！我再认真思考一次就是了！……对了，突然就要那个确实是跳太快了。先从接吻之类的……」</p><p>「我不是都说没关系了吗！而且你讲话太大声了！阿库娅和达克妮丝都在厨房，要是被他们看到这一幕的话……！」</p><p>就在我说到这里的时候。</p><p>我发现和真的视线不在我身上。</p><p>「啊哇哇哇哇哇哇……」</p><p>和真的视线前方，是从走廊的暗处探出头来，双手紧紧握着擦桌子的抹布的阿库娅。</p><p>阿库娅凝视着我们，带着战栗的表情向后退……</p><p>「呐，达克妮丝，大事不好了——！和真和惠惠红着脸黏在一起，说了要接吻还是什么的耶——！」</p><p>我们连忙阻止了打算去报告的阿库娅。</p><h3 id="_7-3" tabindex="-1"><a class="header-anchor" href="#_7-3"><span>7</span></a></h3><p>隔天。</p><p>在聚集到活动据点的成员们面前，我用力挥了一下披风。</p><p>「今天的我气势十足。天气也是万里无云，正是适合火拼的好日子！」</p><p>在摆出耍帅姿势的同时，我拿起爱用的法杖。</p><p>「呐，我姑且问一下，我们是要偷偷熘进坏贵族的宅邸偷东西对吧？火拼是怎样？虽然我不知道那是什么意思，但是听起来就很危险……」</p><p>悠悠一脸不安地对我这么说。</p><p>「火拼就是火拼。这是和真教我的，他说这是在袭击的时候可以用的词汇。总之我们先去贵族宅邸看看，剩下的事情只要靠冲劲和气势搞定就可以了。」</p><p>「呐，我们是盗贼团对吧？我们不是强盗团，是盗贼团对吧？」</p><p>没有理会抓着我的肩膀不住摇晃的悠悠，我问了克莉丝：</p><p>「所以呢，你昨天说要去找值得火拼的贵族，有目标了吗？」</p><p>「呃，嗯，原则上是有啦。不过，我不是要重复悠悠的话，但我们是要去偷东西对吧？不是去打劫对吧？」</p><p>尽管有些害怕，克莉丝还是在聚集到活动据点来的大家面前拿出一张地图。</p><p>那是阿克塞尔周边的地图。</p><p>克莉丝指着位于城镇外面的森林说：</p><p>「事情是这样的。其实这附近有某个贵族的别墅。然后，那里发生了有点奇怪的事。」</p><p>根据克莉丝表示，不知为何，那栋别墅附近传出了在阿克塞尔周遭应该见不到的强大怪物的目击情报。</p><p>「那应该是冒险者公会的管辖范围吧？听说，最近因为阿克塞尔的冒险者们狩猎了好几个悬有重赏的目标，赚了点小钱，大家都不工作了。是不是因为这样，才有大型怪物搬过来吃那些弱小的怪物啊？」</p><p>听我这么说，克莉丝一脸复杂地摇了摇头。</p><p>「或许是这样，也或许不是。我之所以这么说是因为那个贵族家可能用了某种神器。」</p><p>那种神器，是能够随机召唤，并且加以使唤。</p><p>如果真的有这种东西，确实足以称为神器……</p><p>「这种听都没听过的贵族，有办法弄到那么厉害的东西吗？那种东西就算定个天文数字的价格也不奇怪吧。」</p><p>「其实呢，为了不被任何人发现，那个神器被丢进有凶恶的大咖悬赏对象沉睡的湖底，并封印在里面。」</p><p>凶恶的大咖悬赏对象。</p><p>……我记得，最近好像才在阿克塞尔附近的湖里有这样的一只怪物遭到讨伐。</p><p>「没错，就是那只叫多头水蛇的悬赏怪物。那块土地的魔力被多头水蛇吸光，湖水也遭到污染。封印了神器的人似乎认为没有人会接近那种地方，所以才选择了那里……但是湖泊附近的绿化速度远比想像中的还要快上许多，人们开始在那一带往来了。于是，封印了神器的那个人想把神器移到更安全的地方去，好像就在湖底打捞了一阵，但是……」</p><p>「原来如此，神器已经被人拿走了是吧。」</p><p>然后就传出这次强大怪物的目击情报。</p><p>而且，仔细想想，把宅邸建在那种地方，而不是有围墙保护的城镇里面也很奇怪。</p><p>既然召唤的怪物是随机出现，那个贵族或许是在出现了不喜欢的怪物之后就直接放生到森林里去了。</p><p>「还有，关于那个神器……不知道为什么经常落入黑心贵族的手中。神器的上一个持有者，是那个名叫阿尔达普的领主大叔。」</p><p>就是一直对达克妮丝情有独钟，后来行踪不明的那个人啊。</p><p>「那么危险的神器，站在王家的立场也不能置之不理。头目大人，请务必要去那间宅邸！」</p><p>「呐，依丽丝，你刚才是不是说了站在王家的立场也不能置之不理啊？」</p><p>「我没有说。」</p><p>一脸严肃的悠悠的视线，逼得爱丽丝一点一点后退。</p><p>这时，原本坐在沙发上乖乖喝着茶的赛西莉表示：</p><p>「派得上用场……那个叫神器的东西派得上用场。召唤出怪物，任它们到处作乱，然后再让阿克西斯教徒潇洒地赶往现场救援。没错，光是这样就能让想要入教的人翻倍了吧！」</p><p>原来如此，也有像这样被漤用的可能性啊。</p><p>越听越让人觉得不能将那个神器置之不理了。</p><p>应该说，这算是相当严重的问题吧。</p><p>该说是问题的规模太过庞大了呢，还是说已经超出我们所能负荷的范围了呢，感觉已经是某种大事件的前兆了。</p><p>不过……</p><p>「我记得回收危险的神器也是银发盗贼团的目的之一。还是先去那间宅邸看看吧！」</p><p>——那是一间似乎才刚盖好没多久，外观还不见脏污，规模略小的宅邸。</p><p>或许是为了防范怪物，宅邸外侧围了一圈坚固的铁栅栏，内侧也设置了许多陷阱。</p><p>嗯，到这里为止都还没问题，但是……</p><p>「事情好像有点严重耶。」</p><p>「呐，现在不是说这种话的时候了吧！我们得快点去救人才行！」</p><p>我们原本打算袭击的那间贵族宅邸，目前正遭受大量的怪物袭击。</p><p>「哎呀——他们该不会是不小心叫出无法以神器使唤的怪物了吧？可是，如果是这样的话，被成群的怪物袭击也太奇怪了。」</p><p>当一旁的克莉丝还在冷静地观察时，爱丽丝拔出了剑。</p><p>「不管怎么说，我想我们还是前去救援比较好吧？光靠那几位警卫恐怕难以抵挡那么多怪物……」</p><p>并且如此请示我的指示。</p><p>仔细一看，警卫们正在栅栏内侧以长枪和弓箭应战。</p><p>然而……</p><p>「不，大姐姐有个主意。现在应该先置之不理才对。」</p><p>赛西莉突然说出这种话来。</p><p>「说的也是。如果是以盗贼团而言，这种时候应该稍微观察一下状况才是正确选择。如果他们真的持有神器，应该会拿出来试图使唤怪物才对。」</p><p>就连克莉丝也如此赞同她的意见。</p><p>「以艾莉丝教徒而言，你的意见跟我很合嘛！没错，就这样到最后一刻都不要管他们，等到那些警卫陷入危机的时候，如果觉得救得了再抱持着要求回报的态度去救他们！到时候怪物的数量也变少了，救起来也比较轻松！」</p><p>「不是啦，我那么说并不是这个意思！只是以盗贼团而言，为了达成目的而想确认神器的有无的话这样做比较好，所以才……！」</p><p>克莉丝连忙解释，但赛西莉只是不住点头。</p><p>「然后确认有神器的话，就要求他们交出来当作是迎救他们的回报是吧。不愧是艾莉丝教徒，想法真是恶劣啊！但是我不讨厌这种做法！」</p><p>「不不不、不是……！我从来没说过要等到最后一刻才救他们啊……！」</p><p>我可以明白克莉丝想说什么。</p><p>的确，如果他们真的持有那个什么神器的话，在陷入危机的时候应该会用才对。</p><p>而且我们还可以省下刻意冒险潜入贵族宅邸确认神器所在地的麻烦。</p><p>「我没想到克莉丝是那么冷酷的人，不过这个方法还算不错。」</p><p>「连惠惠都这样说！不是啦，你们两个听我说！」</p><p>然而。</p><p>「所以我才说不要住在这种地方嘛！」</p><p>「事到如今说这种话也无济于事吧，你也知道大小姐就是这么任性！」</p><p>听见警卫们这样的对话从栅栏里面传出来，悠悠和爱丽丝都带着伤脑筋的表情看着我。</p><p>「大小姐在哪里？至少也要让大小姐逃走才行……！」</p><p>「从刚才开始就不见人影，所以我们也不能逃离这里！」</p><p>这时又听见了这样一番话的我，语气平静地宣告：</p><p>「要对付那么多怪物，即使是我们可能也无法全身而退。」</p><p>「惠惠……」</p><p>悠悠轻轻叫了我一声。</p><p>我并没有回应她，目不转睛地看着袭击贵族宅邸的怪物，继续以平静的语气说了下去：</p><p>「而且，我是盗贼团的头目，有责任尽可能避免让大家以身犯险。我也是高智商的红魔族，所以能够明白就这样置之不理，观察状况应该才是明智的抉择。」</p><p>悠悠当然也能够理解这件事，所以只能无言以对，显得相当失落。</p><p>一旁的爱丽丝依然拿着已经拔出来的剑，视线在贵族宅邸和我之间来回，不断游移。</p><p>而我背对这样的两人，向前踏出一步。</p><p>「但是，我不仅是盗贼团的头目，更是一名冒险者。心里想着有朝一日要打倒魔王的我，怎么可能在面对区区的怪物时耐着性子观察状况呢？」</p><p>在我这么说完之后举起法杖时，身后传来一个轻微的笑声。</p><p>「这样啊。与其搞盗贼团，惠惠还是比较适合当冒险者。」</p><p>听着克莉丝这番不像是在夸奖我，却隐约透露出喜悦之意的话语，我开始咏唱。</p><p>我是很想变得和自己所崇拜的那两个人一样，但没办法。</p><p>面对怪物还要观察状况，这种事情我办不到。</p><p>「惠惠，你没解决掉的漏网之鱼就交给我吧，我会帮你全部收十掉！」</p><p>在开始咏唱的我的右后方，悠悠开心地举起魔杖。</p><p>居然认定我的攻击之下会有漏网之鱼，真亏她有胆这么说。</p><p>「施展了魔法之后会被怪物发现。往我们这边过来的对手，就交给我对付！我今天是保护头目大人的盾牌！」</p><p>我想这个孩子才是最应该被人保护的才对，但是爱丽丝丝毫没有察觉我的担心，在我的左后方举起剑来。</p>`,130),e(m,{src:`/images/C1/04.avif`,alt:`插图`,width:`850`,height:`1257`}),l[23]||=s(`<p>「那大姐姐就在最后面帮大家加油！受了伤的孩子大姐姐会好好治疗，记得要说喔！」</p><p>这种时候还是一点都不会变的赛西莉，让大家不禁莞尔。</p><p>克莉丝也拔出匕首，守住我的背后。</p><p>「那么，我偶尔也来努力一下好了。我要让你们见识一下盗贼有多厉害。那么，惠惠，咱们动手吧！」</p><p>盗贼团的正式活动，或许再等到晚一点会比较好吧。</p><p>比方说，等到打倒魔王，世界变得和平之后。</p><p>「快点啊，第一招让给你就是了，快让我们见识一下头目的真本事啊。」</p><p>听着悠悠这番挑衅的话语。</p><p>「『Explosion』——————！」</p><p>我全力施展了魔法——！</p><h3 id="_8-2" tabindex="-1"><a class="header-anchor" href="#_8-2"><span>8</span></a></h3><p>魔力恢复到能够走动的程度的我，拖着沉重的步伐回到豪宅之后。</p><p>「欢迎回来～～！呐，惠惠，你听我说！今天的晚餐是很久没吃的霜降红蟹喔！让我回想起我们刚搬来这间豪宅的时候呢！」</p><p>阿库娅带着满面的笑容出来迎接我，手上还拿着蟹螯一开一合地玩。</p><p>「还真是丰盛啊。没想到我一生中居然可以吃到两次霜降红蟹。」</p><p>拖着因为魔力不足而感到倦怠的身体，我倒在沙发上。</p><p>「你今天看起来又比平常还要疲惫呢。话说爆炸声都传到这里来了，可见你今天的气势特别不一样喔。虽然没有亲眼看到，不过今天的爆裂魔法我可以给你九十五分。」</p><p>坐在餐桌旁边期待不已的和真这么说。</p><p>「话说回来，惠惠，你今天的表情看起来相当神清气爽呢。是不是有什么好事啊？」</p><p>达克妮丝在将沸腾的火锅放到餐桌上的同时，带着温柔的表情这么问我。</p><p>「今天我认清了自己最想做的事情。一定是这个原因吧。」</p><p>「你想做的事情除了施展爆裂魔法之外还有什么啊？」</p><p>我难得心旷神怡的好心情被和真的乱插嘴泼了一盆冷水。</p><p>他到底要把我当成只有爆裂魔法的女人到什么时候啊？</p><p>像今天也是，我带领大家去了贵族宅邸，发现那里的人不知为何遭到怪物袭击，为了救他们，我光是施展了爆裂魔法就——</p><p>「……奇怪？我今天好像只有施展爆裂魔法而已耶？」</p><p>「你突然说这种话是怎样？应该说，你怎么事到如今才在说这种话啊？你一直都只有施展爆裂魔法而已啊？追根究柢，如果从你身上抽掉爆裂魔法，就只剩下萝莉成分了吧。」</p><p>正当我满心疑问时，迅速倒着酒的和真什么不好叫，偏偏叫了我萝莉。</p><p>「那不时对我性骚扰的和真就是萝莉控了。冒险者公会会好好帮你宣扬控萝真之名。」</p><p>「住、住手，你要自爆也别把我卷进去。这样一来小萝莉之名也会正式跟着你喔。」</p><p>没有理会这样的我们，阿库娅已经把螃蟹放到烤炉上烤了起来。</p><p>「真是的，有螃蟹在面前还可以吵架，你们两个在想什么啊？就不能像我一样冷静一点，活得沉稳一点吗？」</p><p>「你刚才在拿到达克妮丝的老爸给我们的螃蟹的时候明明还高兴到不停蹦跳，最后踢到沙发哭了出来不是吗。」</p><p>正当我想着要在吃饭前先去洗个手的时候，刚把火锅放到餐桌上的达克妮丝就来到我身边，扶我起身。</p><p>「我不知道发生了什么事，不过惠惠今天看起来特别高兴呢。吃晚餐的时候，可以说说你今天做了些什么吗？最近的惠惠看起来总是非常开心。」</p><p>说着，她对我笑了笑。</p><p>——结果，那个时候我们搭救的贵族，一言以蔽之就是烂透了。</p><p>在我们驱逐了怪物之后，似乎是一个人逃到宅邸外面去，年纪和我们差不了多少的贵族千金大小姐就现身了。</p><p>我们也没有要求谢礼，她却突然开口就说：「我又没叫你们来救援。」</p><p>要不是我处于耗尽魔力，无法动弹的状态，我可能已经忍不住攻击她了。</p><p>那间贵族宅邸为什么会遭受怪物袭击？</p><p>最根本的问题是，他们为什么要把宅邸建在那里？</p><p>尽管还留有许多疑问，克莉丝却表示这些事情总有一天会解决。</p><p>她之所以这么说，是因为银发盗贼团好像也盯上了那间贵族宅邸。</p><p>克莉丝为什么会知道这种事情让我有点好奇，不过这大概也是因为盗贼之间有着某种情报网吧。</p><p>「达克妮丝说得好。其实我也很好奇惠惠最近在做什么。想说你会不会又做出什么奇怪的事情来了。」</p><p>视线没有从被烤得滋滋作响的螃蟹上头移开的和真这么问。</p><p>「我知道喔，因为赛西莉有告诉我。听她说，好像是在榨取美少女的精华，而且还想到了什么借此赚取暴利的方法。」</p><p>听她这么说，和真和达克妮丝用一种「你该不会开始做什么见不得人的生意了吧」的眼神看着我。</p><p>「我会好好告诉大家我在做什么啦。我并没有做什么见不得人的事情喔……真的喔。真的啦！所以不要用那种眼神看我！」</p><p>我连忙向大家解释，同时回想起今天的事情。</p><p>这种无疾而终的结果多少让我有点不甘心，但是又觉得，如果我所崇拜的他们能够替我们扳回一城，那好像也不错。</p><p>不过，可以的话。</p><p>「就在烟火大会那天的晚上。被警察释放的我，正一个人走在回豪宅的路上时——」</p><p>真希望总有一天，能够再次见到我所崇拜的他们——</p><h2 id="最终话-反击的盗贼团" tabindex="-1"><a class="header-anchor" href="#最终话-反击的盗贼团"><span>最终话 反击的盗贼团</span></a></h2>`,56),e(m,{src:`/images/C1/26.avif`,alt:`章节标题`,collapsed:``,width:`850`,height:`1257`}),l[24]||=s(`<h3 id="_1-4" tabindex="-1"><a class="header-anchor" href="#_1-4"><span>1</span></a></h3><p>事情发生在我们前往邻国埃尔罗得，经历了种种之后回到阿克塞尔来，然后又过了一阵子的某一天。</p><p>「这里就是朵内利家的宅邸啊。我不知道为什么要盖在这么偏僻的地方，不过倒是盖得还满气派的嘛。」</p><p>我们来到兀自伫立在阿克塞尔附近的森林当中，名叫朵内利的贵族的宅邸。</p><p>仰望着宅邸的我如此表示，由于今天是来见贵族而穿了礼服的达克妮丝便用力点了点头说：</p><p>「朵内利家是从以前就相当致力在从商的贵族。尽管位阶不高，在资金方面却足以凌驾于我们家之上。不过，他们的年轻女当家是个令人厌恶的家伙。明明只是个位阶不高的暴发户，在社交界见到我的时候却动不动就话中带刺，说我们家是没有钱的贫穷贵族，瞧不起我们家！和真，这次的委托可能有什么内幕，你要小心喔。」</p><p>或许是他们两家贵族之间的关系不太好，达克妮丝显得相当愤慨。而在他身旁同样穿着礼服的阿库娅不知为何同样激动地表示：</p><p>「我知道朵内利家！之前我花光零用钱，去找他们家经营的金融业者借钱的时候，他们说不借钱给阿克西斯教徒就把我赶走了！」</p><p>「你这个家伙在我没注意的时候干了这种事情啊……真是的，在埃尔罗得想喂我安眠药夺走我的贞操的达克妮丝也好，你也罢，难道就不能学学最近这么乖的惠惠吗？」</p><p>「！」</p><p>听我这么说，惠惠整个人抖了一下。</p><p>「……喂，你最近是不是闯了什么祸？」</p><p>「没有。」</p><p>看着尽管别开视线还是斩钉截铁地如此断言的惠惠，我敢肯定这个家伙绝对闯了什么祸。</p><p>「和、和真……关于想对你下药那件事情我道歉就是了，你可以忘掉那件事当成没发生过吗……就是……那件事对我们双方都很尴尬，都算是污点吧？对吧？不然，回家以后我请你喝好喝的酒就是了……」</p><p>「呐，和真，这家不可以啦，我们拒绝他们吧！嫌弃阿克西斯教徒的家族肯定不是什么好东西！」</p><p>我丢下两个吵死人的家伙，敲了敲宅邸的门——</p><p>——我收到了一封信。</p><p>信件的内容是希望我这个阿克塞尔名声最响亮的冒险者，能够接下一项委托。</p><p>对方会想要依赖在邻国埃尔罗得又缔造了一项传说的我，这样的心情我可以理解。</p><p>但是，我每天都为了对付魔王军而在研磨武器、锻炼身体，有很多事情要忙。</p><p>像这种委托原本我都是直接回绝，不过这次的对象是贵族。</p><p>虽然已经有许多关系可以利用，不过现在我也知道了权力之可贵，趁机创建新的关系也还不坏。</p><p>我原本是这么想，而打算接受委托的……</p><p>「幸会。我是朵内利家的当家，名叫卡莲。」</p><p>我们被带到会客室之后，在此向我们打招呼的，是一个年纪比我略大的红发少女。</p><p>身高颇高，和我差不多，是个苗条的模特儿体型的美女。</p><p>「你就是佐藤和真先生对吧？今天承蒙你愿意接受本家的请求，真是太感谢……」</p><p>自称卡莲的那个人在看见我之后，停下了动作。</p><p>不对，正确来说是看见躲在我背后的惠惠。</p><p>「……抱歉，请你稍等一下。」</p><p>「好、好的……没关系……」</p><p>我抓着依然缩在我背后的惠惠的后颈暂时离开会客室，来到走廊上。</p><p>「你跟那个叫卡莲的人怎么了？快说。」</p><p>「你在说什么啊？我和她是第一次见面当然没怎样……我知道了，我说就是了，不要用『Drain Touch』！用了我就无法施展今天的爆裂魔法了！」</p><p>自从来到这间宅邸状况就不太对劲的惠惠，一面提防着我已经伸到她身边的右手，一面开了口：</p><p>「……其实之前这个家曾经遭受怪物袭击，那个时候我和同伴们一起营救了他们——」</p><p>我不知道惠惠跑来这种森林里面做什么，不过听了她告诉我的部分，内容感觉并没有什么好隐瞒的。</p><p>「什么嘛，我还以为有什么隐情呢，像是在打倒怪物的时候爆裂魔法破坏了宅邸的一部分，或是扫荡怪物的时候也一起扫荡了警卫们之类呢。」</p><p>「不，并没有类似这样的事情发生……」</p><p>嘴上这么说，惠惠不知为何却含煳其词。</p><p>「如果问心无愧的话你大可以抬头挺胸啊。怎么，你是因为瞒着我们去讨伐怪物怕我们会介意吗？我是有点担心，不过乍听之下，你的那些同伴好像也不弱嘛。」</p><p>「是啊，有个还满强的基层人员，跟一个没朋友的红魔族。再加上阿克西斯教的祭司和盗贼吧。」</p><p>这个小队结构有点莫名其妙，不过没朋友的红魔族大概就是悠悠吧，有那个女孩跟着她的话应该不太需要担心。</p><p>「既然如此就没有任何问题了。毕竟赚经验值也很重要嘛，我有空的时候也去陪你们好了。」</p><p>「和真明明每天都有空吧。不过，如果和真愿意陪我们的话，我就让你成为我们的同伴好了。包你吓一跳喔！」</p><p>虽然听不太懂，不过既然她看起来那么开心就好了。</p><p>我带着惠惠再次打开会客室的门……</p><p>「快道歉！你们说不借钱给阿克西斯教徒还把我赶跑，快为了这件事好好向我道歉！」</p><p>「非、非常抱歉。不好意思，我代替我的员工向你谢罪……」</p><p>便看见逼卡莲道歉的阿库娅，还有在她身旁，以双手遮着通红的脸的达克妮丝，害我瞬间很想直接闪人。</p><h3 id="_2-4" tabindex="-1"><a class="header-anchor" href="#_2-4"><span>2</span></a></h3><p>「——要驱除在宅邸附近游荡的怪物们？」</p><p>「是的。如果是在这个城镇也是以武功高强而闻名的佐藤先生的小队，我也能够安心委托……」</p><p>拿茶点给了气愤的阿库娅让她安静下来之后，我们正式听对方说明了委托内容。</p><p>「这个嘛，我们是很厉害没错啦。不过报酬未免也太高了吧？这可以当作你对我们的评价就是这么高吧？」</p><p>「喂，你就不能谦虚一点吗？而且我一开始就告诉过你了，他们家的委托可能另有内情，要你当心啊……」</p><p>正当我一脸认真地听对方说话时，达克妮丝一边如此耳语，一边用手肘顶了我的肚子。</p><p>话是这么说没错，但是考虑到我们的功绩，之前的评价才叫作不当，这才是正确的对待方式。</p><p>至于卡莲，她在我稍微挺起胸膛的时候突然伸出双手，紧紧握住我的手。</p><p>「那是当然了，佐藤先生。我早就久仰你的大名了。人人都说佐藤先生运用许多的技能以及令人敬佩的机智，将众多魔王军干部玩弄于股掌之间。而且队友们也都是大祭司与大法师等等，各个都是可靠的上级职业……！」</p><p>「这个嘛，我们是很厉害没错啦。如果没有我的话，还真不知道这个城镇现在会变成怎样呢……」</p><p>卡莲握着我的手，以仰慕的眼神看着我这么说，让我感到有点不好意思，却还是忍不住将胸膛挺得更高了。</p><p>这时，在这样的我身旁，达克妮丝一脸厌烦地开口说：</p><p>「……喂，和真的小队里还有本小姐好吗？」</p><p>总觉得她的眼神有点凶恶，语气也很冷淡。</p><p>「哎呀，我还以为你今天只是怕跟你关系亲密的男人被我抢走，所以死赖着一起跟来罢了呢……原来达斯堤尼斯爵士在学人家当冒险者的那个传闻是真的呀。只有家世可取，没有半点钱的贵族还真是辛苦啊。」</p><p>卡莲将缠在我的手上的手指松开，对着这样的达克妮丝笑了一下。</p><p>「呵呵，你这么说还真有意思。果然是靠钱爬上贵族阶级的家族，看来你一点都不懂得什么叫作礼仪和拘谨呢。不同于某些为了钱可能不惜卖身，家名无足轻重也不用肩负责任的暴发户贵族，达斯堤尼斯家身为国家的栋梁，有贵族的义务要顾，所以才像这样挺身而出，成为保护庶民的盾牌。」</p><p>达克妮丝和刚才缩起身子用手肘顶我的时候截然不同，她缓缓挺直背嵴，散发出优雅与威严，以微笑回应对方。</p><p>……咦？这是怎样，好恐怖。</p><p>「哎呀，不愧是达斯堤尼斯大人。为了你所谓的贵族的义务，穷困到在社交界必须穿同一套礼服好几次，真是令我动容。如果你不嫌弃我穿过的东西，不妨带几套礼服回去吧？」</p><p>眼中毫无笑意的卡莲如此表示，达克妮丝也带着僵硬的笑容说：</p><p>「不愧是每次穿完礼服就会丢掉的家族，在体型和心态两方面的肚量都很大呢。不过，我并不是因为没钱，而是因为喜欢穿家母以前穿过的礼服才那么做的，所以不劳你费心了。而且……」</p><p>说完，她为了强调那个部位，刻意双手抱胸。</p><p>「既然是你穿过的礼服…………无论如何，胸围的部分我就塞不下了吧。」</p><p>完全不是譬喻，我感觉到现场的空气真的冻结了。</p><p>……这是怎样，真的很恐怖耶。</p><p>我都想回家了。</p><p>随着一个用力拍桌的声音，卡莲突然站了起来。</p><p>「你再说一次看看啊，只有身材可取的达斯堤尼斯！男人们比较喜欢我这种苗条的体型好吗！」</p><p>「是吗，我偶尔出现在社交界的时候，男人们的视线好像都集中在我身上而不是你身上耶，那总不会是我的错觉吧？每次胸围变大的时候都要修改礼服，真是累人呢。朵内利小姐每次都买新礼服的理由大概也是这样吧？」</p><p>达克妮丝也同样站了起来，刻意将交叠在胸部下方的双臂向上一托，强调那个部位。</p><p>「啊啊，好重好重……如果不是在当冒险者可以锻炼身体的话，我大概也支撑不了这个重量吧。」</p>`,84),e(m,{src:`/images/C1/17.avif`,alt:`插图`,width:`850`,height:`1257`}),l[25]||=s(`<p>「你、你这个女人！」</p><p>咬牙切齿的卡莲瞪着达克妮丝看，而达克妮丝本人却是刻意皱起眉头，装出一脸伤脑筋的表情。</p><p>「朵内利小姐看着这个部位的眼神好像很羡慕的样子，可是这么大一点好处也没有喔。不但重，又容易肩膀酸痛，可以穿的衣服也很有限，铠甲也得订制才行，而且男人的视线更是会像这样……你、你这个家伙，我是知道你会看，但是也看得太不客气了吧……」</p><p>见我直盯着被她托高的那个部位看，达克妮丝稍微后退了几步。</p><p>「好痛！呜喂，你这是在做什么啊，惠惠？我又不是在挑衅你……！算我不对就是了，不要拉我的头发！」</p><p>然后惠惠不知为何就开始拉扯达克妮丝的头发，让卡莲看见这一幕似乎就比较没有那么气愤了。</p><p>「那、那个……所以，佐藤先生愿意接下这项委托吗？」</p><p>她叹了口气之后，露出很表面的笑容，对我这么问道。</p><h3 id="_3-4" tabindex="-1"><a class="header-anchor" href="#_3-4"><span>3</span></a></h3><p>翌日。</p><p>决定接下委托的我们，准备好齐全的装备之后，再次来到了宅邸附近。</p><p>驱除突然出现在宅邸周边的众多强大怪物。</p><p>这就是我们这次接下的委托。</p><p>「不过，为什么只有在这种地方一直冒出强大的怪物啊？这里是不是长了什么好吃的东西啊？应该说，我总觉得有种不祥的预感。我们今天先回家，改天再来好不好？」</p><p>我们在宅邸附近巡逻，寻找怪物的身影。</p><p>「你这个家伙，上次下雨的时候我本来要叫你去买晚餐用的食材，那个时候你也说有不祥的预感所以不肯外出，结果也只是在家打电动啊。应该说，怪物会随便改变栖息环境吗？我是接下了委托没错，但是讨伐目标也只说是宅邸周边的强大怪物，说得不清不楚的。如果目标是不死怪物的话，我们这边倒是有个很适合用来吸引目标的诱饵就是了……」</p><p>「呐，我姑且问一下，你所说的诱饵不是指我吧？」</p><p>阿库娅用力拉了拉我的衣袖，不过我当然没有回答的必要。</p><p>……话说回来。</p><p>「我还真没想到你会说那种话耶。温柔贤淑的贵族千金这个头衔在那一刻终于消失殆尽了呢。你是怎么说的来着，『男人们的视线好像都集中在我身上』是吧？什么嘛，你在社交界的时候就不是很介意曝身在那种视线之中了嘛。」</p><p>「不、不是……！才不是这样呢，在那种场合有些时候就是得借由视线进行贵族之间的攻防……」</p><p>听我那么说，达克妮丝连忙解释。</p><p>「就是说啊。而且还一下挺胸一下托胸的，我还是第一次见到那么充满挑衅意味的达克妮丝呢。原来如此，其实你也是做得出那种事情来的，只是我们不知道而已。你是怎么说的来着，『啊啊，好重好重……如果不是在当冒险者可以锻炼身体的话，我大概也支撑不了这个重量』是吧。那个时候的表情还真是信心十足呢。」</p><p>惠惠也如此追击达克妮丝，害她面红耳赤地越走越快。</p><p>正当达克妮丝拔出挂在腰际的剑对着森林的草木乱挥，借此泄愤的时候。</p><p>「嗯？喂，你等一下。」</p><p>我以感应危机技能感觉到些微的气息，拉住达克妮丝的披风的那个瞬间。</p><p>「怎样啦，和真？要是你还想继续羞辱我的话，我也有……」</p><p>达克妮丝的话才刚说到这里，她的大剑已经随着一个清脆的金属声飞上了天。</p><p>要是达克妮丝就这样一直往前走的话，现在大概已经跟自己的大剑在一起了吧。</p><p>察觉到这件事的达克妮丝丢掉断了一半的剑，展开双手护着我们。</p><p>但是，眼前的草木当中并没有怪物潜伏的迹象。</p><p>这种时候……</p><p>「敌人要从上面来了！小心！」</p><p>我迅速将视线转向上方，并且从达克妮丝背后推开她——！</p><p>——我所在的地方，是现在已经相当熟悉的白色房间。</p><p>隐约显露出困惑之色，一脸有话想说的样子的艾莉丝站在我的眼前。</p><p>「……那个……」</p><p>「……不好意思。现在可以先什么都不要说，让我一个人静一静吗？」</p><p>我当场蹲坐在地上，抱着膝盖把脸埋了起来。</p><p>一回想起自己一脸认真地大声宣告敌人会从上面来的那个瞬间，我就害羞到很想干脆就这样死掉。</p><p>……不，我现在是真的死掉了就是。</p><p>「正常来说那种状况都会从上面来吧……」</p><p>没错，我抬了头也没看到任何敌人。</p><p>既不在前面，左右也连个影子都没有。</p><p>既然如此，就只剩下……</p><p>「从下面冒出来根本是来乱的吧。我已经受够这个世界了……」</p><p>突然从地面爬出来的那只看似蚁狮的怪物，就直接把推开达克妮丝的我给——</p><p>「……艾莉丝女神，你该不会是在忍笑吧？不用忍没关系喔。」</p><p>「没有喔！我没有在忍笑，不用顾虑我！不对，说不用顾虑我好像也很奇怪，总之我不会在有人死掉的状况下做出那种不应该的事情！」</p><p>那么大声警告大家，结果却从反方向遭受袭击，未免也太丢脸了。</p><p>艾莉丝维持着一本正经的表情，肩膀却不住微微颤抖，算她有才。</p><p>「是无所谓啦……应该说，为什么阿克塞尔附近会有那种怪物啊？我好歹也已经是等级不错高的冒险者了，还是被一招秒掉耶。」</p><p>听我这么说，艾莉丝原本还在颤抖的肩膀突然停止不动。</p><p>「关于这件事……和真先生，你今晚有空吗？」</p><p>然后带着那一本正经的表情注视着我，并且对我这么说。</p><p>「要问我有没有空的话，我每天随时都有空啊。怎么，要来夜袭吗？我可以现在就上也没关系喔。」</p><p>「不是啦，是想请你协助我找神器！捉弄女神小心遭天谴喔！」</p><p>什么嘛，原来是老样子啊。</p><p>「就算是那件事也没关系啦……咦，难不成这和神器有关吗？」</p><p>听语调略显失望的我这么说，艾莉丝缓缓摇了摇头。</p><p>「不，这个还不清楚……不过，有件事情让我有点担心。」</p><p>——原本由那个名叫阿尔达普的领主所持有的神器。</p><p>那是能够随机召唤怪物并使唤之的道具，克莉丝在回收了那个东西之后，应该已经封印到湖底了才对……</p><p>「多头水蛇栖息的那个湖泊周边，因为大地失去了魔力，我原本以为会好一阵子没办法住人的……但不知为何，魔力的恢复与绿化都比我原本预期的还要迅速，也因此居民们开始开拓那个地方了。然后，我想在被镇民们找到之前把神器移到别的地方去，所以打捞了一下湖底，但是……」</p><p>「神器已经被人拿走了，找不到是吧。」</p><p>「是的……」</p><p>平常只让我见过温柔的笑容和认真的表情的艾莉丝显得相当沮丧。</p><p>原来如此，结果这次突然传出不知道从哪冒出来的强大怪物的骚动。</p><p>听说那个叫作卡莲的贵族别的没有就是钱最多，弄到神器的可能性也很高。</p><p>于是她就在远离城镇的森林里盖了宅邸，像是在玩转蛋一样召唤怪物，抽到铭谢惠顾就直接放生……这样想确实很合理。</p><p>……但如果是这样的话，感觉神器遗失的时间点和卡莲在森林里盖宅邸的时间点好像搭不起来，不过这里是有魔法的异世界。</p><p>或许她使用了达克妮丝在去埃尔罗得的路上给我们看过的那种，可以像冲泡式食品一样轻松完成的魔法宅邸。</p><p>不同于比较没用的那个女神，艾莉丝会出包是很罕见的事情，不过她也是我在这个世界唯一尊敬、崇拜的头目。</p><p>「可以啊。简单来说就是要调查神器在不在那个名叫卡莲的人家里对吧？我陪你去。」</p><p>听我爽快答应，艾莉丝的表情瞬间亮了起来。</p><p>然后，她不知为何露出有点像是小朋友想到要恶作剧的时候的表情。</p><p>「今天晚上除了和真先生以外，我还打算带别的帮手去。至于是谁……我要先保密。」</p><p>说完，她开心地把食指放在嘴唇上。</p><h3 id="_4-4" tabindex="-1"><a class="header-anchor" href="#_4-4"><span>4</span></a></h3><p>「——敌人要从上面来了！小心！在大喊这句有名的台词的同时，却被怪物从下方偷袭杀掉的和真先生，欢迎回来！」</p><p>刚复活就看到这个狂出包女神的灿烂笑容，真想给她一巴掌。</p><p>似乎是躺在阿库娅的大腿上的我挺起身来，四处张望。</p><p>「你醒了啊，和真。这次该怎么说呢……谢谢你救了我。原本应该是我以身为盾的，真不好意思。」</p><p>铠甲上到处都是凹痕，大口喘着气的达克妮丝靠到我身边，跪了下来。</p><p>仔细一看，那个像蚁狮的怪物，不但尖锐的颚部被折断了，身体也像是被用力勒紧过似的扁塌。</p><p>我们的成员当中能够办到这种事情的……</p><p>「不过，你保护了我是让我很高兴，但你应该多信任一下我的耐打度才对。下次……怎、怎么了，和真？你那是什么眼神啊？应该说，你那个表情是怎样？」</p><p>发现我以有点退避三舍的眼神看着她，让达克妮丝露出一脸困惑的表情。</p><p>「没有啦，我只是想说你干脆不要拿武器了，赤手空拳还比较好吧。我说的没错吧？应该说你不但是前锋类型的上级职业，等级也很高。感觉差不多可以徒手掐死一只熊了吧。」</p><p>听见依然觉得很退避三舍的我这么说，达克妮丝大叫了一声。</p><p>「不、不是啦，和真！就算是我也没办法单靠自己的力量掐死那么硬的怪物！是因为那只怪物杀死你的方式太夸张了，阿库娅才会气到对我施展了特别强大的支持魔法！」</p><p>或许是不想被当成肌肉女吧，达克妮丝连忙对我这么说。</p><p>「杀死我的方式太夸张是怎样，我这次是怎么死的啊？感觉只是一瞬间而已，我完全不记得。」</p><p>「你整个人从头顶到胯下被俐落地一分为二……」</p><p>「我不想听我不想听！喂，等一下，我之前的状态有那么恐怖？……啊，我还想说死成那样为什么衣服还好好的，原来衣服换过了！」</p><p>喂，等一下，是谁帮我穿衣服的？</p><p>我看向达克妮丝和惠惠，她们两个都勐然把头转开。</p><p>是哪一个？</p><p>这种反应是哪一个？</p><p>这时，看着疑惑的我，阿库娅露出温柔的微笑。</p><p>「没事的，和真，你放心吧。本小姐可是名为女神的尊贵存在，看见身为人类的你的裸体也不觉得怎样。」</p><p>「吵死了，就只有这种时候会露出那种看起来很像女神的笑容是怎样！」</p><p>——虽然只打倒了一只怪物，但既然已经有了死伤，我们决定今天还是先就此收摊了。</p><p>讨伐委托是看当天打倒了几只的成效制。</p><p>打倒一只的单价非常高，当初接下委托的时候还觉得这个工作很好赚……</p><p>「一只……是吗？」</p><p>在我们昨天来过的会客室里，卡莲听了我们的报告，瞪大了眼睛。</p><p>「是啊，只有一只。是我们力有未逮，非常抱歉。不过……」</p><p>达克妮丝的话还没说完，卡莲已经伸手制止了她。</p><p>「一只？有达斯堤尼斯大人在，却只打倒了一只？」</p><p>卡莲以嘲讽的语气这么说完之后，突然笑了出来。</p><p>「啊哈哈哈哈哈哈，平常那么会说大话的达斯堤尼斯大人，只打倒了一只吗？而且还是在带着据说曾经打倒魔王军干部，阿克塞尔第一的冒险者的状况之下？」</p><p>卡莲带着不怀好意的笑容抬头看着达克妮丝，而达克妮丝被这么一激也火大了，突然就站了起来。</p><p>「有话想说就快点说清楚啊！我知道你讨厌我，但是如果你连我的同伴都想侮辱的话，我也另有打算！」</p><p>「我想说的话可多着呢！都怪你们家在担任代理领主之后对贷款业务加了一堆限制，害得我们最近的营业额大幅下滑！之前阿尔达普大人当领主的时候我们明明还赚得很多耶，他是上哪去了啊！」</p><p>卡莲也当场站了起来，像是要与之对抗似的。</p><p>「谁教你抱怨我们家了，我是问你对讨伐数量只有一只这件事有什么意见！不过正好，既然你这么想的话，我就在这里解决这件事！贷款是必要的工作，我也不会叫你不准借钱给别人，但是你们那里不但年利率高得夸张，催款的方式也很肮脏！」</p><p>「不谙世事的深闺千金大小姐就是这么搞不清楚状况才伤脑筋。无论年利率多高，既然有人愿意向我们借钱，就代表是双方都愿意接受的契约。而且，你说我们催款的方式太严苛？借钱的时候不断鞠躬哈腰，还钱的时候却反过来指责我们，那种人活该被我们强制回收！你就是这样才会欠阿尔达普大人钱还被迫嫁给他，最后还被逃婚！」</p><p>啊，刚才那个连我都知道不应该。</p><p>卡莲说了不应该说的事情。</p><p>「混帐东西，不过是个下级贵族竟敢口出狂言！给我乖乖跪下，我要宰了你！」</p><p>「有有、有本事你就试试看啊！反正你一定只是嘴上说说而已的吧，达斯堤尼斯……达斯堤尼斯？等一下，你现在面对的不是老百姓，要是你没有任何理由就把我杀掉的话，会演变成很严重的问题喔！」</p><p>「像你这种靠钱当上贵族的黑心高利贷，就算消失了也不会对国家和百姓造成困扰！我要为了世间、为了苍生解决掉你，之后无论是要坐牢还是要怎样我都会乖乖就范……惠惠你做什么，不要阻止我！接下来我要对这个不入流的坏蛋行使正义！」</p><p>达克妮丝揪着卡莲的领子，逼得人家都快哭出来时，惠惠轻轻拉着这样的她的披风。</p><p>「达克妮丝，该适可而止了。因为这次算是我们没有完成任务。就当作是为了刚恢复的和真，我们今天先回去吧？」</p><p>照理来说应该是最暴躁易怒的惠惠轻声这么说。</p><h3 id="_5-4" tabindex="-1"><a class="header-anchor" href="#_5-4"><span>5</span></a></h3><p>当天晚上。</p><p>我们从略显害怕的卡莲手上收下讨伐了一只怪物的报酬之后，立刻回到豪宅，吃完晚餐，在大厅里休息。</p><p>惠惠表示有话要告诉我们大家，于是我就这么听她说了，然而……</p><p>「——抱歉，你可以从头再说一次吗？」</p><p>「可以是可以啦……是这样的，我一时心血来潮成立了一个盗贼团，结果回过神来才发现已经发展到入团申请人数破千的规模了。在得到这个城镇最顶级的宅邸当成活动据点，又有了后盾之后，我想说差不多是时候了，就去那个名叫卡莲的贵族的宅邸发动了袭击。」</p><p>不禁整个人停机的我，在心中自言自语。</p><p>你这个家伙是在搞什么鬼啊？</p><p>在我抱持着如此的感想时，同样整个人僵住的达克妮丝的眼神一飘，开口这么说：</p><p>「这么说来，最近我是听说过这个镇上最顶级的宅邸有了主人……」</p><p>别说了。</p><p>「是啊，我们团里的基层人员稍微动用了一下她的权力，房仲就让我们用了。」</p><p>「等一下，就算是达斯堤尼斯家动用权力，应该也没办法轻易获得那间宅邸的使用权才对。呐，惠惠，你口中的基层人员该不会是……」</p><p>喂，够了，别问了，问下去就无法回头了。</p><p>「这么说来，惠惠在前往埃尔罗得的路上，都是称呼那个叫爱丽丝的孩子是基层人员对吧？」</p><p>「闭嘴啦阿库娅，你平常明明完全没在动脑袋，为什么偏偏挑这种时候问那种多余的问题啊！我们什么都没听到，什么都不知道，懂了吗？」</p><p>「懂什么啊！喂，惠惠，这是怎么回事？换言之，你把爱丽丝殿下拉进一个奇怪的组织里，还和一群不知道在哪里认识的可疑人士一起去袭击那个家伙的宅邸吗！」</p><p>达克妮丝冒着汗这么问，一脸快要哭出来的样子。</p><p>「什么可疑人士啊，没礼貌。成员只有不谙世事的基层人员和没有朋友的红魔族，以及阿克西斯教的祭司跟一个盗贼。除此之外的人我现在都还没让他们入团。」</p><p>除了最后的那个盗贼以外大概都是我认识的人吧。</p><p>为什么只要我稍微一不注意，我的同伴们就会搞出严重的问题来啊？</p><p>「而且正确说来，我们只是计划要袭击之后跑去那个人的家而已，并没有实际执行。我上次不是跟和真说过了吗，因为宅邸里的那些人被怪物袭击，我就击退怪物，救了他们。」</p><p>听惠惠这么说，我稍微松了口气。</p><p>不对，接下来还有很多事情要问她就是了。</p><p>「就算是这样好了，你干嘛要成立那种愚蠢的团体啊？为什么你的人生道路就不能走得更平稳一点呢？」</p><p>听见我发自内心的这番话，惠惠却是露出一脸「这家伙在说什么啊」的表情。</p><p>「这个我之前不是说过了吗？我忘也忘不了，那是大家再次一起吃霜降红蟹的那一天。在大家大啖螃蟹的时候，对于遇见我所崇拜的银发盗贼团的状况还有他们的生存之道，我不是讲得那么热烈吗！如果要说我为什么成立了那样的团体的话，理由大概就是那样了吧。」</p><p>那个时候我只顾着吃螃蟹，完全没听她说了什么，但是事到如今我又不能这么说。</p><p>「而且那个时候，我虽然没有说明到自己成立的是盗贼团，但是关于我在阿克塞尔聚集人力，取得活动据点，还开始工作了，这个我应该有告诉你们吧？」</p><p>「是、是啊，确实是这样……吧……？」</p><p>看见达克妮丝的眼神飘忽不定，我敢肯定这个家伙一样只顾着吃螃蟹也没在听。</p><p>在眼神同样飘忽不定的我身旁，阿库娅抓了抓头，同时不以为意地说：</p><p>「抱歉喔，我只顾着吃螃蟹都没在听。」</p><p>……我和达克妮丝的水准也跟这个家伙一样啊。</p><p>「——然后，你救了那个贵族之后，她不但没有给你礼金，甚至连谢谢都没说一声就把你赶走了，是吧。」</p><p>听完惠惠和那个贵族之间的纠纷之后，我如此总结，向她确认。</p><p>「是的，那个叫卡莲的贵族之所以在看到我的时候那么吃惊，大概是因为想起那个时候的事情而感到尴尬吧。至于我这边，如果是很正常的刚好路过顺便救人也就算了，事实上却是原本要去袭击，结果看到他们不知怎地遭受怪物袭击，所以心血来潮地救了他们……」</p><p>惠惠显得坐立难安，整个人缩在一起。</p><p>「所以，惠惠也因为有点心虚而不敢坚持要报酬，就那么让步了是吧。」</p><p>「没错……」</p><p>听了我最后的确认，惠惠似乎回想起当时的状况，双肩一垮，显得相当沮丧。</p><p>我想，惠惠她自己其实也不是那么想要钱吧。</p><p>但是，那样形同是在团员们面前被赖帐，似乎让她相当烦恼。</p><p>……这时，原本闭着眼睛听她说的达克妮丝突然杏眼圆睁，站了起来。</p><p>「那个该死的暴发户还是一样小气又爱耍心机！瞧不起和真和我或许还可以原谅，但是她再怎么说也是贵族，被年纪轻轻的惠惠救了之后居然连一句道谢也没说就把人赶走，绝对不可原谅！」</p><p>「喂喂，你说的话我是可以认同，但是她瞧不起我你就没意见喔？」</p><p>也不知道有没有在听我说，达克妮丝的眼中闪现凶光。</p><p>「和真，明天行动！我原本是想说现在立刻动身的，不过明天一早我们能找到多少人就带多少人去袭击她们家！惠惠不是也说了吗，她原本打算袭击那里。你有达斯堤尼斯家做担保，尽管烧毁他们家吧，不用客气！」</p><p>「不要连你也说这种蠢话！就连急躁的惠惠都打消那个念头了好吗！」</p><p>「不，我那个时候只是因为成群的强大怪物出现在眼前，所以暂时放下盗贼团，顺应冒险者的本能罢了。」</p><p>可以不要再走这种自己破坏自己佳话的路线了吗！</p><p>「你们好像有很多事情要烦恼呢。为了避免事情变得更复杂，我还是乖乖待在这里喝酒好了。」</p><p>这是为什么呢，唯有今天阿库娅看起来最像正常人。</p><p>「等着瞧吧，该死的朵内利！我已经不管会有任何后果了！等到一切都结束之后无论要上法庭还是怎样我都愿意接受。我要让那个家伙好看！」</p><p>听达克妮丝做出如此危险的宣言，我飞也似的逃回房间。</p><h3 id="_6-4" tabindex="-1"><a class="header-anchor" href="#_6-4"><span>6</span></a></h3><p>到了四下已经完全变黑，房舍的灯火也都熄灭的时刻。</p><p>有人轻轻敲了我的房门。</p><p>「我醒着——」</p><p>在棉被里磙来磙去的我表示要来者进来之后，一个娇小的人影便走了进来。</p><p>「不好意思，这么晚了还来找你。」</p><p>走进房间里的是惠惠。</p><p>话虽如此，都已经这个时间了，她也没换上睡衣，害我想像了一下她是不是在吃完晚餐之后就一直闷闷不乐到现在。</p><p>没错，感觉这个家伙在我复活之后就一直有点沮丧。</p><p>她为了不让我们察觉，一直装得和平常没有两样，但是和她相处了这么久的我，早就看穿了。</p><p>「怎么了？你看起来好像不是要来讲些什么有情调的事情，感觉也不太像是可以开玩笑的样子。」</p><p>我从床上坐了起来，为了不让她消沈的更严重而这么问。</p><p>惠惠双肩一垮，低下头之后……</p><p>「对不起。」</p><p>便轻声向我道歉。</p><p>「不，你突然跑来我的房间然后只说这三个字的话，光看这个场面感觉很像是我被甩了，让我不太舒服耶。」</p><p>我催惠惠继续说下去，而她依然低着头……</p><p>「如果我之前没有救那个贵族，而是真的去袭击那间宅邸的话，说不定和真今天就不会死了。之所以这么说，是因为那个贵族的宅邸附近冒出强大的怪物这件事本身，原因很有可能出在那个名叫卡莲的人身上……」</p><p>突然对我这么说。</p><p>奇怪？</p><p>应该说，我今天已经听别人说过类似的话了耶。</p><p>惠惠继续对默不作声的我说：</p><p>「那个贵族的家里，可能有个会召唤怪物的神器。如果我当时成功夺取了那个东西的话，和真就不会碰上那种事情了……」</p><p>对于惠惠这番忏悔般的独白——</p><p>「这件事是谁告诉你的？」</p><p>我心想反正一定是那个人的同时，这么打断了她。</p><p>或许是因为就算有挨骂的心理准备，也没想到我会问情报来源吧，惠惠的红色视线在黑暗中游移了一阵之后……</p><p>「是我刚才提到的那个，我的盗贼团里的盗贼。其实，和真也认识那个人就是了……」</p><p>说着，她稍微笑了一下。</p><p>我一边叹气一边下床，看向窗户。</p><p>大概是因为外面很冷，要我快点察觉到而故意发出轻微的敌意吧。</p><p>我的感应敌人技能从刚才开始就告诉我，有人在窗外等候。</p><p>正当惠惠因为我突然下了床并走向窗户，而对我露出一脸疑惑的表情时。</p><p>我一把拉开挂在窗边的窗帘，就看见——</p><p>「你说的盗贼，就是这个人对吧？」</p><p>简直就像是早就料到事情会变成这样似的。</p><p>窗外的那个人不是艾莉丝女神，也不是冒牌盗贼团的基层人员克莉丝，而是用面罩遮住口部的悬赏要犯的头目，向我们挥了挥手。</p><h3 id="_7-4" tabindex="-1"><a class="header-anchor" href="#_7-4"><span>7</span></a></h3><p>「呼～～真是的，你也发现得太慢了吧，助手老弟。天气已经开始变冷了耶。」</p><p>我一打开窗户，克莉丝便轻身钻了进来。</p><p>「不对喔，问题是出在头目没有指定时间吧。应该说，我们也差不多该约在外面会合才对了吧。」</p><p>而我就像平常一样如此回应她。</p><p>惠惠则是整个人僵在原地，看着我们两个这样的互动。</p><p>「……呐，助手老弟，惠惠都一动也不动耶。」</p><p>「是因为头目的登场方式太奇葩了吧？而且有可疑人物从窗户跑进来的话，正常人都会吓到吧。」</p><p>我们两个明知道惠惠僵住不动的理由，却还是一边说着这种不着边际的话，还一边笑得很贼。</p><p>「……歉。」</p><p>「嗯？」</p><p>「惠惠，你说什么？抱歉，我听不太到。」</p><p>原本在嘴里嘟哝的惠惠，突然跪了下去。</p><p>「非常抱歉！我自称是你的支持者，却没发现你的真面目！」</p><p>「喂喂，你太大声了，外面的人也会听见啦！」</p><p>「惠惠，没关系没关系！这不是什么需要道歉的事情，别跪我啦——！」</p><p>正当我们两个惊慌失措的时候，惠惠抬起头来，一直盯着我看。</p><p>「应该说，就是……既然你从刚才开始就一直叫他助手老弟，就代表……」</p><p>她红色的眼睛当中充满着兴奋与期待，让我觉得不应该在这个时候装傻或是蒙混过去。</p><p>我以眼神寻求克莉丝的同意，她便像是想说当然没问题似的闭起一只眼睛，竖起拇指。</p><p>她明知道惠惠在里面还跑进来，就表示她想公开真面目了吧。</p><p>既然如此，我也不需要继续隐瞒下去了。</p><p>我走向收着从事盗贼工作的时候用的衣服和面具的衣柜——</p><p>「惠惠，你可要仔细看好了。你在我面前大谈有多喜欢的那个人，就要展现出他的真面目了喔！」</p><p>克莉丝站在我打开的衣橱旁边，露出一脸爱恶作剧的孩童般的笑容，如此调侃惠惠。</p><p>「是啊，我会仔细看的。因为我想知道我最喜欢的人之前做过些什么。」</p><p>而惠惠对此以正中直球加以反击，反而让克莉丝面红耳赤了起来。</p><p>「头目，这个家伙随时都是全力以赴，所以调侃她也没用啦。我也被她这样反击过好几次了。」</p><p>「抱抱抱、抱歉喔，不知道怎么搞的对我造成的伤害也不小耶。这种酸酸甜甜的心情是什么啊，虽然令人害臊却又想要多听一点，同时又让人很想遮脸的感觉到底是……！」</p><p>见我们轻声对彼此交头接耳，惠惠露出有点难过的表情。</p><p>「那个，你们两个的关系相当密切吗？是从什么时候变成这种关系的啊？」</p><p>「惠惠，不是啦！我们两个开始一起当盗贼也是最近的事情，我之前也说过了啊，助手老弟在我心目中什么都不是！我只把他当成普通朋友，对他并没有特别的感觉！」</p><p>「等一下，你们两个当我不在场的时候都聊了些什么啊？为什么我要在不知情的状况下被甩掉啊？」</p><p>说真的，她们到底趁我不在的时候聊过什么啊？</p><p>今后还是尽量减少性骚扰行为和发言，以免她们背地里说我的坏话好了。</p><p>就在一边这样想，一边换衣服的时候，我忽然感觉到背后的视线。</p><p>「你们刚才是说过要仔细看好我的真面目没错，不过再怎么样，这一幕还是别看比较好吧……」</p><p>一脸认真地看着我的两人连忙将视线从把手放在裤子上的我身上移开——</p><p>「——今晚有很漂亮的满月呢！助手老弟有夜视能力所以无所谓，不过对我而言，这种日子才是最适合工作的时候。」</p><p>我们只凭借着月光，在阿克塞尔之中賓士。</p><p>惠惠现在穿的不是常穿的长袍，而是不同于平常的轻便服装。</p><p>根据克莉丝表示，她甚至还特地准备了面罩，就只为了这个。</p><p>「那个，我真的可以跟去吗？我又没有盗贼技能，不会拖累你们吗？」</p><p>我对跟在我们身后，从刚才开始就变得比较含蓄又乖巧的惠惠表示：</p><p>「因为头目说过，这次除了我之外还叫了其他帮手嘛。而且，你记好了，戴上这个面具之后，我就不是平常的我了。现在的我不是干练的冒险者佐藤和真，而是悬有重赏的面具盗贼团的头目。只限于满月的晚上，我有时候会觉得情绪非常高昂，不会输给任何人。然后，今晚我当然也是状况绝佳！」</p><p>「呐，助手老弟，你真的不是恶魔或魔族吧？只是普通人类对吧？还有，这是银发盗贼团，而且头目是我喔。」</p><p>把依然失礼的头目的这番话当成耳边风，我尽管有点介意一直钉在我背上的视线，还是不断赶路。</p><p>之所以这么做，是因为一旦到了明天，某个狂暴的大贵族就会为了帮惠惠报仇而展开行动了。</p><p>那个家伙原本就已经够顽固，在看见她认真起来的眼神时，我就放弃阻止她了。</p><p>既然如此，就只能在天亮之前抢走可能在卡莲家里的那个召唤怪物的神器了。</p><p>只要能偷出那个神器，把神器当成证据暂时交给达克妮丝，证明卡莲召唤怪物，使阿克塞尔面临危机，就可以正式以法律制裁她了。</p><p>仔细想想，都已经有被送到艾莉丝身边的我这个被害人了，要是真的找到那个神器，我也没什么好抱怨的了。</p><p>……</p><p>「呐，我从刚才开始就一直感觉到你的视线耶。」</p><p>「啊！不不、不好意思，因为你太适合戴面具了，我忍不住就……」</p><p>跟在后面的惠惠好像一直盯着我看。</p><p>「先别说那些了，快到城镇的正门了，惠惠也戴上面罩吧。今天你也是银发盗贼团的一员喔。」</p><p>听克莉丝这么说，兴奋到眼睛发出红光的的惠惠以面罩遮住口部。</p><p>「……糟了，头目，这家伙的红眼害得面罩几乎发挥不了作用。」</p><p>「怎么办啊，助手老弟？这个我也没想到。」</p><p>光是遮住口部的话，红魔族的特征还是完全显露在外。</p><p>这个镇上只有两个红魔族，再怎么说这样也不可能不穿帮。</p><p>见惠惠沮丧得那么明显，我就拿下面具递给她。</p><p>「没办法，今晚你就戴我的面具吧。我用你的面罩。今晚面具盗贼团的头目给你当。」</p><p>「呐，助手老弟，我们应该来统一一下盗贼团的名称才对，而且头目是我喔！」</p><p>从我手上接过面具的惠惠露出幸福无比的笑容。</p><p>「我们被悬赏的时候你明明就说过我们还是叫面具盗贼团好了，头目也给我当的，不是吗？」</p><p>「最近风波开始平息了嘛，这原本就是我成立的盗贼团，应该用我的注册商标银发来当名称才可以。」</p><p>我一边戴上惠惠给我的面罩，一边和克莉丝如此对话时，惠惠表示：</p><p>「我对命名很有自信喔。不然由我来取团名如何？」</p><p>「「那可不行。」」</p><p>我们无意间异口同声。</p><p>——使用潜伏技能的我们轻松突破了阿克塞尔的正门，在月光之下朝森林前进。</p><p>「和真，我觉得戴上这个面具的感觉非常自然。即使说这是最适合红魔族的配件也不为过。这个可以给我吗？」</p><p>「最近我也开始喜欢上那个了所以不可以给你。巴尼尔的店里有卖类似款，你去那里买吧。不过那个好像很热卖，所以很难买到就是了。」</p><p>听了我们的对话，克莉丝也兴致勃勃地问道：</p><p>「巴尼尔先生是那个老是戴着面具的人吗？我只有从远方稍微看过他，听说他会赶跑捣乱垃圾场的乌鸦所以被称为乌鸦杀手，好像是个很老实的人呢。」</p><p>……这个人在说什么啊？</p><p>这个世界的女神眼睛都瞎了吗？</p><p>不对，我记得她好像说过自己在下凡的时候用的是暂时的身体。所以是这样才没有发现巴尼尔的真面目吗？</p><p>虽然感觉好像会很危险，但我还是想让她见见维兹和巴尼尔。</p><p>「——哦，看得到那间宅邸了耶。好了，惠惠，今晚要为我们上次的行动雪耻。其实那个人的态度也让我有点火大。」</p><p>说着，克莉丝盯着浮现在森林之中的宅邸，对眼睛闪着红光的惠惠露出笑容。</p><p>「好了，咱们上吧！」</p><h3 id="_8-3" tabindex="-1"><a class="header-anchor" href="#_8-3"><span>8</span></a></h3><p>或许是为了防范怪物，宅邸的正门理所当然的有人看守。</p><p>首先为了排除他们，我发动了潜伏技能，从暗处悄悄接近他们。</p><p>看守有两人。</p><p>绕到背后去，捂住他们的嘴，用「Drain Touch」就可以解决他们了吧。</p><p>……这时，在悄悄接近的我所在之处的另外一边，也就是看守的左手边，响起了一个沙沙声。</p><p>原本面对正面的两名看守转头看了过去——</p><p>我没有错过这个机会，一口气熘到他们背后，以左右手分别堵住两人的嘴，发动了「Drain Touch」。</p><p>看见两人一声不响地瘫倒在地之后，躲在草木后面的克莉丝和惠惠也来到我这边。</p><p>「那个，你们两位的表现都相当精彩。应该说，和真原来这么厉害啊。」</p><p>平常好像觉得我不太厉害的惠惠对我们投以尊敬的眼神。</p><p>刚才那个吸引了看守注意的声音，好像是克莉丝丢小石头发出来的。</p><p>「我们可是一路突破到王城最深处，悬有重赏的银发盗贼团喔！这点小事太轻松了。」</p><p>气定神闲地这么说的克莉丝扬起嘴角。</p><p>「不久之前还在冒牌盗贼团当基层盗贼的人在说什么啊。是说，为什么头目在我不注意的时候就会立刻碰上那种搞笑的状况啊？」</p><p>「我才想问好吗？我的运气明明也不比你差啊。」</p><p>被克莉丝这么一说我才发现，其实我也是个明明运气很好，却老是被卷进奇妙的麻烦之中的人。</p><p>在我这么想的时候，我们在宅邸的围墙内绕到后门，潜入屋子里面之后。</p><p>「……该说我们的运气果然很好吗，头目？」</p><p>「以这个状况来说，与其说是运气好，我更有种抽到下下签的感觉呢。」</p><p>「你们两位果然是历练丰富，在这种时候还这么冷静。」</p><p>我们面面相觑，思考该如何处理突然撞见的这个状况。</p><p>「我不知道你们是什么人，又是打哪来的，不过别闲聊了，快点救我！」</p><p>出现在我们眼前的，是被一只和人一样大，长得像章鱼的怪物缠住的卡莲。</p><p>「——得、得救了。我差点就要失去身为贵族千金最重要的东西了……」</p><p>我和克莉丝两个人砍了过去，救助卡莲脱离章鱼型怪物后，才发现自己身在牢笼里。</p><p>房间的另外一边有一扇门，但房间中央还有一道将房间一分为二的铁栅栏。</p><p>照理来说，这应该是在铁栅栏的另外一边安全召唤怪物的系统吧。</p><p>「这间宅邸的后门为什么通到牢房里面来啊？」</p><p>刚才还被怪物紧紧勒住的卡莲不停咳嗽，随后才站了起来，回答我的疑问。</p><p>「那里不是什么后门。是用来将没中奖的怪物放到外面去的排放口。」</p><p>卡莲事到如今才以警戒的眼神看着我们，手里还拿着某种不明物体，对着我们举起来，吓唬我们。</p><p>「她刚才说了没中奖的怪物耶，头目。这个家伙果然有罪。」</p><p>「等一下，助手老弟，我们还没看到最重要的神器耶。」</p><p>面对毫无紧张感的我们，卡莲显得有些焦躁，放声大喊：</p><p>「你们到底是什么人啊！应该是知道这里是什么地方才闯进来的吧？」</p><p>「这里是恶名昭彰的朵内利家对吧？我们今晚是来还你人情的。」</p><p>听克莉丝气定神闲地这么说。</p><p>「原来如此。我从事的是贷款的工作，会怨恨我的人早已多到数不清了。你们也是其中之一对吧？不过你们的运气太差了，等着当我的新商品的实验对象吧！」</p><p>卡莲一边这么说，一边将她手上的不明物体高高举起——！</p><p>「「『Steal』。」」</p><p>然后我和克莉丝同时施展了「Steal」，抢走那个不明物体。</p><p>「啥！」</p><p>没有理会惊叫出声的卡莲，我们确认了一下战利品。</p><p>「总之先抢过来了，不过这个东西是什么啊？」</p><p>「啊，可恶，我输了！我偷到的又是内裤！」</p><p>卡莲原本打算使用的道具在克莉丝手上。</p><p>进到我手中的则是白色内裤。</p><p>「为什么和真的『Steal』总是特别着重在性骚扰上啊？……是说，那个东西借我看一下。我记得好像在哪里看过……不是啦，我才不是要看内裤，我说的是那颗石头啦！」</p><p>克莉丝将手上的石头交给惠惠，我烦恼着该怎么处理这条内裤，而压着裙摆的卡莲则是狠狠瞪着这样的我。在如此奇妙的状况之下——</p><p>「来、来人啊！有入侵者，有奸细啊！」</p><p>卡莲好像终于想到要叫人来了。</p><p>「这是以怪物的蛋为原料加工而成的违禁魔道具。这个东西能够召唤怪物，不过也仅止于此。既无法使唤怪物，召唤出来的怪物也是随机决定，是只有危险性的道具。」</p><p>识破了石头是什么来历的惠惠如此指出，但卡莲用鼻子哼笑。</p><p>「只有危险性的道具？你错了，那个东西可以生出钱来，是非常了不起的魔道具。随机召唤出来的怪物当中，有出现大葱鸭和黄金蚁等大奖的可能性。目前为止我抽到最大的奖是未成年的龙。我靠那个就把之前投注在其中的资金一举赚回来了。」</p><p>在众人奔向这里的脚步声当中，卡莲拉开了和我们之间的距离，从架子上拿了一颗新的石头。</p><p>也就是说，这个家伙在这个用铁栅栏隔开的房间里召唤怪物，中了大奖就卖掉换钱，出现卖不了钱的怪物就随便野放是吧。</p><p>然后，因为那些被野放的怪物的传闻开始在镇上传开了，她为了减少怪物的数量才会委托人称阿克塞尔最强的我来解决。</p><p>「头目，这个家伙只是个不入流的小咖耶，她把自己做的坏事全都招出来了。」</p><p>「助手老弟，那种事情只可以在心里想，不可以说出来啦。不过，那个人对我来说才叫作没中奖吧。我原本还以为她用的是神器……」</p><p>「你们两个说的话都被人家听到了啦。那个人已经满脸通红了。」</p><p>见我们依然毫无紧张感，卡莲顿时暴怒，对着我们举起石头。</p><p>「瞧你们在这个状况下还那么气定神闲的，等着到阴间去后悔吧！警卫们不久之后也会赶到——」</p><p>「「『Steal』。」」</p><p>在卡莲说到最后之前，我们的「Steal」再次发威。</p><p>「我又赢了。」</p><p>「不对，等一下喔。对我而言，偷到这个东西比偷到那个石头还要开心，如果要说谁输谁赢的话，应该说是我赢也可以吧？」</p><p>「这个男人烂透了，居然当着我们的面大大方方地说出那种话。」</p><p>我手上的是卡莲的胸罩。</p><p>克莉丝手上的是那种石头。</p><p>「你们是怎样！你们两个到底是怎样啊！」</p><p>不只压着裙摆还压着胸部的卡莲泪眼汪汪的瞪着我们。</p><p>就在这个时候。</p><p>「大小姐，怎么了！」</p><p>「有入侵者！快抓住这些人！」</p><p>见警卫们赶到，卡莲一副胜券在握的样子，如此命令了他们。</p><p>——命令了在铁栅栏的另外一边的他们。</p><p>「助手老弟，这个人有点废耶。」</p><p>「一开始就应该知道这个人很废了吧，她可是拿违禁品当手游的转蛋来玩的人耶。」</p><p>「手游的转蛋是什么意思啊？算了，先不问这个了，真不知道这个人为什么在铁栅栏的这一边召唤出怪物来呢？不过，我猜她是在整理架子还是怎样的时候，不小心把那种石头碰到地上，无意间召唤出怪物来了，大概是类似这样的状况吧。」</p><p>听见我们这么说的卡莲脸都红到耳根子去了，这时克莉丝点头表示：</p><p>「虽然我们才刚来，不过应该可以走了吧？这个我们就当成违法召唤怪物的证据带走喽。我们会帮你送到达斯堤尼斯家去的。」</p><p>听见这句话，卡莲的脸色瞬间刷白。</p><p>「等、等一下！你们别想离开，或许外表看不出来，但我也是等级很高的贵族，争取时间等警卫们绕到后门去这点小事，我还——」</p><p>「『Stea』……」</p><p>「不可以啦助手老弟，我觉得你不应该再出招了！」</p><p>正当我准备对话还没说完的卡莲施展「Steal」的时候，克莉丝连忙打断了我。</p><p>「有什么关系嘛，就在这个女人的部下面前把她扒光吧。」</p><p>惠惠毫不留情的这么说，卡莲这才理解到身上只剩下一件洋装的自己差点被怎样，瘫坐到地上，一边颤抖一边后退。</p><p>气也算是有点消了，证据也到手了。</p><p>正如克莉斯所说，差不多是该撤退的时候了。</p><p>或许是明显察觉到我们这样的想法，瘫坐在地上的卡莲开口说：</p><p>「仔细一看，我认得那个面具。你们就是街头巷尾盛传的面具盗贼团吧！不要以为找到这种程度的违禁品我就会被抄家。你们觉悟吧，等着看挂在你们身上的奖金会变得多高——我乱讲的，对不起！」</p><p>然后就看见我对她伸出手，于是一边后退，一边放声尖叫。</p><h2 id="终章" tabindex="-1"><a class="header-anchor" href="#终章"><span>终章</span></a></h2>`,398),e(m,{src:`/images/C1/06.avif`,alt:`章节标题`,collapsed:``,width:`850`,height:`1257`}),l[26]||=s(`<p>隔天早上。</p><p>「哈哈哈哈哈哈哈！哈哈哈哈哈哈哈哈！该死的朵内利，我要用这个好好教训你！干得好啊，和真，你立大功了！哈哈哈哈哈哈哈哈哈哈！」</p><p>达克妮丝胜而骄矜的笑声在一如往常的大厅里回响。</p><p>取得召唤怪物的证物之后，我将那个东西交给达克妮丝，也大略说明了一下昨天晚上发生了什么事。</p><p>她因为我们又去偷东西而责怪了我一下，不过最后的结果就像这样。</p><p>「早安……你们是怎么了？今天都起得这么早。」</p><p>穿着睡衣的阿库娅抱着一包东西，来到楼下。</p><p>「不是起得早而是熬夜了。我接下来要去睡觉，到傍晚之前都不要叫醒我。」</p><p>「你又打电动了是吧？真是的，尼特就是这样，真是的。」</p><p>对于昨晚的骚动毫不知情，喝了酒就睡到现在的这个家伙没资格说我啦。</p><p>这时，阿库娅在桌子上摊开布包，让惠惠对里面的东西产生了兴趣。</p><p>「阿库娅，那是什么啊？看起来好像是石头耶。」</p><p>「不愧是惠惠，红魔族鉴定物品的眼光果然不同凡响。」</p><p>那个家伙的眼睛可是瞎到在昨天之前都没发现我的真面目喔。</p><p>在我一边这么想，一边啜饮晨间咖啡时。</p><p>「这个啊，是我收藏的奇石系列。在河边啊、池塘啊、湖边啊，都可以找到很不错的石头喔。我偶尔会像这样细心打磨，让它们亮晶晶的……你要一个吗？」</p><p>「不需要。」</p><p>……我们那么辛苦，这个家伙却这么悠哉是怎样啊？</p><p>虽然解决了召唤怪物骚动，但是失踪的神器到头来还是不在那间宅邸里面，所以克莉丝又得去追查神器的下落了。</p><p>真希望这个只会做多余事情的家伙可以好好学学那个比较认真的女神。</p><p>「这么说来，阿库娅从前一阵子就经常外出，离开城镇，那到底是在做什么啊？我们一不注意惠惠，结果等我们发现的时候事情已经很严重了。所以我姑且还是想问一下你在做什么……」</p><p>「等一下，达克妮丝，不要把我当成问题儿童好吗！那是冒险者公会的人拜托我去打工啦。你也知道，我有超强的净化能力对吧？是公会拜托我，希望我运用那种力量净化多头水蛇之前住的那座湖泊和周边的环境，所以我很努力喔！」</p><p>正当我一边放空望着这种一如往常的景象，一边啜饮咖啡时，惠惠把一样东西抱在胸前，站到我身旁来。</p><p>她好像有话想说，但似乎还在犹豫该不该说的样子。</p><p>「那、那还真是抱歉啊，阿库娅。是我不对。」</p><p>「你真的觉得是你不对吗？是的话就从我的奇石收藏当中买走一个吧。净化的打工已经结束了，我最近很缺钱。」</p><p>没有理会那两个长舌的家伙，我开口调侃惠惠。</p><p>「你有什么话想说吗？我知道了——你发现了我的真面目之后，想要我的签名了是吧？还是想要跟我握手啊？」</p><p>「都不需要。」</p><p>惠惠斩钉截铁地如此秒答之后，眼神游移了一阵。</p><p>「就是……谢谢你。你那么做等于是为我们报了仇。」</p>`,31),e(m,{src:`/images/C1/25.avif`,alt:`插图`,width:`850`,height:`1257`}),l[27]||=s(`<p>原来是想说这个啊。</p><p>「我又不是去帮你们报仇的。再说，我等于是间接被那个女人杀掉的，所以心情也有点舒畅。更何况，你们是我们的下游组织对吧？既然如此，我帮基层人员报仇也是理所当然的吧。」</p><p>我耍帅地笑了一声之后这么说，惠惠也露出腼腆的微笑。</p><p>「那么，今后我应该称呼和真为头目吗？」</p><p>「嗯，可以啊。毕竟悬赏的名义是面具盗贼团，所以我可以算是实质上的头目吧……啊，别告诉克莉丝我说过这种话喔。不然她又要骂我了。」</p><p>见我有点慌张，惠惠开心地咯咯笑了起来。</p><p>「可以啊，我帮你保密就是了。不过相对的……」</p><p>她摆在胸前抱着东西的手用力握了一下。</p><p>「偶一为之就行了，我可以再跟你一起行动吗？」</p><p>说着，她将一直抱在胸前的东西递给了我，那是我的面具。</p><h2 id="特典-vs" tabindex="-1"><a class="header-anchor" href="#特典-vs"><span>特典 VS！</span></a></h2><p>在小朋友们的注视之下，惠惠将披风用力一掀，说出报名台词。</p><p>「吾乃惠惠！身为阿克塞尔首屈一指的魔法师，乃善使爆裂魔法之人！」</p><p>而站在惠惠对面的……</p><p>「吾乃芸芸！身为红魔族首屈一指的魔法师……呀——！等等，我的报名台词才说到一半而已耶！住手，快住手——！」</p><p>则是在说出台词的同时遭到袭击而放声惨叫的芸芸。</p><p>在阿克塞尔的公园里，两名红魔族一大早就扭打在一起，滚倒在地上。</p><p>「……总之，第一场就算惠惠赢了可以吗？」</p><p>「我不承认这种方式！规则是要等到台词说完才……等等，惠惠，我知道了！我认输就是了，不要拉我的头发嘛！」</p><p>被惠惠压在身上的芸芸哭丧著脸认输了。</p><p>——事情的开端，是来豪宅过夜的芸芸不经意说出的一句话。</p><p>「我确实是败场比较多没错，但是我们的比赛内容多半都是惠惠决定的。而且，惠惠从来没有公平地和我一决胜负过。」</p><p>听了惠惠和芸芸的过去之后，我没有多想就不小心这么问了：</p><p>所以你们两个到底是谁比较强啊？ ——这样。</p><p>「——我确实是把红魔族首屈一指的称号让给你了没错，但是你在我眼前大大方方说出来，我还是会觉得很火大！」</p><p>「不要因为那种理由就不遵守规则跑来袭击我好吗！我知道了啦！第一场算我输了就是了啦！」</p><p>推倒芸芸骑在她身上的惠惠幼稚地大吵大闹了一番。</p><p>「那就算惠惠赢了……接下来是由芸芸决定要比什么对吧？」</p><p>顺手推舟变成见证人的我莫名觉得有点丢脸，决定尽快结束这场比赛。</p><p>因为受到红魔族浮夸的报名台词和表现手法的影响，附近的小朋友们都聚集了过来，注视著我们。</p><p>其中已经有些小朋友还开始耳濡目染，模仿起红魔族的报名台词和招牌姿势了。</p><p>在这样的小朋友们的注视之下，眼中微微泛泪的芸芸拍了拍衣服上的尘土，从放在地上的包包里面拿出某样东西。</p><p>「接下来……用这个棋类游戏来一决胜负！」</p><p>那时我已经相当熟悉的那个惠惠拿手的，类似西洋棋的对战游戏。</p><p>「我才不要呢，没朋友的芸芸应该一年到头都一个人在玩那个，持续不断地锻炼吧。我知道你已经有达人级的实力了。」</p><p>「不需要提什么没有朋友、什么一年到头那些多余的话吧！你是怎样，知道会输就不肯接受挑战了吗？无论比什么，红魔族都应该欣然接受才对吧？」</p><p>「唔唔唔唔唔……」</p><p>见惠惠咬牙切齿，不住低吟，芸芸带著无所畏惧的笑容，摆好了棋子。</p><p>——以结果而言是芸芸赢了，但对决是在非常低调的状态下结束。</p><p>「好了，这样一来就是一比一了！再来呢，最后一场要比什么？拿出红魔族风范来场魔法对决吗？如果是这样的话就是比谁打倒的怪物比较多了…… 」</p><p>平常一个人玩的时间似乎并没有白费，对上惠惠还获得了压倒性胜利的芸芸，现在显得有点亢奋。</p><p>这时，惠惠忽然看向我。</p><p>「最后一场可以由见证人和真来决定要比什么吗？无论比什么我都不会有意见，以此一决高下。」</p><p>「由和真先生决定吗？也好，这样我也可以接受……」</p><p>话不是这么说的吧，我已经想回家了……</p><p>「好麻烦喔，不然就猜拳吧……」</p><p>「你把红魔族神圣的对决当成什么了！」</p><p>「请你认真点决定好吗！」</p><p>打算随便决定的我被她们两个痛骂。</p><p>这两个家伙是怎样，小心我叫你们来个性感度对决，看谁能够让我按捺不住喔。</p><p>正当我烦恼著要不要找她们麻烦，叫她们比这个的时候。</p><p>不知道是正好在巡逻还是怎样，两名警官来到了公园这边来。</p><p>那两位警官找上了正在围观我们的小朋友们，好像在打听什么。</p><p>……我有种不祥的预感。</p><p>「那我要决定比赛内容了。」</p><p>或许是同样感受到不祥的预感了，惠惠和芸芸两个人也一直盯著警官看。</p><p>「要比什么呢？应该说，我觉得今天可以就此解散也无所谓啦……」</p><p>「我、我也觉得留待日后再分高下也可以……」</p><p>相较于感到害怕的两人，我一点一点远离接近我们的警官。</p><p>「可以耽误你们一点时间吗？有附近的居民报案，说有一群人在教小朋友玩一些奇怪的游戏……」</p><p>「比赛内容是在这个公园留到最后的人获胜！那我就先回去了！」</p><p>「我接受这个挑战！唔，不愧是芸芸，居然能够打败我……！」</p><p>「吶，我还没说要接受挑战，也还没赢！明明是这样，为什么惠惠要一脸不甘心地逃走啊！啊啊，警察先生，不是这样的，我没有做任何坏事……！」</p><p>——获胜的是芸芸。</p><h2 id="特典-阿克塞尔第一的" tabindex="-1"><a class="header-anchor" href="#特典-阿克塞尔第一的"><span>特典 阿克塞尔第一的……</span></a></h2><p>睡到下午的我一边甩著因为睡太久而昏昏沉沉的头，一边来到楼下的时候。</p><p>「堕落不已的狗屎尼特啊！尽管死在吾之红拳之下，来世好好走上正途吧！」</p><p>一手遮著右眼摆出中二姿势的惠惠，用力指著我这么说。</p><p>「……虽然听不太懂，不过你想打架的话就等著输给我吧。」</p><p>「痛痛痛痛痛！请住手，我道歉就是了，请你住手！」</p><p>我握住她伸出来指著我的食指打算反折，吓得惠惠连忙哀求。</p><p>「所以说，你刚才那招到底是怎样？如果你只是毫无意义痛骂了我一顿的话，我就用『Drain Touch』吸你的魔力，让你无法一日一爆裂喔。」</p><p>「别别别别、别这样！你、你怎么会想到这么恐怖的事情啊，这种想法比巴尼尔还更像个恶魔吧！」</p><p>不过就是一天没有办发用魔法而已，说成这样未免也太夸张了，但是对惠惠而言，这似乎比任何威胁都还要有效。</p><p>我放开她的手指之后，惠惠往后退了一大步，似乎对我有所防备。</p><p>「其实是这样的，我们几个住在阿克塞尔附近的红魔族，偶尔会聚在一起聊聊各种事情。」</p><p>「……我还以为会离开故乡的红魔族就只有你和芸芸而已，原来不是这么回事啊。你们那种爱制造麻烦的种族，可以尽量不要离开那个名为红魔之里的隔离设施吗？」</p><p>「你说谁是制造麻烦的种族啊！无论是佣兵团还是骑士团，只要去面试就会立刻录取，去冒险者公会也不愁找不到队友，红魔族就是这么厉害好吗！」</p><p>原则上红魔族好像是最强的魔法师集团，不过看著这个家伙就会让人很想怀疑这到底是不是真的。</p><p>「所以呢？红魔族的聚会和你辱骂我到底有什么关系？」</p><p>「其实是这样的。我们决定在下次聚会的时候，选出住在这一带的红魔族当中，招牌台词最帅气的是谁。」</p><p>……红魔族那群人真的是最强的魔法师集团吗？</p><p>我一脸傻眼的看著惠惠，她发现了便说：</p><p>「你、你那是什么眼神啊！对红魔族而言，招牌台词是非常重要的东西，真要说的话，就像是辞世或是生涯的座右铭一样。」</p><p>「你打算把刚才对我说的那些，什么堕落不已的狗屎尼特之类的台词，当成生涯的座右铭吗？」</p><p>「不是啦，那只是因为看见刚睡醒的和真一脸堕落不已又没出息的表情，所以把心里想到的台词说出来而已。」</p><p>听惠惠这么说，我为了用「Drain Touch」对付她，对她施展了铁爪功。</p><p>「等等等等等一下！我道歉就是了，千万不要吸我的魔力！」</p><p>——一个星期之后。</p><p>「……吶，为什么我还得陪你来啊？」</p><p>不知为何，我被带来参观他们红魔族的招牌台词对决。</p><p>「有什么关系嘛，反正和真那么闲，你昨天不是还拿著镊子把阿克娅种的仙人掌盆栽的刺一根一根拔掉，白白浪费了一整天吗？我今天会让你见识我帅气的一面。阿克塞尔第一的招牌台词高手这个称号非我莫属。」</p><p>「我那么做有我的意义好吗。不仅可以打发时间，更可以看见哭丧著脸的阿克娅，谁教她要擅自喝掉我珍藏的高级尼禄依德。」</p><p>「大概是因为阿克娅后来施展了好几次『Heal』的关系吧，我今天早上看到的时候，那株仙人掌已经长到两倍大了喔。完全成长的仙人掌很聪明，今后要是你不小心随便靠近的话可能会被喷刺攻击喔。」</p><p>真的假的。</p><p>正当我对于这个世界的植物拥有智能的不合理事实感到愤慨不已的时候——</p><p>「咦，和真先生？惠、惠惠，你为什么连和真先生都带来了啊！」</p><p>对我这么说的，是在这个城镇也算是比较有常识的少女。</p><p>这里大概就是他们的集合地点吧。</p><p>在被好几名红魔族擅自占据的阿克塞尔的公园里，芸芸发现了我们两个，便来找我们搭话。</p><p>「这个男人好像不太了解招牌台词对于红魔族的重要性以及存在意义，所以我硬是把他拖过来了。」</p><p>「别这样好吗，太丢脸了！我也是完全无法了解也不想了解啊，不要连和真先生这种普通人都牵扯进来好吗！」</p><p>或许是察觉到我们这边的骚动，红魔族们看到第一次见面的我开始蠢蠢欲动，似乎也想说出自己的报名台词。</p><p>其中还有人交头接耳地讨论这「牵扯进来？他想临时参赛吗？」什么的。</p><p>「真是的，都是芸芸要说得那么大声啦。现在不知为何，搞得好像连和真都不得不参加了耶。」</p><p>「啊啊啊啊对不起对不起！和真先生，都是我不好，对不起！」</p><p>一脸快要哭出来的芸芸向我道歉，但在看见她身后那些红魔族脸上的期待表情，害我冒出想要回应他们的念头。</p><p>招牌台词…………帅气的招牌台词啊。</p><p>「——什么，所有人都一致赞成，临时参加的佐藤和真先生的招牌台词最帅气！」</p><p>「为什么变成和真的最帅气啊！太奇怪了，这样太奇怪了！你怎么有办法接连说出那么帅气的台词啊！」</p><p>「我国病入膏肓的程度可不是你们比得上的。有过去的伟人们留下的那些中二病到不行的台词，我怎么可能会输呢。」</p><p>「再一次！请你再说一次刚才的台词吧！」</p><p>阿克塞尔第一的称号变成我的了。</p><h2 id="特典-『盗贼少女在努力』" tabindex="-1"><a class="header-anchor" href="#特典-『盗贼少女在努力』"><span>特典 『盗贼少女在努力』</span></a></h2><p>在街上散步的我碰到了罕见的组合。</p><p>「阿库西斯教！信奉阿库西斯教吧！」</p><p>那是大声安利阿库西斯教的塞西莉。</p><p>以及……</p><p>「阿库西斯教……请信奉阿库西斯教吧……」</p><p>疑似被塞西莉强行拉来的，抱着大量阿库西斯教入教申请书的克里斯。她露出燃尽了似的表情将申请书发给行人。</p><p>「你们到底在干什么呢？」</p><p>我对那两人搭话。克里斯像是被发现了黑历史一样浑身打了个激灵。</p><p>「啊，惠惠小姐！这当然是在安利啊！我们现在人手不足，麻烦你也来帮忙吧？报酬是我请你吃午饭！」</p><p>「帮一下没问题。我只是想问为啥连厄里斯教徒都来做这种事了」</p><p>克里斯一脸尴尬，但还是老实地把入教申请书塞给路人……</p><p>「因为闲的没事，我去基地玩耍。结果听到塞西莉小姐说『之前女神厄里斯随性地降临在这个城市，搞得阿库西斯教徒更没容身之处了，这位女神是不是有些太不顾后果了？』。我这么一想，也觉得阿库西斯教徒有些可怜，所以仅限今天来帮他们的忙……」</p><p>这人为什么这么容易任人摆布啊。</p><p>「阿库西斯教徒的话本身就是有问题的你别听他们瞎扯啊。不过是女神厄里斯自己瞎下凡制造骚乱而已，又不需要身为信徒的你去为此买单」</p><p>「………………我，我今天还是努力帮帮阿库西斯教徒吧」</p><p>虽然不知道原因，但她本人觉得好就行。</p><p>「那，我要怎么帮忙呢？难不成是要把入教申请书塞到每家每户的邮筒里？」</p><p>「不，难得惠惠小姐来了，我们就来久违地来一套那个吧！」</p><p>塞西莉露出了坏笑。</p><p>——在阿克塞尔的大道上。</p><p>我在来来往往的行人面前大声呼救。</p><p>「救命啊！来人救救我吧！我养的宠物猫被路过的厄里斯教徒袭击，已经奄奄一息了！」</p><p>我双手按住精神抖擞地在我脚边乱转的逗之助，防止它乱动。</p><p>然后，因绝望而双眼无神的克里斯说</p><p>「厄，厄里斯教徒的直觉告诉我，这黑猫是邪恶的化身。我只是以女神厄里斯的名义对它进行制裁，我不会道歉的。要是想求救，你可以去找找厄里斯教会啊」</p><p>在克里斯做作地说完台词后，塞西莉拨开围观群众跳出来。</p><p>「到此为止了！邪恶的厄里斯教徒！这种迫害柔弱的少女的宠物猫，并企图逼她去厄里斯教会疗伤榨取高额回报的恶行！就算是警察叔叔能容许，阿库娅大人和我也不会容许的！」</p><p>围观群众对我们的小剧场议论纷纷。</p><p>「那个不是和真先生家的惠惠么，这又是什么新玩法」</p><p>「连克里斯小姐都掺和进来了，我还以为她是个正常人呢……」</p><p>「喂，别和她们对上视线，会被卷进不好的事里……」</p><p>他们似乎已经忍不住了。</p><p>「真是困扰了。惠惠小姐和克里斯小姐的知名度太高，这招行不通了！这下我这美人司祭使用奇迹的复活魔法让小猫复活使因此而感动得哭出来的惠惠入教并且号召围观者纷纷入教的完美作战计划就……」</p><p>「我只说了帮忙，但我可没说我要改信你们教啊！而且恕我水平有限演不出你想要的那种效果！」</p><p>就在这时。</p><p>我察觉到背后有某个气息，一回头——</p><p>「你们在干嘛？」</p><p>那是或许是去买晚饭了的和真与达克尼斯。</p><p>两人表情复杂，对克里斯投以怜悯的视线。</p><p>「不不不不不是的达克尼斯！听我解释啊助手君！这个算是补偿蒙受女神厄里斯下凡造成的损失的阿库西斯教徒……」</p><p>达克尼斯温柔地把手放在克里斯肩膀上。她身旁的和真露出苦笑。</p><p>「克里斯……你有什么烦恼尽管说。所以，别干这种蠢事了，多依靠我一点吧……」</p><p>「那个，我也会尽我所能帮你的。所以请不要再继续减少本来就很少的『正常人』角色了」</p><p>「不是啊！你们两个听我解释啊！求你们不要用这种眼神看我！」</p><h2 id="特典-恶魔的禁书" tabindex="-1"><a class="header-anchor" href="#特典-恶魔的禁书"><span>特典 恶魔的禁书</span></a></h2><p>事情就发生在我到处闲晃，玩到很晚，走在回豪宅路上的时候。</p><p>「……那是怎样？」</p><p>明明都已经是这个时间了，却有人在大街通往后巷的小路排队。</p><p>而且队伍里面还有几张我很熟悉的面孔。</p><p>好奇心被激起的我排到队伍的最尾端之后问道：</p><p>「不好意思，请问这是在排什么啊？」</p><p>「常、常客先生！你怎么会在这个时间来到这种地方！」</p><p>排在队伍里的，是经常照顾我的梦模服务店的大姊姊们。</p><p>「人、人类！这种时间居然有人类出现！」</p><p>「糟糕，被人类看到了！今天的贩售会取消吗！」</p><p>正在排队的人们看见我，开始鼓噪了起来。</p><p>「没、没关系！这位是我们店里的常客，他已经知道我们是梦魔了！」</p><p>听那位大姊姊这么说，正在排队的人们才松了口气。</p><p>也就是说，这些家伙全不是人喽。</p><p>「其实是这样的。今天晚上，队伍前方那间店即将贩售非常惊人的珍贵写真集……」</p><p>非常惊人的珍贵写真集？</p><p>「我好期待啊！在决定发售之后，我就一直在等待这一天的到来……」</p><p>「我、我更是在决定发售之后，就每天都对邪神祈祷……！」</p><p>两名排在队伍最前端的男子如此对话。</p><p>仔细一看，在场的所有淫魔全都带著兴奋不已的表情在排队。</p><p>真、真的那么惊人吗……</p><p>「总之事情就是这样……常客先生，你就当作是在帮我们的忙，不要把在这里看到的事情告诉任何人，好吗？」</p><p>说完，大姊姊对我深深一鞠躬。</p><p>「我当然会保密。而且，我也要排。」</p><p>「「「咦！」」」</p><p>听我这么说，在场的恶魔全都惊叫出声。</p><p>「这、这样好吗？我不知道这样说妥不妥当，不过那可是非常惊人的东西，如果是对于这方面的事情没什么抵抗力的未成年淫魔看了，甚至会不小心少掉只数喔！」</p><p>「那我更想看了。」</p><p>「那、那个不知死活的人类到底是何方神圣啊……！」</p><p>「你不知道吗？他是我们店里的常客，而且还和巴尼尔大人有交情呢。」</p><p>在四处传出这样的交头接耳声的同时，不知为何，他们还对我投以羡慕的表情。</p><p>就在这个时候——</p><p>「好了，感谢各位贵客在深夜聚集到本店来！请进！」</p><p>宣告开门的是巴尼尔。</p><p>不，从地理位置来说，我其实隐隐约约有这种预感就是了……</p><p>淫魔们争先恐后地买下写真集，像是得到了什么宝物似地抱进怀里。</p><p>「唔，喂，快点往后翻！快快快、快翻下一页啊！」</p><p>「我我、我明白你的心情，不过先别冲动，冷冷、冷静一点！太精彩了，这未免也太精彩了……！」</p><p>或许是压抑不住浮躁的心情，似乎是合资买一本的男性淫魔们全都兴奋不已，立刻沉浸在书中。</p><p>「噗！」</p><p>「啊啊！所以我才说这对你来讲还太早了嘛，只数就这么少掉了！」</p><p>大概是因为听了男性淫魔们的讨论而受不了了，之前那个来我的豪宅时被阿克娅逮到的萝莉梦魔喷出鼻血倒下了。</p><p>有有、有那么惊人吗……！</p><p>就在我这样满心期待的时候——</p><p>「哎呀，真是太可惜了，已经全都卖完了。后面的各位客人请都带著预约券回去，静待日后再次贩售。」</p><p>在我前面几个人的地方，巴尼尔宣布了残酷的事情。</p><p>我推开一脸遗憾地收下预约券的淫魔们，上前逼问巴尼尔。</p><p>「喂，给我等一下！害我这么期待才来这套，也太过分了吧！」</p><p>「嗯？唔还想说怎么突然冒出美味的负面情感呢，原来是这个淫魔应若是的好色小鬼啊。汝怎么会在这种地方？」</p><p>「我也对那个非常惊人的珍贵写真集很有兴趣啊。喂，难道一本都没剩了吗？」</p><p>「汝又不是恶魔族却想要这本书吗？也罢，汝是重要的客户，为了避免有缺页需要交换，吾这边还留了一本……」</p><p>听见我们的对话，在我之前收下预约券的淫魔们开始鼓噪起来。</p><p>「怎、怎么这样！常客先生太奸诈了吧，至少借我看一下！」</p><p>「我、我也要！也借我看一下！」</p><p>他们这么说也无可厚非，于是我带著满怀的期待，在淫魔面前翻开写真集……！</p><p>上面的照片是一张铺满玫瑰花的床，中间摆著巴尼尔的面具。</p><p>没错，只有面具摆在床上而已。</p><p>「啊啊……！巴巴、巴尼尔大人居然一丝不挂！」</p><p>「太、太惊人了……！真不敢相信，居然连巴尼尔大人的面具背面都……！」</p><p>和亢奋的淫魔们相反，我只是一脸茫然。而巴尼尔则是兴致勃勃地对这样的我说：</p><p>「不过，汝真是个奇怪的男人啊。居然会想要这本写真集，难不成汝是吾之粉丝吗？但是，很遗憾的，吾等恶魔并没有性别之分，所以吾没办法回应汝的心意……喔喔，这又是如此极致的负面情感！真是太美味了！」</p><h2 id="特典-红魔族的抑制力" tabindex="-1"><a class="header-anchor" href="#特典-红魔族的抑制力"><span>特典 红魔族的抑制力</span></a></h2><p>觉得煮午餐很麻烦的我在外面随便吃过饭之后，没有直接回豪宅，而是在阿克塞尔的街上散步。</p><p>——这时，我看见一个认识的人贴在墙壁上，偷看著后巷的状况。</p><p>「咦？喂~~这不是芸芸吗？你在这种地方做什么啊？」</p><p>我看见的是芸芸。</p><p>「你在这种地方偷窥什么啊？有野猫还是尼禄依德在交配吗？」</p><p>「才不是呢！就算是好了，为什么我得偷窥那种东西啊！不是这样好吗，你看，你自己看那边！」</p><p>我遵照她所说，偷看了一下后巷，看见的是身穿黑色洋装的惠惠。</p><p>「什么嘛，原来你只是像平常一样在跟踪惠惠啊。」</p><p>「我平常才没有这么做！你把我当成怎样的人了啊！」</p><p>见芸芸眼中发出红光，我把食指放在嘴巴前面，以手势示意要她安静。</p><p>「太大声会被惠惠发现啦。那个家伙是怎样？既不是祭典，又没有什么活动，却穿上平常没在穿的洋装，到底想干嘛啊？我不知道她想去哪里，不过好像很有趣耶，偷偷跟著她看看好了。」</p><p>「所以说，我也是因为这样而感到好奇，才做出这样的举动……怎么搞的，被说成是跟踪狂之后，听和真先生这么说让我感到非常无法释怀……」</p><p>没有理会不知道在纠结什么的芸芸，我跟在惠惠后面沿著后巷前进。</p><p>不久之后，走在前面的惠惠好像发现了什么，并停下脚步。</p><p>「哦，看来有尼禄依德在那里交配呢。」</p><p>「尼禄依德在交配有那么奇特吗！应该说，惠惠为什么看得那么兴致勃勃啊！」</p><p>「不，有尼禄依德在交配的话任何人都会看吧。而且，说真的，尼禄依德到底是什么东西啊？」</p><p>「这个我还比较想知道呢，为什么大家可以毫无障碍地把尼禄依德做成饮料喝啊！那个到底是什么东西啊！」</p><p>——十分钟后。</p><p>「我还是第一次知道，原来尼禄依德的交配那么戏剧化……」</p><p>「惠惠都看到哭了呢……」</p><p>不只是因为情绪高涨而亮起红光，也因为感动落泪而哭红了眼睛的芸芸，一边说出这样的感想，一边跟在惠惠后面。</p><p>走出后巷之后，惠惠前往的地方是剧场。</p><p>她认真地确认贴在建筑物前面的预告海报。</p><p>「那个家伙是不是有什么想看的戏剧啊？」</p><p>「啊！我想一定是这样，她想看的大概是暴坊君主或普谭金男爵归来记的剧场版吧！暴坊君主非常好看喔，暴坊君主这部作品呢……！」</p><p>「喂，你太大声而且眼睛也变红了！你想畅谈喜欢的作品的心情我很明白，但是会被发现啦！」</p><p>——五分钟后。</p><p>「然后，前领主老爷爷这么说了。『没有面包的话吃怪物不就好了』。据说，这就是过去被视为禁忌的吃怪物行为的开端，后来籍此度过饥荒之后，各个城镇都开始推出当地的招牌怪物料理……」</p><p>「喂，惠惠要走了喔。君主的话题就聊到这里！听起来好像满有意思的所以我之后要去看，你别爆雷！」</p><p>大概是确认完戏剧情报了，惠惠开始移动，我们也跟了上去。</p><p>这时，芸芸一脸羞赧地说：</p><p>「和真先生，你对暴坊君主有兴趣啊。真是太巧了，我、我也很喜欢那部作品呢，不过，你有办法一个人进剧场吗？我已经很习惯一个人进剧场了，但这其实是很高难度行为呢。有人可以陪你一起去吗？那个，该怎么说呢，这样好像很多管闲事，我好像也没资格说这种话，不过如果你不嫌弃的话…… 」</p><p>「我去，你可以接受的话我们一起去就是了，不然我可以连惠惠也带去，所以你不要再说那种令人揪心的话了！」</p><p>这时，走在前面的惠惠忽然停下脚步，也不知道在想什么，居然跑进警察局里去了。</p><p>那个家伙打扮成那样，结果是去自首吗！</p><p>看见这一幕的我和芸芸冲进警察局里，对正在和惠惠交谈的职员说：</p><p>「对不起，我是这个家伙的保证人！这次真的非常抱歉！」</p><p>「笨蛋惠惠！你又闯了什么祸啊——————！」</p><p>——十分钟后。</p><p>「真是的！你们两个真是的！光是看到我走进警察局就联想到犯罪，也太夸张了吧！」</p><p>我想，这就是你平常的行为造成的吧。</p><p>「惠惠，对不起啦！可是，我怎么想得到惠惠居然会当起警察局的海报模特儿嘛……」</p><p>「喂，你对如此惹人怜爱的少女说那种话是什么意思，我洗耳恭听。」</p><p>没错，惠惠之所以打扮成这样，是因为接了当模特儿的委托。</p><p>「不过，没想到惠惠居然会变成警察局的代言人呢。到底是谁的口味这么特殊啊……」</p><p>「喂，口味特殊是什么意思，我洗耳恭听。」</p><p>听见我们的对话，职员表示：</p><p>「啊，这不是代言人的宣传海报喔，是性骚扰防治的海报。」</p><p>「「「咦？」」」</p><p>我们转过头去，看见了像是草稿的海报范本。</p><p>海报正中央是一名眼睛发出红光，看起来相当可怕的少女，然后……</p><p>『当心阴暗的夜路与红魔族。 』</p><p>海报上面写著这样的标语，其内文是要警告众人，如果在这个镇上被外貌蒙骗而轻易犯下性骚扰行为的话，下场可能会非常凄惨——</p><h2 id="特典-吉祥物的真面目" tabindex="-1"><a class="header-anchor" href="#特典-吉祥物的真面目"><span>特典 吉祥物的真面目……</span></a></h2><p>在豪宅院子里的一角，有颗毛球在温暖的太阳下睡午觉。</p><p>「……喂，我已经看穿你的真面目了。」</p><p>我抱著膝盖，坐在草地上，对那颗被取名为点仔的毛球这么说。</p><p>原本在睡觉的点仔听见我的声音有了反应，抬起头来。</p><p>打了一个大呵欠之后，它就缓步走到我的脚边来。</p><p>「啊，你是怎样！可别以为撒个娇就可以蒙混过关了喔！就算我是猫派，对于你的异常性，也无法再继续睁一只眼闭一只眼了！」</p><p>点仔一边呼噜著，一边用头蹭我的膝盖，而我为了不让它轻易得逞，便伸出双手抱起她娇小的身体，让它与我的视线同高。</p><p>「喂。我看你是想要取我性命的魔王军干部或是什么的吧？仔细一看，你背上长了一对小翅膀，还会吐火，最奇怪的是，你都不会长大。」</p><p>没错，尽管都已经过了一年多了，这颗小毛球却还是小猫的模样。</p><p>其他人似乎都不觉得这件事有问题，但我可不一样。</p><p>「现在只有我和你独处。好了，你也该老实招来了吧？其实你会说话对吧？而且，在满月的夜晚还会变成人类的模样或是怎样的对吧？喂，我会向大家保密，所以快点变成猫耳美少女来给我看看！」</p><p>我把脸凑到点仔面前，结果点仔也把鼻尖凑了过来，用力闻起我的味道。</p><p>……算了，无论这个家伙的真面目是什么都没关系了啦。</p><p>我在草皮上躺了下来，顺势将点仔往上抱起——</p><p>「我还想说你怎么会不见人影呢，居然在这种地方和它玩在一起。」</p><p>这时，我因为突如其来的声音看了过去，见到的是一脸傻眼的惠惠，还有简直像是找到同伴似的，以开心的眼神看向我的芸芸。</p><p>惠惠隐约显得浑身无力，看来她已经完成每天不可或缺的一日一爆裂，被芸芸送回来了吧。</p><p>「我会假装没看到你刚才抱著点仔玩得很开心的样子，所以分我一点魔力吧。」</p><p>「……不是啦。我才不是在跟它玩，这其实是有我的原因……」</p><p>我正打算说出之前一直对点仔抱持的怀疑时，芸芸握起拳头说：</p><p>「那个，我觉得跟猫说话并不是什么不好的事情！我一个人独处的时候，不但会跟狗和猫说话，还会跟鱼缸里的鱼和球藻说话呢……！」</p><p>「我都说不是了！我并不是因为一个人感到寂寞所以才跟猫说话的好吗！」</p><p>——惠惠得到我分给她的魔力之后，就和芸芸一起在我们家认真练习耍帅的招牌姿势。</p><p>「……吶，你快点向之前烤鱼的时候那样，再喷一次伙来看看吧。这样就可以证明我没说谎了。」</p><p>我用两只手交互抓著爬到我大腿上来的点仔，同时不断对它说话。</p><p>搔到它背上的翅膀时，点仔呼噜得一副很舒服的样子。</p><p>难不成长翅膀的猫在这个世界上根本不稀奇吗？</p><p>看大家都不吐槽，就让我觉得其实是自己的常识有偏差。</p><p>这时，坐在我大腿上的点仔好像发现了什么，抬起头来。</p><p>它的视线前方，有只色彩鲜艳的蚱蜢在跳来跳去。</p><p>这种地方就和一般的猫没两样。</p><p>看来拘泥在它的真面目上，好像太钻牛角尖了点。就当我一边苦笑，一边打算去摸点仔的头时……</p><p>只见点仔从嘴里「啪吱」一声发出电击，我便将伸出去的手缩了回来。</p><p>我看向维持著奇怪的招牌姿势，动也不动的两人。</p><p>「……喂～～这个家伙刚才从嘴里吐出电击耶。对于这个地方的猫而言，这是正常的事情吗？」</p><p>「嗯？猫怎么可能吐出电击啊，天还这么亮你就睡昏头了吗？」</p><p>「对……对啊。点仔只是普通的猫，才没有那种能力呢。」</p><p>和一脸淡定装傻到底的惠惠正好相反，芸芸的眼神随即游移了起来。</p><p>「……我说啊，你们两个该不会知道这颗毛球的真面目是什么吧？这个家伙到底是什么来头？这个家伙果然不是猫对吧？」</p><p>我抱起点仔递上去给她们看，结果她们两个都别开了视线。</p><p>「好了，芸芸，再来要想跟大头目对峙时的招牌台词了。对我而言，爆裂和最强这两个词汇绝对不能少」</p><p>惠惠若无其事地继续练习著，她身旁的芸芸则是故意不看我身边，同时举起魔杖……</p><p>这是，点仔突然从我怀里跳了出去，全身的毛都倒竖了起来。</p><p>仔细一看，是有只野猫闯进院子里来了。</p><p>「呜喵——！」</p><p>「呼唰——！」</p><p>点仔朝野猫直冲了出去，和它互瞪了一下之后……！</p><p>「啊啊！喂，你们看！快点看啦！点仔正在吐火吓唬野猫耶！」</p><p>「……好，练到这边就差不多了，开始实践吧！芸芸，我们上街去！」</p><p>「我我、我知道了！就让你见识一下我的练习成果吧！」</p><p>「你们想上哪去啊，你们知道那只猫是什么对不对！喂，你们问心无愧的话就转过头来看著我啊！」</p><h2 id="特典-少女的价值在于" tabindex="-1"><a class="header-anchor" href="#特典-少女的价值在于"><span>特典 少女的价值在于……</span></a></h2><p>事情发生在我在冒险者公会的酒吧吃午餐的时候。</p><p>「惠惠小姐，可以打扰你一下吗？」</p><p>号称公会招牌职员的巨乳柜台小姐突然找我搭话。</p><p>「有什么事吗？我最近应该没有做什么会被大姐姐训话的事情才对啊。」</p><p>听我这么说，大姐姐摇了摇头。</p><p>「我今天不是要训话，是有工作想要委托你。」</p><p>既然是要委托我，那目标应该相当大咖吧。</p><p>「如果是讨伐任务的话可以去跟和真说吗？要接受委托我是相当乐意，但是如果知道我擅自接下讨伐大咖悬赏怪物的任务，我肯定会被他骂。」</p><p>然而大姐姐再次摇头。</p><p>「也不是讨伐任务，我希望惠惠小姐可以配合一项魔法实验。」</p><p>——这个国家有名为魔法研究所的设施。</p><p>那种设施正如其名，日夜都在研究魔法，项目还非常广泛，像是开发新魔法以及提升魔法威力，省略咏唱以及魔力和怪物的关系等等。</p><p>而在阿克塞尔的郊外，也有这样的一个研究所……</p><p>「原来如此。也就是说，你们对于我令人畏惧的才能以及强大至极的魔力感到佩服，无论如何都想知道其中的秘密——简单来说就是这么回事吧。」</p><p>「我并没有说得那么夸张，而且想知道的是有关红魔族的事情，总之就是这么回事。」</p><p>听了我的提问，研究所的大姐姐面无表情地回答得很淡定。</p><p>红魔族原本是某个技术大国的改造人。</p><p>现在那个国家已经灭亡，而且很遗憾的，改造的技术也已经失传了。</p><p>如果能够找回那种超科技的一部分，或许就会多出一些对抗魔王军的手段，所以研究所才会决定像这样开始研究红魔族。</p><p>被叫到研究所来的我，换上白色的方衣，被带到一个大房间的中央站著。</p><p>我不知道他们到底要研究什么，不过大概是顾虑到我的感受，所以研究员全都是女性。</p><p>「那么，惠惠小姐。首先，请再次说明有关你们红魔族的事情。」</p><p>拿著笔记本的研究员用力推了一下眼镜，然后对我这么问。</p><p>「吾等红魔族，所有人生来都具备高强的魔力，而且正如你们所知，有著不同于常人的帅气名字和编码。」</p><p>流利地记录下我所说的话的研究员，在此停下动作。</p><p>「……帅气名字的部分姑且不论，不过编码这件事我还是第一次听说。那是怎么一回事呢？红魔族会给每个人一个号码吗？」</p><p>「不，不是给与的。是像这样，在出生的时候就在身上了……」</p><p>说著，我掀开方衣一脚，露出号码给她们看。</p><p>我原本并不喜欢让别人看到这个。</p><p>因为这会让我们回想起自己是改造人，是应该藏起来的东西……</p><p>「屁股上的那个，就是名字很奇怪的勇者大人所说的条码对吧？」</p><p>「原来如此，红魔族的人屁股上都有条码。」</p><p>「条码的位置是固定的吗？还是说，条码在屁股上的只有惠惠小姐呢？」</p><p>「不好意思，可以不要一直屁股来屁股去的吗？你们再提屁股我就要走人了。」</p><p>我这句话让研究员都闭上了嘴。</p><p>「……我继续说下去，红魔族正如名称的由来所示，所有人的眼睛都是红色的，而且喜欢黑色和红色等这类颜色，个性好战，因为我们是为了战斗而被制造出来的，所以动不动就和人杠上是出自于本能」</p><p>正当研究员们在笔记本上振笔疾书时，一名女性举起手问道：</p><p>「刚才看见惠惠小姐的内裤是黑色的也是出于本能吗？所以不是因为萝莉体型的你想靠内裤装大人喽？」</p><p>「是出于本能，不过可以不要提及我的内裤颜色吗？我真的会走人喔。」</p><p>这到底是在研究什么啊？</p><p>我这个疑问还没有等到解决，口头问答的时间很快就结束了。接著则是进入魔力和体能的测验。</p><p>「——不愧是红魔族，我从来没有看过如此异常的魔力数值……」</p><p>「不是有一些名字很奇怪的强大冒险者吗，有办法测出这种数值的也只有他们了吧？」</p><p>研究员测量了我的魔力之后议论纷纷了起来。</p><p>平常不太会有人因为我的魔力而如此惊奇，这让我的心情有点好。</p><p>「有没有其他实验或是问题？你们给我的报酬也不错，如果还有什么我能帮得上忙的事情，就尽管说吧。」</p><p>听心情大好的我这么说，一名研究员举起手问道：</p><p>「既然如此……王都好像有个魔道具，我们可以拿来试一下吗？据说是那些名字很奇怪怪的人带来的东西，不过目前为止几乎没有使用到那个的机会。」</p><p>「要拿我来实验没有用过的魔道具也太危险了吧。不过，如果是对人体无害的东西，倒是无所谓啦……」</p><p>听我这么说，研究员摇了摇头。</p><p>「不会不会，那个对人体无害。刚才不是有提到条码这东西吗，那个魔道具好像可以读取条码的内容。」</p><p>研究员对听了之后整个人僵住的我继续说：</p><p>「惠惠小姐屁股上的条码，可以接我们哔一下吗？」</p><p>——隔天起我当然就没有去了。</p><h2 id="gamers-特典-魔剑之勇者与空腹女孩" tabindex="-1"><a class="header-anchor" href="#gamers-特典-魔剑之勇者与空腹女孩"><span>Gamers 特典 魔剑之勇者与空腹女孩</span></a></h2><p>世上有个被称为诞生的全都是优秀魔法师的叫红魔村的村子。</p><p>「那个…小妹妹。你能再说一遍吗？」</p><p>在那个传说中的村子的酒店里，我正感到非常困惑。</p><p>「才不是小妹妹呢，我叫小米呦。听说不论谁只要是红魔族就有机会，所以我来面试了。」</p><p>「唔，这样啊，是小米酱啊。但是抱歉，哥哥我是为了和魔王战斗才来寻找能一起旅行的红魔族的。要是把小米带去一起旅行的话，你妈妈也会感到寂寞的吧。」</p><p>我直面眼前的幼女的眼神，试着用讲道理的姿态对她说。</p><p>确实，酒店的墙上贴着的募集小队成员的海报上写着只要是红魔族谁都可以，但我实在没预料到这种展开。</p><p>「妈妈也老大不小了，我觉得是时候应该让她离开孩子了。」</p><p>「唔…是我的表达方式不对。对不起啦，再怎么说要带着小米这么小的孩子一起旅行还是有点……对了，等小米再长大一点……等小米长大了，还想与魔王战斗的话，再加入我的小队吧。」</p><p>这么说着，我对小米露出笑容。</p><p>「再长大一点？明天？」</p><p>「啊，差不多再过十年吧……」</p><p>听完我的话，小米的脸上浮现出无比悲伤的表情。</p><p>……这孩子，为什么这么想和魔王战斗啊。</p><p>难道说，家人落入魔王军魔手了吗——</p><p>「再过十年，我就要被饿死了，我已经三天没吃东西了。」</p><p>看来是奔着海报上写着的高报酬和包吃包住的条件来的。</p><p>「想吃饭的话我会请你的，你能告诉我关于这个村里的人们的事吗？」</p><p>——小米简直像松鼠一样往嘴里塞满了食物说道。</p><p>「然后呢，姐姐就说要成为红魔族最强的魔法师啦，说自己毕竟是红魔族首屈一指的天才。」</p><p>「诶、诶~，这还真是强啊。比起这个小米啊，嘴里有食物的时候可不能说话哟，你可是个女孩子嘛。」</p><p>我用手帕去擦自满地说着话的小米的嘴。</p><p>小米咽下嘴里的东西说道。</p><p>「大哥哥为什么要去打倒魔王呢，被魔王做了什么过分的事吗？」</p><p>听到这天真的话语，到刚才都没留意这边对话的红魔族人们突然变得安静了。</p><p>「……我啊，是从遥远的异世界，借助某位女神的力量过来的。然后那位女神对我说，被选中的勇者啊，只有你才能拯救这个世界。快去拯救在魔王统治下水生火热的百姓吧。哈哈，这种话很难以置信对吧。」</p><p>是的，即使是被选中的我，仍然觉得被送来这个世界仿佛是在做梦一般。</p><p>刚来这个世界的时候，把这件事和认识的人说了无数遍。</p><p>但是相信我的只有我的两位同伴。这些人肯定也……</p><p>「牛逼啊！明明不是红魔族却堂堂正正地说出了这么帅气的话，这个男人不得了啊！」</p><p>「是勇者啊！真正意义上的勇者就在这里啊！」</p><p>酒店里不知为什么被喧闹覆盖了。</p><p>正当我被料想外的展开震惊到的时候，</p><p>「喂你这家伙！明明是外乡人却很懂嘛！」</p><p>「是啊，从异世界来的勇者什么的是全新版本啊！该怎么办啊，以后我的自我介绍也要加上这句…」</p><p>红魔族人们一边说着莫名其妙的话一边聚到我身边。</p><p>……这些人为什么会相信我的话啊。</p><p>「大哥哥，感觉像布克罗里一样！」</p><p>赤红的眼瞳闪着光，小米握着拳头说道。</p><p>「布克罗里？那位是谁呀？」</p><p>「不为人所知却保护着村子的，魔王军游击部队的人！」</p><p>那个叫做布克罗里的男人到底是怎样的人呢。</p><p>以自己的意志守护村子，甚至连创造了以魔王军为对手的部队！</p><p>一定是个伟大的人吧。是个优秀的魔法师。</p><p>不过，既然还有守护村子的使命，也没办法把他拉进小队吧。</p><p>「……红魔族么。你们似乎和别的人不太一样呢。」</p><p>有像这样相信着我的话语的人们，还有也不是因为被谁命令就自发与魔王军对抗的男人存在。</p><p>自己是否真的是被选中的勇者，像这样被动摇的自信如今也找回了。</p><p>从此以后，就堂堂正正地报上自己的名号吧。自己是被女神阿库娅选中的勇者。</p><p>「大哥哥太帅了！告诉我你的名字吧！」</p><p>在这个世界，自我介绍的时候，要是报上奇怪的名号就会被嘲笑。</p><p>但总感觉，这村里的可敬的各位一定不会把我的名字当做笑话的。</p><p>「——我的名字叫御剑响夜。」</p><p>……我看着大家的反应，想到果然这些人们是不同的，笑容不自禁地浮上面颊。</p><p>——来到这个世界，今天是第一次被人夸这是个帅气的名字。</p><h2 id="gamers-特典-武斗派公主的治安活动" tabindex="-1"><a class="header-anchor" href="#gamers-特典-武斗派公主的治安活动"><span>Gamers 特典 武斗派公主的治安活动</span></a></h2><p>某天下午。</p><p>「我想要来场冒险！」</p><p>爱丽丝一到活动据点就这么说。芸芸在爱丽丝自然的溜出王城后就把她带来了这里。</p><p>「……这是怎么回事？老实说，溜出王城到这偏远的城镇本身不就是场冒险了吗？」</p><p>今天只有芸芸、爱丽丝、还有我来到活动据点。</p><p>话说如此，我认为三个人去冒险的话人数有点少啊。</p><p>「走吧走吧！吶，惠惠，这是场冒险喔！」</p><p>「你这烦人的小妮子反应还真是一如既往的烦人啊。」</p><p>当对于「同伴」和「冒险」这些字眼没辙的这女孩开始发脾气时，爱丽丝握著拳头向我主张到：</p><p>「头目大人！镇上的民众一直都生活在怪物的威胁之下！既然我们拥有改变这个状况的能力，岂能成天玩耍呢？」</p><p>「没错！红魔族的力量应该被用于崇高的目标之上！」</p><p>这两人今天异常的合拍啊。</p><p>「但你们昨天不是还玩『踢罐子』玩的不亦乐乎吗？明明晚上有客人要接待，你跟芸芸却不断的说『我不想回家』还有其他一些孩子气的事。」</p><p>爱丽丝霎时变得满脸通红，芸芸则是移开了视线。</p><p>但是爱丽丝还是不气馁，并从包包中拿出了某样东西。</p><p>「我已经玩够『踢罐子』了！昨天回家后，克莱儿一直陪我玩到了半夜。更重要的是，你看看这个！」</p><p>爱丽丝边说边示意从她包包拿出的厚厚一叠纸。</p><p>我疑惑地拿起上头第一张纸并扫视了一遍。</p><p>「『每天中午，『那个』的声音都会从森林的方向传来，但最近却消失了。这使我有些挂心，因此我希望谁可以去调查一下。』……所以，这是什么？」我问。</p><p>爱丽丝一脸认真的探出身子。</p><p>「我不知道『那个』是什么，但你不觉得这很奇怪吗？不管那是什么，感觉都是不祥的预兆……而且也有可能是某种可怕的怪物住在森林里……！我们去把幕后黑手揪出来吧！」</p><p>听完爱丽丝这番说词，芸芸咕哝般地说道：</p><p>「……吶，『那个』不是从惠惠每天施展爆裂魔法的森林的方向传来的吗？那不也是我能去跟依丽丝会合的原因吗？」</p><p>「看来如此呢。为了从王城叫你出来，爱丽丝，我最近每天都在王都附近施展爆裂魔法，所以已经有一段时间没有在阿克塞尔附近施展了。到头来，幕后黑手就是你呢。」</p><p>随著芸芸与我的对话，爱丽丝好像要隐藏表情似的低下了头。</p><p>我不打算窥探她现在脸上的表情，但从她耳朵赤红的程度来看，她应该对自己非常自信地将此称为『不祥的预兆』一事感到羞耻。</p><p>不过，爱丽丝心情平复的很快。</p><p>「接、接下来是这个！『某种东西在夏天时于蓄水池住了下来。当我晚上睡不著时，我喜欢去蓄水池游个泳。但这次，我看到某种蓝色的物体在水中沉浮。那有可能是只怪物，所以请消灭它。』……城镇中央有可能住著一只怪物，更重要的是，它住在当成城镇水源的蓄水池里面。我们必须赶紧……」</p><p>「啊，那大概是阿克娅。当天气太热睡不著觉时，她总是会跑出门去。」</p><p>「我没记错的话，她最近不是有浮在池塘上打盹过吗？」</p><p>尽管爱丽丝气势十足的翻到下一页，我们马上就以真相击沉她。她再次把头低下去。</p><p>终于，在毫无自信的状态下，爱丽丝怯生生地再次翻页。</p><p>「那这个如何呢……『孤独的红眼女孩的幽灵每晚都从窗户窥视酒馆内部。』」</p><p>芸芸一听便开始哀号，并以手遮住脸。</p><p>「非常抱歉！我只是晚上感到特别孤单而已，好吗！？那酒馆总是人声鼎沸，所以我总是毫无目的在那附近游荡，希望可以吸引谁的注意……！」</p><p>「我知道你的情况就像是被诱虫灯吸引的虫子，但是身为同路人，请你别再这样做了。也太丢脸了吧！更重要的是，这是新手城镇，并不会有多少人被怪物威胁。城镇周围危险的怪物也总是被系统性的消灭了。」</p><p>「那我们做一些只有我们做得到的事吧。如果不能征服怪兽，那我们就来清剿邪恶吧！这里有一件商人控诉暴虐贵族刁难他的案子……『某位贵族强迫性的买下了我库存的医疗用史莱姆。虽然那位贵族有好好付钱，也以金钱赔偿了在艾莉丝教会等著的病人，但因为很烦人所以请做点什么吧。』」（译注：参照「外传 找面具恶魔指点迷津！」第三章，第四节）</p><p>「啊，那一定是在说你名为拉拉蒂娜的下属。」</p><p>爱丽丝将那张纸揉成一团并丢到房间的另一头。</p><p>「啊啊真是的！难道只有我认识的人在制造麻烦吗？感觉我已经完全深刻体会兄长大人的困难，深刻到我想去好好鼓励他一番了！」</p><p>当爱丽丝感到挫折而用手按著头时，一张纸轻轻地掉到她的脚边。</p><p>「请到此为止，好吗？你已经把这里搞得一团糟了。……这是最后一张，对吧？」</p><p>我捡起地上的纸，芸芸从旁开始念起纸上的内容。</p><p>「『中午的时候，有一位不工作的可疑人士带玩具给公园里的小孩们以赢取他们的青睐。』」</p><p>「……针对小孩子是犯罪对吧？虽然我认识的人很有可能做出刚刚那些案件，但是其中没有无耻到做得出这种事情的人。这次我们一定要降下正义的铁锤……！」</p><p>「『可疑人士是位黑发黑眼的冒险者……』」</p><p>「那肯定是和真。他跟我说过因为女冒险者都心有算计的在谄媚他，所以他要找些纯真的孩子，然后秀给他们看他自制的玩具，再让他们称赞自己。」</p><p>——在那之后，爱丽丝一段时间没有离开过王城。</p><h2 id="后记" tabindex="-1"><a class="header-anchor" href="#后记"><span>后记</span></a></h2><p>感谢各位这次购买《续·为美好的世界献上爆焰！》。</p><p>我想应该不至于有初次见面的人才对，我是某种类似作家的人，暁なつめ。</p><p>本书是以SNEAKER WEB网站上的连载内容，再加上新稿构成的外传小说。</p><p>由于会写出这本故事的前因后果已经在《美好世界》第十集的后记当中说明过了，所以这边就先省略，这件事情让我学习到不应该听到什么就随便答应要做。</p><p>我诚心祈祷以后不会再办角色人气票选了。</p><p>——如此这般，本书成了满载各种秘密故事的一集。</p><p>克莉丝在第七集的最后丢进湖里，现在仍在搜索中的那个神器，也已经被那个最擅长做多余事情的女神在不知情的状况下捡回家，每天用心打磨。</p><p>在克莉丝追查神器的下落，到处找遍了之后，想必会在为了喘口气而去和真他们的豪宅玩的时候瞬间找到，当场瘫坐在地吧。</p><p>如果有机会的话，未来我也想写这样的故事。</p><p>——好了，当本书陈列在书店的时候，电视动画版第二季也快要开播了吧。（注：此指日文版发售期）</p><p>这次我也很少到动画版的录音现场探班，不过作家这种生物的习性就是不想离开家里，这也是无可奈何的事情！</p><p>因为每次去参观录音就会被爆雷，这种时候还是尽可能不要参加，自己也以一个动画爱好者的身分期待动画第二季开播。</p><p>然后下个月，三嶋くろね老师也即将推出全部都是《美好世界》插画的画集。</p><p>画集当中也收录了我的小说新稿，请有兴趣的读者务必参考看看。</p><p>在各杂志上连载中的漫画也请各位多多支持了。</p><p>如此这般，这一集也是因为有以三嶋くろね老师为首的各位鼎力相助，才能够顺利出版，在此感谢大家。</p><p>最重要的，还是要向拿起本书的各位读者，再次致上最深的感谢！</p><div style="text-align:right;"><p>晓なつめ</p></div>`,506),e(m,{src:`/images/C1/15.avif`,alt:`后记插图`,width:`850`,height:`1257`},{default:i(()=>[...l[3]||=[a(`p`,null,[a(`strong`,null,`ATOGAKI`)],-1),a(`p`,null,`头目好可爱！`,-1),a(`div`,{style:{"text-align":`right`}},[a(`p`,null,[n(`*￣△￣`),a(`br`),n(` みしま くろね`),a(`br`),n(` 2017`)])],-1)]]),_:1})])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};